window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["JON"]={"book":"JON","editions":{"hbo-source":[[1,1,"וַֽ⁠יְהִי֙ דְּבַר־יְהוָ֔ה אֶל־יוֹנָ֥ה בֶן־אֲמִתַּ֖י לֵ⁠אמֹֽר׃","waֽ⁠yĕhiy֙ dĕ̇bar-yĕhwá֔h ʼel-ywòná֥h ben-ʼàmiţȧ֖y lé⁠ʼmòֽr׃"],[1,2,"ק֠וּם לֵ֧ךְ אֶל־נִֽינְוֵ֛ה הָ⁠עִ֥יר הַ⁠גְּדוֹלָ֖ה וּ⁠קְרָ֣א עָלֶ֑י⁠הָ כִּֽי־עָלְתָ֥ה רָעָתָ֖⁠ם לְ⁠פָנָֽ⁠י׃","q֠ẇm lé֧kĕ ʼel-niֽynĕwé֛h há⁠ʻi֥yr ha⁠gĕ̇dwòlá֖h ẇ⁠qĕrá֣ʼ ʻále֑y⁠há kiֽ̇y-ʻálĕţá֥h ráʻáţá֖⁠m lĕ⁠pánáֽ⁠y׃"],[1,3,"וַ⁠יָּ֤קָם יוֹנָה֙ לִ⁠בְרֹ֣חַ תַּרְשִׁ֔ישָׁ⁠ה מִ⁠לִּ⁠פְנֵ֖י יְהוָ֑ה וַ⁠יֵּ֨רֶד יָפ֜וֹ וַ⁠יִּמְצָ֥א אָנִיָּ֣ה ׀ בָּאָ֣ה תַרְשִׁ֗ישׁ וַ⁠יִּתֵּ֨ן שְׂכָרָ֜⁠הּ וַ⁠יֵּ֤רֶד בָּ⁠הּ֙ לָ⁠ב֤וֹא עִמָּ⁠הֶם֙ תַּרְשִׁ֔ישָׁ⁠ה מִ⁠לִּ⁠פְנֵ֖י יְהוָֽה׃","wa⁠yá֤̇qám ywònáh֙ li⁠bĕrò֣ẖa ţȧrĕşǐ֔yşá̌⁠h mi⁠li̇⁠pĕné֖y yĕhwá֑h wa⁠yé̇֨red yáp֜wò wa⁠yi̇mĕẕá֥ʼ ʼániyá֣̇h ׀ bá̇ʼá֣h ţarĕşǐ֗yş̌ wa⁠yi̇ţé̇֨n şĕ̂kárá֜⁠ḣ wa⁠yé֤̇red bá̇⁠ḣ֙ lá⁠b֤wòʼ ʻimá̇⁠hem֙ ţȧrĕşǐ֔yşá̌⁠h mi⁠li̇⁠pĕné֖y yĕhwáֽh׃"],[1,4,"וַֽ⁠יהוָ֗ה הֵטִ֤יל רֽוּחַ־גְּדוֹלָה֙ אֶל־הַ⁠יָּ֔ם וַ⁠יְהִ֥י סַֽעַר־גָּד֖וֹל בַּ⁠יָּ֑ם וְ⁠הָ֣⁠אֳנִיָּ֔ה חִשְּׁבָ֖ה לְ⁠הִשָּׁבֵֽר׃","waֽ⁠yhwá֗h héti֤yl rֽẇẖa-gĕ̇dwòláh֙ ʼel-ha⁠yá̇֔m wa⁠yĕhi֥y saֽʻar-gá̇d֖wòl bȧ⁠yá֑̇m wĕ⁠há֣⁠ʼoniyá̇֔h ẖişĕ̇̌bá֖h lĕ⁠hişá̇̌béֽr׃"],[1,5,"וַ⁠יִּֽירְא֣וּ הַ⁠מַּלָּחִ֗ים וַֽ⁠יִּזְעֲקוּ֮ אִ֣ישׁ אֶל־אֱלֹהָי⁠ו֒ וַ⁠יָּטִ֨לוּ אֶת־הַ⁠כֵּלִ֜ים אֲשֶׁ֤ר בָּֽ⁠אֳנִיָּה֙ אֶל־הַ⁠יָּ֔ם לְ⁠הָקֵ֖ל מֵֽ⁠עֲלֵי⁠הֶ֑ם וְ⁠יוֹנָ֗ה יָרַד֙ אֶל־יַרְכְּתֵ֣י הַ⁠סְּפִינָ֔ה וַ⁠יִּשְׁכַּ֖ב וַ⁠יֵּרָדַֽם׃","wa⁠yiֽ̇yrĕʼ֣ẇ ha⁠mȧlá̇ẖi֗ym waֽ⁠yi̇zĕʻàqẇ֮ ʼi֣yş̌ ʼel-ʼèlòháy⁠w֒ wa⁠yá̇ti֨lẇ ʼeţ-ha⁠ké̇li֜ym ʼàşě֤r báֽ̇⁠ʼoniyá̇h֙ ʼel-ha⁠yá̇֔m lĕ⁠háqé֖l méֽ⁠ʻàléy⁠he֑m wĕ⁠ywòná֗h yárad֙ ʼel-yarĕkĕ̇ţé֣y ha⁠sĕ̇piyná֔h wa⁠yi̇şĕ̌kȧ֖b wa⁠yé̇rádaֽm׃"],[1,6,"וַ⁠יִּקְרַ֤ב אֵלָי⁠ו֙ רַ֣ב הַ⁠חֹבֵ֔ל וַ⁠יֹּ֥אמֶר ל֖⁠וֹ מַה־לְּ⁠ךָ֣ נִרְדָּ֑ם ק֚וּם קְרָ֣א אֶל־אֱלֹהֶ֔י⁠ךָ אוּלַ֞י יִתְעַשֵּׁ֧ת הָ⁠אֱלֹהִ֛ים לָ֖⁠נוּ וְ⁠לֹ֥א נֹאבֵֽד׃","wa⁠yi̇qĕra֤b ʼéláy⁠w֙ ra֣b ha⁠ẖòbé֔l wa⁠yò֥̇ʼmer l֖⁠wò mah-lĕ̇⁠ká֣ nirĕdá֑̇m q֚ẇm qĕrá֣ʼ ʼel-ʼèlòhe֔y⁠ká ʼẇla֞y yiţĕʻaşé֧̇̌ţ há⁠ʼèlòhi֛ym lá֖⁠nẇ wĕ⁠lò֥ʼ nòʼbéֽd׃"],[1,7,"וַ⁠יֹּאמְר֞וּ אִ֣ישׁ אֶל־רֵעֵ֗⁠הוּ לְכוּ֙ וְ⁠נַפִּ֣ילָה גֽוֹרָל֔וֹת וְ⁠נֵ֣דְעָ֔ה בְּ⁠שֶׁ⁠לְּ⁠מִ֛י הָ⁠רָעָ֥ה הַ⁠זֹּ֖את לָ֑⁠נוּ וַ⁠יַּפִּ֨לוּ֙ גּֽוֹרָל֔וֹת וַ⁠יִּפֹּ֥ל הַ⁠גּוֹרָ֖ל עַל־יוֹנָֽה׃","wa⁠yò̇ʼmĕr֞ẇ ʼi֣yş̌ ʼel-réʻé֗⁠hẇ lĕkẇ֙ wĕ⁠napi֣̇yláh gֽwòrál֔wòţ wĕ⁠né֣dĕʻá֔h bĕ̇⁠şě⁠lĕ̇⁠mi֛y há⁠ráʻá֥h ha⁠zò֖̇ʼţ lá֑⁠nẇ wa⁠yȧpi̇֨lẇ֙ ġֽwòrál֔wòţ wa⁠yi̇pò֥̇l ha⁠ġwòrá֖l ʻal-ywònáֽh׃"],[1,8,"וַ⁠יֹּאמְר֣וּ אֵלָ֔י⁠ו הַגִּידָ⁠ה־נָּ֣א לָ֔⁠נוּ בַּ⁠אֲשֶׁ֛ר לְ⁠מִי־הָ⁠רָעָ֥ה הַ⁠זֹּ֖את לָ֑⁠נוּ מַה־מְּלַאכְתְּ⁠ךָ֙ וּ⁠מֵ⁠אַ֣יִן תָּב֔וֹא מָ֣ה אַרְצֶ֔⁠ךָ וְ⁠אֵֽי־מִ⁠זֶּ֥ה עַ֖ם אָֽתָּה׃","wa⁠yò̇ʼmĕr֣ẇ ʼélá֔y⁠w hagi̇ydá⁠h-ná֣̇ʼ lá֔⁠nẇ bȧ⁠ʼàşě֛r lĕ⁠miy-há⁠ráʻá֥h ha⁠zò֖̇ʼţ lá֑⁠nẇ mah-mĕ̇laʼkĕţĕ̇⁠ká֙ ẇ⁠mé⁠ʼa֣yin ţá̇b֔wòʼ má֣h ʼarĕẕe֔⁠ká wĕ⁠ʼéֽy-mi⁠zė֥h ʻa֖m ʼáֽţá̇h׃"],[1,9,"וַ⁠יֹּ֥אמֶר אֲלֵי⁠הֶ֖ם עִבְרִ֣י אָנֹ֑כִי וְ⁠אֶת־יְהוָ֞ה אֱלֹהֵ֤י הַ⁠שָּׁמַ֨יִם֙ אֲנִ֣י יָרֵ֔א אֲשֶׁר־עָשָׂ֥ה אֶת־הַ⁠יָּ֖ם וְ⁠אֶת־הַ⁠יַּבָּשָֽׁה׃","wa⁠yò֥̇ʼmer ʼàléy⁠he֖m ʻibĕri֣y ʼánò֑kiy wĕ⁠ʼeţ-yĕhwá֞h ʼèlòhé֤y ha⁠şá̇̌ma֨yim֙ ʼàni֣y yáré֔ʼ ʼàşěr-ʻáşá֥̂h ʼeţ-ha⁠yá֖̇m wĕ⁠ʼeţ-ha⁠yȧbá̇şáֽ̌h׃"],[1,10,"וַ⁠יִּֽירְא֤וּ הָֽ⁠אֲנָשִׁים֙ יִרְאָ֣ה גְדוֹלָ֔ה וַ⁠יֹּאמְר֥וּ אֵלָ֖י⁠ו מַה־זֹּ֣את עָשִׂ֑יתָ כִּֽי־יָדְע֣וּ הָ⁠אֲנָשִׁ֗ים כִּֽי־מִ⁠לִּ⁠פְנֵ֤י יְהוָה֙ ה֣וּא בֹרֵ֔חַ כִּ֥י הִגִּ֖יד לָ⁠הֶֽם׃","wa⁠yiֽ̇yrĕʼ֤ẇ háֽ⁠ʼànáşǐym֙ yirĕʼá֣h gĕdwòlá֔h wa⁠yò̇ʼmĕr֥ẇ ʼélá֖y⁠w mah-zò֣̇ʼţ ʻáşî֑yţá kiֽ̇y-yádĕʻ֣ẇ há⁠ʼànáşǐ֗ym kiֽ̇y-mi⁠li̇⁠pĕné֤y yĕhwáh֙ h֣ẇʼ bòré֔ẖa ki֥̇y higi֖̇yd lá⁠heֽm׃"],[1,11,"וַ⁠יֹּאמְר֤וּ אֵלָי⁠ו֙ מַה־נַּ֣עֲשֶׂה לָּ֔⁠ךְ וְ⁠יִשְׁתֹּ֥ק הַ⁠יָּ֖ם מֵֽ⁠עָלֵ֑י⁠נוּ כִּ֥י הַ⁠יָּ֖ם הוֹלֵ֥ךְ וְ⁠סֹעֵֽר׃","wa⁠yò̇ʼmĕr֤ẇ ʼéláy⁠w֙ mah-nȧ֣ʻàşêh lá̇֔⁠kĕ wĕ⁠yişĕ̌ţò֥̇q ha⁠yá֖̇m méֽ⁠ʻálé֑y⁠nẇ ki֥̇y ha⁠yá֖̇m hwòlé֥kĕ wĕ⁠sòʻéֽr׃"],[1,12,"וַ⁠יֹּ֣אמֶר אֲלֵי⁠הֶ֗ם שָׂא֨וּ⁠נִי֙ וַ⁠הֲטִילֻ֣⁠נִי אֶל־הַ⁠יָּ֔ם וְ⁠יִשְׁתֹּ֥ק הַ⁠יָּ֖ם מֵֽ⁠עֲלֵי⁠כֶ֑ם כִּ֚י יוֹדֵ֣עַ אָ֔נִי כִּ֣י בְ⁠שֶׁ⁠לִּ֔⁠י הַ⁠סַּ֧עַר הַ⁠גָּד֛וֹל הַ⁠זֶּ֖ה עֲלֵי⁠כֶֽם׃","wa⁠yò֣̇ʼmer ʼàléy⁠he֗m şá̂ʼ֨ẇ⁠niy֙ wa⁠hàtiylu֣⁠niy ʼel-ha⁠yá̇֔m wĕ⁠yişĕ̌ţò֥̇q ha⁠yá֖̇m méֽ⁠ʻàléy⁠ke֑m ki֚̇y ywòdé֣ʻa ʼá֔niy ki֣̇y bĕ⁠şě⁠li̇֔⁠y ha⁠sȧ֧ʻar ha⁠gá̇d֛wòl ha⁠zė֖h ʻàléy⁠keֽm׃"],[1,13,"וַ⁠יַּחְתְּר֣וּ הָ⁠אֲנָשִׁ֗ים לְ⁠הָשִׁ֛יב אֶל־הַ⁠יַּבָּשָׁ֖ה וְ⁠לֹ֣א יָכֹ֑לוּ כִּ֣י הַ⁠יָּ֔ם הוֹלֵ֥ךְ וְ⁠סֹעֵ֖ר עֲלֵי⁠הֶֽם׃","wa⁠yȧẖĕţĕ̇r֣ẇ há⁠ʼànáşǐ֗ym lĕ⁠háşǐ֛yb ʼel-ha⁠yȧbá̇şá֖̌h wĕ⁠lò֣ʼ yákò֑lẇ ki֣̇y ha⁠yá̇֔m hwòlé֥kĕ wĕ⁠sòʻé֖r ʻàléy⁠heֽm׃"],[1,14,"וַ⁠יִּקְרְא֨וּ אֶל־יְהוָ֜ה וַ⁠יֹּאמְר֗וּ אָנָּ֤ה יְהוָה֙ אַל־נָ֣א נֹאבְדָ֗ה בְּ⁠נֶ֨פֶשׁ֙ הָ⁠אִ֣ישׁ הַ⁠זֶּ֔ה וְ⁠אַל־תִּתֵּ֥ן עָלֵ֖י⁠נוּ דָּ֣ם נָקִ֑יא כִּֽי־אַתָּ֣ה יְהוָ֔ה כַּ⁠אֲשֶׁ֥ר חָפַ֖צְתָּ עָשִֽׂיתָ׃","wa⁠yi̇qĕrĕʼ֨ẇ ʼel-yĕhwá֜h wa⁠yò̇ʼmĕr֗ẇ ʼáná֤̇h yĕhwáh֙ ʼal-ná֣ʼ nòʼbĕdá֗h bĕ̇⁠ne֨peş̌֙ há⁠ʼi֣yş̌ ha⁠zė֔h wĕ⁠ʼal-ţi̇ţé֥̇n ʻálé֖y⁠nẇ dá֣̇m náqi֑yʼ kiֽ̇y-ʼaţá֣̇h yĕhwá֔h kȧ⁠ʼàşě֥r ẖápa֖ẕĕţá̇ ʻáşîֽyţá׃"],[1,15,"וַ⁠יִּשְׂאוּ֙ אֶת־יוֹנָ֔ה וַ⁠יְטִלֻ֖⁠הוּ אֶל־הַ⁠יָּ֑ם וַ⁠יַּעֲמֹ֥ד הַ⁠יָּ֖ם מִ⁠זַּעְפּֽ⁠וֹ׃","wa⁠yi̇şĕ̂ʼẇ֙ ʼeţ-ywòná֔h wa⁠yĕtilu֖⁠hẇ ʼel-ha⁠yá֑̇m wa⁠yȧʻàmò֥d ha⁠yá֖̇m mi⁠zȧʻĕṗֽ⁠wò׃"],[1,16,"וַ⁠יִּֽירְא֧וּ הָ⁠אֲנָשִׁ֛ים יִרְאָ֥ה גְדוֹלָ֖ה אֶת־יְהוָ֑ה וַ⁠יִּֽזְבְּחוּ־זֶ֨בַח֙ לַֽ⁠יהוָ֔ה וַֽ⁠יִּדְּר֖וּ נְדָרִֽים׃","wa⁠yiֽ̇yrĕʼ֧ẇ há⁠ʼànáşǐ֛ym yirĕʼá֥h gĕdwòlá֖h ʼeţ-yĕhwá֑h wa⁠yiֽ̇zĕbĕ̇ẖẇ-ze֨baẖ֙ laֽ⁠yhwá֔h waֽ⁠yi̇dĕ̇r֖ẇ nĕdáriֽym׃"],[1,17,"וַ⁠יְמַ֤ן יְהוָה֙ דָּ֣ג גָּד֔וֹל לִ⁠בְלֹ֖עַ אֶת־יוֹנָ֑ה וַ⁠יְהִ֤י יוֹנָה֙ בִּ⁠מְעֵ֣י הַ⁠דָּ֔ג שְׁלֹשָׁ֥ה יָמִ֖ים וּ⁠שְׁלֹשָׁ֥ה לֵילֽוֹת׃","wa⁠yĕma֤n yĕhwáh֙ dá֣̇g gá̇d֔wòl li⁠bĕlò֖ʻa ʼeţ-ywòná֑h wa⁠yĕhi֤y ywònáh֙ bi̇⁠mĕʻé֣y ha⁠dá̇֔g şĕ̌lòşá֥̌h yámi֖ym ẇ⁠şĕ̌lòşá֥̌h léylֽwòţ׃"],[2,1,"וַ⁠יִּתְפַּלֵּ֣ל יוֹנָ֔ה אֶל־יְהוָ֖ה אֱלֹהָ֑י⁠ו מִ⁠מְּעֵ֖י הַ⁠דָּגָֽה׃","wa⁠yi̇ţĕpȧlé֣̇l ywòná֔h ʼel-yĕhwá֖h ʼèlòhá֑y⁠w mi⁠mĕ̇ʻé֖y ha⁠dá̇gáֽh׃"],[2,2,"וַ⁠יֹּ֗אמֶר קָ֠רָאתִי מִ⁠צָּ֥רָה לִ֛⁠י אֶל־יְהוָ֖ה וַֽ⁠יַּעֲנֵ֑⁠נִי מִ⁠בֶּ֧טֶן שְׁא֛וֹל שִׁוַּ֖עְתִּי שָׁמַ֥עְתָּ קוֹלִֽ⁠י׃","wa⁠yò̇֗ʼmer qá֠ráʼţiy mi⁠ẕá֥̇ráh li֛⁠y ʼel-yĕhwá֖h waֽ⁠yȧʻàné֑⁠niy mi⁠bė֧ten şĕ̌ʼ֛wòl şǐwȧ֖ʻĕţi̇y şá̌ma֥ʻĕţá̇ qwòliֽ⁠y׃"],[2,3,"וַ⁠תַּשְׁלִיכֵ֤⁠נִי מְצוּלָה֙ בִּ⁠לְבַ֣ב יַמִּ֔ים וְ⁠נָהָ֖ר יְסֹבְבֵ֑⁠נִי כָּל־מִשְׁבָּרֶ֥י⁠ךָ וְ⁠גַלֶּ֖י⁠ךָ עָלַ֥⁠י עָבָֽרוּ׃","wa⁠ţȧşĕ̌liyké֤⁠niy mĕẕẇláh֙ bi̇⁠lĕba֣b yami̇֔ym wĕ⁠náhá֖r yĕsòbĕbé֑⁠niy ká̇l-mişĕ̌bá̇re֥y⁠ká wĕ⁠galė֖y⁠ká ʻála֥⁠y ʻábáֽrẇ׃"],[2,4,"וַ⁠אֲנִ֣י אָמַ֔רְתִּי נִגְרַ֖שְׁתִּי מִ⁠נֶּ֣גֶד עֵינֶ֑י⁠ךָ אַ֚ךְ אוֹסִ֣יף לְ⁠הַבִּ֔יט אֶל־הֵיכַ֖ל קָדְשֶֽׁ⁠ךָ׃","wa⁠ʼàni֣y ʼáma֔rĕţi̇y nigĕra֖şĕ̌ţi̇y mi⁠nė֣ged ʻéyne֑y⁠ká ʼa֚kĕ ʼwòsi֣yp lĕ⁠habi̇֔yt ʼel-héyka֖l qádĕşěֽ⁠ká׃"],[2,5,"אֲפָפ֤וּ⁠נִי מַ֨יִם֙ עַד־נֶ֔פֶשׁ תְּה֖וֹם יְסֹבְבֵ֑⁠נִי ס֖וּף חָב֥וּשׁ לְ⁠רֹאשִֽׁ⁠י׃","ʼàpáp֤ẇ⁠niy ma֨yim֙ ʻad-ne֔peş̌ ţĕ̇h֖wòm yĕsòbĕbé֑⁠niy s֖ẇp ẖáb֥ẇş̌ lĕ⁠ròʼşǐֽ⁠y׃"],[2,6,"לְ⁠קִצְבֵ֤י הָרִים֙ יָרַ֔דְתִּי הָ⁠אָ֛רֶץ בְּרִחֶ֥י⁠הָ בַעֲדִ֖⁠י לְ⁠עוֹלָ֑ם וַ⁠תַּ֧עַל מִ⁠שַּׁ֛חַת חַיַּ֖⁠י יְהוָ֥ה אֱלֹהָֽ⁠י׃","lĕ⁠qiẕĕbé֤y háriym֙ yára֔dĕţi̇y há⁠ʼá֛reẕ bĕ̇riẖe֥y⁠há baʻàdi֖⁠y lĕ⁠ʻwòlá֑m wa⁠ţȧ֧ʻal mi⁠şȧ֛̌ẖaţ ẖayȧ֖⁠y yĕhwá֥h ʼèlòháֽ⁠y׃"],[2,7,"בְּ⁠הִתְעַטֵּ֤ף עָלַ⁠י֙ נַפְשִׁ֔⁠י אֶת־יְהוָ֖ה זָכָ֑רְתִּי וַ⁠תָּב֤וֹא אֵלֶ֨י⁠ךָ֙ תְּפִלָּתִ֔⁠י אֶל־הֵיכַ֖ל קָדְשֶֽׁ⁠ךָ׃","bĕ̇⁠hiţĕʻaté֤̇p ʻála⁠y֙ napĕşǐ֔⁠y ʼeţ-yĕhwá֖h záká֑rĕţi̇y wa⁠ţá̇b֤wòʼ ʼéle֨y⁠ká֙ ţĕ̇pilá̇ţi֔⁠y ʼel-héyka֖l qádĕşěֽ⁠ká׃"],[2,8,"מְשַׁמְּרִ֖ים הַבְלֵי־שָׁ֑וְא חַסְדָּ֖⁠ם יַעֲזֹֽבוּ׃","mĕşǎmĕ̇ri֖ym habĕléy-şá֑̌wĕʼ ẖasĕdá֖̇⁠m yaʻàzòֽbẇ׃"],[2,9,"וַ⁠אֲנִ֗י בְּ⁠ק֤וֹל תּוֹדָה֙ אֶזְבְּחָה־לָּ֔⁠ךְ אֲשֶׁ֥ר נָדַ֖רְתִּי אֲשַׁלֵּ֑מָה יְשׁוּעָ֖תָ⁠ה לַ⁠יהוָֽה׃ס","wa⁠ʼàni֗y bĕ̇⁠q֤wòl ţ̇wòdáh֙ ʼezĕbĕ̇ẖáh-lá̇֔⁠kĕ ʼàşě֥r náda֖rĕţi̇y ʼàşǎlé֑̇máh yĕş̌ẇʻá֖ţá⁠h la⁠yhwáֽh׃s"],[2,10,"וַ⁠יֹּ֥אמֶר יְהוָ֖ה לַ⁠דָּ֑ג וַ⁠יָּקֵ֥א אֶת־יוֹנָ֖ה אֶל־הַ⁠יַּבָּשָֽׁה׃פ","wa⁠yò֥̇ʼmer yĕhwá֖h la⁠dá֑̇g wa⁠yá̇qé֥ʼ ʼeţ-ywòná֖h ʼel-ha⁠yȧbá̇şáֽ̌h׃p"],[3,1,"וַ⁠יְהִ֧י דְבַר־יְהוָ֛ה אֶל־יוֹנָ֖ה שֵׁנִ֥ית לֵ⁠אמֹֽר׃","wa⁠yĕhi֧y dĕbar-yĕhwá֛h ʼel-ywòná֖h şé̌ni֥yţ lé⁠ʼmòֽr׃"],[3,2,"ק֛וּם לֵ֥ךְ אֶל־נִֽינְוֵ֖ה הָ⁠עִ֣יר הַ⁠גְּדוֹלָ֑ה וִּ⁠קְרָ֤א אֵלֶ֨י⁠הָ֙ אֶת־הַ⁠קְּרִיאָ֔ה אֲשֶׁ֥ר אָנֹכִ֖י דֹּבֵ֥ר אֵלֶֽי⁠ךָ׃","q֛ẇm lé֥kĕ ʼel-niֽynĕwé֖h há⁠ʻi֣yr ha⁠gĕ̇dwòlá֑h wi̇⁠qĕrá֤ʼ ʼéle֨y⁠há֙ ʼeţ-ha⁠qĕ̇riyʼá֔h ʼàşě֥r ʼánòki֖y dò̇bé֥r ʼéleֽy⁠ká׃"],[3,3,"וַ⁠יָּ֣קָם יוֹנָ֗ה וַ⁠יֵּ֛לֶךְ אֶל־נִֽינְוֶ֖ה כִּ⁠דְבַ֣ר יְהוָ֑ה וְ⁠נִֽינְוֵ֗ה הָיְתָ֤ה עִיר־גְּדוֹלָה֙ לֵֽ⁠אלֹהִ֔ים מַהֲלַ֖ךְ שְׁלֹ֥שֶׁת יָמִֽים׃","wa⁠yá֣̇qám ywòná֗h wa⁠yé֛̇lekĕ ʼel-niֽynĕwe֖h ki̇⁠dĕba֣r yĕhwá֑h wĕ⁠niֽynĕwé֗h háyĕţá֤h ʻiyr-gĕ̇dwòláh֙ léֽ⁠ʼlòhi֔ym mahàla֖kĕ şĕ̌lò֥şěţ yámiֽym׃"],[3,4,"וַ⁠יָּ֤חֶל יוֹנָה֙ לָ⁠ב֣וֹא בָ⁠עִ֔יר מַהֲלַ֖ךְ י֣וֹם אֶחָ֑ד וַ⁠יִּקְרָא֙ וַ⁠יֹּאמַ֔ר ע֚וֹד אַרְבָּעִ֣ים י֔וֹם וְ⁠נִֽינְוֵ֖ה נֶהְפָּֽכֶת׃","wa⁠yá֤̇ẖel ywònáh֙ lá⁠b֣wòʼ bá⁠ʻi֔yr mahàla֖kĕ y֣wòm ʼeẖá֑d wa⁠yi̇qĕráʼ֙ wa⁠yò̇ʼma֔r ʻ֚wòd ʼarĕbá̇ʻi֣ym y֔wòm wĕ⁠niֽynĕwé֖h nehĕpáֽ̇keţ׃"],[3,5,"וַֽ⁠יַּאֲמִ֛ינוּ אַנְשֵׁ֥י נִֽינְוֵ֖ה בֵּֽ⁠אלֹהִ֑ים וַ⁠יִּקְרְאוּ־צוֹם֙ וַ⁠יִּלְבְּשׁ֣וּ שַׂקִּ֔ים מִ⁠גְּדוֹלָ֖⁠ם וְ⁠עַד־קְטַנָּֽ⁠ם׃","waֽ⁠yȧʼàmi֛ynẇ ʼanĕşé֥̌y niֽynĕwé֖h béֽ̇⁠ʼlòhi֑ym wa⁠yi̇qĕrĕʼẇ-ẕwòm֙ wa⁠yi̇lĕbĕ̇ş֣̌ẇ şâqi̇֔ym mi⁠gĕ̇dwòlá֖⁠m wĕ⁠ʻad-qĕtanáֽ̇⁠m׃"],[3,6,"וַ⁠יִּגַּ֤ע הַ⁠דָּבָר֙ אֶל־מֶ֣לֶך נִֽינְוֵ֔ה וַ⁠יָּ֨קָם֙ מִ⁠כִּסְא֔⁠וֹ וַ⁠יַּעֲבֵ֥ר אַדַּרְתּ֖⁠וֹ מֵֽ⁠עָלָ֑י⁠ו וַ⁠יְכַ֣ס שַׂ֔ק וַ⁠יֵּ֖שֶׁב עַל־הָ⁠אֵֽפֶר׃","wa⁠yi̇gȧ֤ʻ ha⁠dá̇bár֙ ʼel-me֣lek niֽynĕwé֔h wa⁠yá̇֨qám֙ mi⁠ki̇sĕʼ֔⁠wò wa⁠yȧʻàbé֥r ʼadȧrĕţ֖̇⁠wò méֽ⁠ʻálá֑y⁠w wa⁠yĕka֣s şâ֔q wa⁠yé֖̇şěb ʻal-há⁠ʼéֽper׃"],[3,7,"וַ⁠יַּזְעֵ֗ק וַ⁠יֹּ֨אמֶר֙ בְּ⁠נִֽינְוֵ֔ה מִ⁠טַּ֧עַם הַ⁠מֶּ֛לֶךְ וּ⁠גְדֹלָ֖י⁠ו לֵ⁠אמֹ֑ר הָ⁠אָדָ֨ם וְ⁠הַ⁠בְּהֵמָ֜ה הַ⁠בָּקָ֣ר וְ⁠הַ⁠צֹּ֗אן אַֽל־יִטְעֲמוּ֙ מְא֔וּמָה אַ֨ל־יִרְע֔וּ וּ⁠מַ֖יִם אַל־יִשְׁתּֽוּ׃","wa⁠yȧzĕʻé֗q wa⁠yò̇֨ʼmer֙ bĕ̇⁠niֽynĕwé֔h mi⁠tȧ֧ʻam ha⁠mė֛lekĕ ẇ⁠gĕdòlá֖y⁠w lé⁠ʼmò֑r há⁠ʼádá֨m wĕ⁠ha⁠bĕ̇hémá֜h ha⁠bá̇qá֣r wĕ⁠ha⁠ẕò̇֗ʼn ʼaֽl-yitĕʻàmẇ֙ mĕʼ֔ẇmáh ʼa֨l-yirĕʻ֔ẇ ẇ⁠ma֖yim ʼal-yişĕ̌ţֽ̇ẇ׃"],[3,8,"וְ⁠יִתְכַּסּ֣וּ שַׂקִּ֗ים הָֽ⁠אָדָם֙ וְ⁠הַ⁠בְּהֵמָ֔ה וְ⁠יִקְרְא֥וּ אֶל־אֱלֹהִ֖ים בְּ⁠חָזְקָ֑ה וְ⁠יָשֻׁ֗בוּ אִ֚ישׁ מִ⁠דַּרְכּ֣⁠וֹ הָֽ⁠רָעָ֔ה וּ⁠מִן־הֶ⁠חָמָ֖ס אֲשֶׁ֥ר בְּ⁠כַפֵּי⁠הֶֽם׃","wĕ⁠yiţĕkȧṡ֣ẇ şâqi̇֗ym háֽ⁠ʼádám֙ wĕ⁠ha⁠bĕ̇hémá֔h wĕ⁠yiqĕrĕʼ֥ẇ ʼel-ʼèlòhi֖ym bĕ̇⁠ẖázĕqá֑h wĕ⁠yáşǔ֗bẇ ʼi֚yş̌ mi⁠dȧrĕk֣̇⁠wò háֽ⁠ráʻá֔h ẇ⁠min-he⁠ẖámá֖s ʼàşě֥r bĕ̇⁠kapé̇y⁠heֽm׃"],[3,9,"מִֽי־יוֹדֵ֣עַ יָשׁ֔וּב וְ⁠נִחַ֖ם הָ⁠אֱלֹהִ֑ים וְ⁠שָׁ֛ב מֵ⁠חֲר֥וֹן אַפּ֖⁠וֹ וְ⁠לֹ֥א נֹאבֵֽד׃","miֽy-ywòdé֣ʻa yáş̌֔ẇb wĕ⁠niẖa֖m há⁠ʼèlòhi֑ym wĕ⁠şá֛̌b mé⁠ẖàr֥wòn ʼaṗ֖⁠wò wĕ⁠lò֥ʼ nòʼbéֽd׃"],[3,10,"וַ⁠יַּ֤רְא הָֽ⁠אֱלֹהִים֙ אֶֽת־מַ֣עֲשֵׂי⁠הֶ֔ם כִּי־שָׁ֖בוּ מִ⁠דַּרְכָּ֣⁠ם הָ⁠רָעָ֑ה וַ⁠יִּנָּ֣חֶם הָ⁠אֱלֹהִ֗ים עַל־הָ⁠רָעָ֛ה אֲשֶׁר־דִּבֶּ֥ר לַ⁠עֲשׂוֹת־לָ⁠הֶ֖ם וְ⁠לֹ֥א עָשָֽׂה׃","wa⁠yȧ֤rĕʼ háֽ⁠ʼèlòhiym֙ ʼeֽţ-ma֣ʻàşé̂y⁠he֔m ki̇y-şá֖̌bẇ mi⁠dȧrĕká֣̇⁠m há⁠ráʻá֑h wa⁠yi̇ná֣̇ẖem há⁠ʼèlòhi֗ym ʻal-há⁠ráʻá֛h ʼàşěr-di̇bė֥r la⁠ʻàş̂wòţ-lá⁠he֖m wĕ⁠lò֥ʼ ʻáşáֽ̂h׃"],[4,1,"וַ⁠יֵּ֥רַע אֶל־יוֹנָ֖ה רָעָ֣ה גְדוֹלָ֑ה וַ⁠יִּ֖חַר לֽ⁠וֹ׃","wa⁠yé֥̇raʻ ʼel-ywòná֖h ráʻá֣h gĕdwòlá֑h wa⁠yi֖̇ẖar lֽ⁠wò׃"],[4,2,"וַ⁠יִּתְפַּלֵּ֨ל אֶל־יְהוָ֜ה וַ⁠יֹּאמַ֗ר אָנָּ֤ה יְהוָה֙ הֲ⁠לוֹא־זֶ֣ה דְבָרִ֗⁠י עַד־הֱיוֹתִ⁠י֙ עַל־אַדְמָתִ֔⁠י עַל־כֵּ֥ן קִדַּ֖מְתִּי לִ⁠בְרֹ֣חַ תַּרְשִׁ֑ישָׁ⁠ה כִּ֣י יָדַ֗עְתִּי כִּ֤י אַתָּה֙ אֵֽל־חַנּ֣וּן וְ⁠רַח֔וּם אֶ֤רֶךְ אַפַּ֨יִם֙ וְ⁠רַב־חֶ֔סֶד וְ⁠נִחָ֖ם עַל־הָ⁠רָעָֽה׃","wa⁠yi̇ţĕpȧlé̇֨l ʼel-yĕhwá֜h wa⁠yò̇ʼma֗r ʼáná֤̇h yĕhwáh֙ hà⁠lwòʼ-ze֣h dĕbári֗⁠y ʻad-hèywòţi⁠y֙ ʻal-ʼadĕmáţi֔⁠y ʻal-ké֥̇n qidȧ֖mĕţi̇y li⁠bĕrò֣ẖa ţȧrĕşǐ֑yşá̌⁠h ki֣̇y yáda֗ʻĕţi̇y ki֤̇y ʼaţá̇h֙ ʼéֽl-ẖaṅ֣ẇn wĕ⁠raẖ֔ẇm ʼe֤rekĕ ʼapȧ֨yim֙ wĕ⁠rab-ẖe֔sed wĕ⁠niẖá֖m ʻal-há⁠ráʻáֽh׃"],[4,3,"וְ⁠עַתָּ֣ה יְהוָ֔ה קַח־נָ֥א אֶת־נַפְשִׁ֖⁠י מִמֶּ֑⁠נִּי כִּ֛י ט֥וֹב מוֹתִ֖⁠י מֵ⁠חַיָּֽ⁠י׃ס","wĕ⁠ʻaţá֣̇h yĕhwá֔h qaẖ-ná֥ʼ ʼeţ-napĕşǐ֖⁠y mimė֑⁠ni̇y ki֛̇y t֥wòb mwòţi֖⁠y mé⁠ẖayáֽ̇⁠y׃s"],[4,4,"וַ⁠יֹּ֣אמֶר יְהוָ֔ה הַ⁠הֵיטֵ֖ב חָ֥רָה לָֽ⁠ךְ׃","wa⁠yò֣̇ʼmer yĕhwá֔h ha⁠héyté֖b ẖá֥ráh láֽ⁠kĕ׃"],[4,5,"וַ⁠יֵּצֵ֤א יוֹנָה֙ מִן־הָ⁠עִ֔יר וַ⁠יֵּ֖שֶׁב מִ⁠קֶּ֣דֶם לָ⁠עִ֑יר וַ⁠יַּעַשׂ֩ ל֨⁠וֹ שָׁ֜ם סֻכָּ֗ה וַ⁠יֵּ֤שֶׁב תַּחְתֶּ֨י⁠הָ֙ בַּ⁠צֵּ֔ל עַ֚ד אֲשֶׁ֣ר יִרְאֶ֔ה מַה־יִּהְיֶ֖ה בָּ⁠עִֽיר׃","wa⁠yé̇ẕé֤ʼ ywònáh֙ min-há⁠ʻi֔yr wa⁠yé֖̇şěb mi⁠qė֣dem lá⁠ʻi֑yr wa⁠yȧʻaş̂֩ l֨⁠wò şá̌֜m suká̇֗h wa⁠yé֤̇şěb ţȧẖĕţė֨y⁠há֙ bȧ⁠ẕé̇֔l ʻa֚d ʼàşě֣r yirĕʼe֔h mah-yi̇hĕye֖h bá̇⁠ʻiֽyr׃"],[4,6,"וַ⁠יְמַ֣ן יְהוָֽה־אֱ֠לֹהִים קִיקָי֞וֹן וַ⁠יַּ֣עַל ׀ מֵ⁠עַ֣ל לְ⁠יוֹנָ֗ה לִֽ⁠הְי֥וֹת צֵל֙ עַל־רֹאשׁ֔⁠וֹ לְ⁠הַצִּ֥יל ל֖⁠וֹ מֵ⁠רָֽעָת֑⁠וֹ וַ⁠יִּשְׂמַ֥ח יוֹנָ֛ה עַל־הַ⁠קִּֽיקָי֖וֹן שִׂמְחָ֥ה גְדוֹלָֽה׃","wa⁠yĕma֣n yĕhwáֽh-ʼè֠lòhiym qiyqáy֞wòn wa⁠yȧ֣ʻal ׀ mé⁠ʻa֣l lĕ⁠ywòná֗h liֽ⁠hĕy֥wòţ ẕél֙ ʻal-ròʼş̌֔⁠wò lĕ⁠haẕi֥̇yl l֖⁠wò mé⁠ráֽʻáţ֑⁠wò wa⁠yi̇şĕ̂ma֥ẖ ywòná֛h ʻal-ha⁠qֽ̇iyqáy֖wòn şîmĕẖá֥h gĕdwòláֽh׃"],[4,7,"וַ⁠יְמַ֤ן הָֽ⁠אֱלֹהִים֙ תּוֹלַ֔עַת בַּ⁠עֲל֥וֹת הַ⁠שַּׁ֖חַר לַֽ⁠מָּחֳרָ֑ת וַ⁠תַּ֥ךְ אֶת־הַ⁠קִּֽיקָי֖וֹן וַ⁠יִּיבָֽשׁ׃","wa⁠yĕma֤n háֽ⁠ʼèlòhiym֙ ţ̇wòla֔ʻaţ bȧ⁠ʻàl֥wòţ ha⁠şȧ֖̌ẖar laֽ⁠má̇ẖorá֑ţ wa⁠ţȧ֥kĕ ʼeţ-ha⁠qiֽ̇yqáy֖wòn wa⁠yi̇ybáֽş̌׃"],[4,8,"וַ⁠יְהִ֣י ׀ כִּ⁠זְרֹ֣חַ הַ⁠שֶּׁ֗מֶשׁ וַ⁠יְמַ֨ן אֱלֹהִ֜ים ר֤וּחַ קָדִים֙ חֲרִישִׁ֔ית וַ⁠תַּ֥ךְ הַ⁠שֶּׁ֛מֶשׁ עַל־רֹ֥אשׁ יוֹנָ֖ה וַ⁠יִּתְעַלָּ֑ף וַ⁠יִּשְׁאַ֤ל אֶת־נַפְשׁ⁠וֹ֙ לָ⁠מ֔וּת וַ⁠יֹּ֕אמֶר ט֥וֹב מוֹתִ֖⁠י מֵ⁠חַיָּֽ⁠י׃","wa⁠yĕhi֣y ׀ ki̇⁠zĕrò֣ẖa ha⁠şė̌֗meş̌ wa⁠yĕma֨n ʼèlòhi֜ym r֤ẇẖa qádiym֙ ẖàriyşǐ֔yţ wa⁠ţȧ֥kĕ ha⁠şė֛̌meş̌ ʻal-rò֥ʼş̌ ywòná֖h wa⁠yi̇ţĕʻalá֑̇p wa⁠yi̇şĕ̌ʼa֤l ʼeţ-napĕş̌⁠wò֙ lá⁠m֔ẇţ wa⁠yò̇֕ʼmer t֥wòb mwòţi֖⁠y mé⁠ẖayáֽ̇⁠y׃"],[4,9,"וַ⁠יֹּ֤אמֶר אֱלֹהִים֙ אֶל־יוֹנָ֔ה הַ⁠הֵיטֵ֥ב חָרָֽה־לְ⁠ךָ֖ עַל־הַ⁠קִּֽיקָי֑וֹן וַ⁠יֹּ֕אמֶר הֵיטֵ֥ב חָֽרָה־לִ֖⁠י עַד־מָֽוֶת׃","wa⁠yò֤̇ʼmer ʼèlòhiym֙ ʼel-ywòná֔h ha⁠héyté֥b ẖáráֽh-lĕ⁠ká֖ ʻal-ha⁠qiֽ̇yqáy֑wòn wa⁠yò̇֕ʼmer héyté֥b ẖáֽráh-li֖⁠y ʻad-máֽweţ׃"],[4,10,"וַ⁠יֹּ֣אמֶר יְהוָ֔ה אַתָּ֥ה חַ֨סְתָּ֙ עַל־הַ⁠קִּ֣יקָי֔וֹן אֲשֶׁ֛ר לֹא־עָמַ֥לְתָּ בּ֖⁠וֹ וְ⁠לֹ֣א גִדַּלְתּ֑⁠וֹ שֶׁ⁠בִּן־לַ֥יְלָה הָיָ֖ה וּ⁠בִן־לַ֥יְלָה אָבָֽד׃","wa⁠yò֣̇ʼmer yĕhwá֔h ʼaţá֥̇h ẖa֨sĕţá̇֙ ʻal-ha⁠qi֣̇yqáy֔wòn ʼàşě֛r lòʼ-ʻáma֥lĕţá̇ ḃ֖⁠wò wĕ⁠lò֣ʼ gidȧlĕţ֑̇⁠wò şě⁠bi̇n-la֥yĕláh háyá֖h ẇ⁠bin-la֥yĕláh ʼábáֽd׃"],[4,11,"וַֽ⁠אֲנִי֙ לֹ֣א אָח֔וּס עַל־נִינְוֵ֖ה הָ⁠עִ֣יר הַ⁠גְּדוֹלָ֑ה אֲשֶׁ֣ר יֶשׁ־בָּ֡⁠הּ הַרְבֵּה֩ מִֽ⁠שְׁתֵּים־עֶשְׂרֵ֨ה רִבּ֜וֹ אָדָ֗ם אֲשֶׁ֤ר לֹֽא־יָדַע֙ בֵּין־יְמִינ֣⁠וֹ לִ⁠שְׂמֹאל֔⁠וֹ וּ⁠בְהֵמָ֖ה רַבָּֽה׃","waֽ⁠ʼàniy֙ lò֣ʼ ʼáẖ֔ẇs ʻal-niynĕwé֖h há⁠ʻi֣yr ha⁠gĕ̇dwòlá֑h ʼàşě֣r yeş̌-bá̇֡⁠ḣ harĕbé̇h֩ miֽ⁠şĕ̌ţé̇ym-ʻeşĕ̂ré֨h riḃ֜wò ʼádá֗m ʼàşě֤r lòֽʼ-yádaʻ֙ bé̇yn-yĕmiyn֣⁠wò li⁠şĕ̂mòʼl֔⁠wò ẇ⁠bĕhémá֖h rabáֽ̇h׃"]],"fra-lsg1910":[[1,1,"La parole de l'Éternel fut adressée à Jonas, fils d'Amitthaï, en ces mots:","La parole de l'Éternel fut adressée à Jonas, fils d'Amitthaï, en ces mots:"],[1,2,"Lève-toi, va à Ninive, la grande ville, et crie contre elle! car sa méchanceté est montée jusqu'à moi.","Lève-toi, va à Ninive, la grande ville, et crie contre elle! car sa méchanceté est montée jusqu'à moi."],[1,3,"Et Jonas se leva pour s'enfuir à Tarsis, loin de la face de l'Éternel. Il descendit à Japho, et il trouva un navire qui allait à Tarsis; il paya le prix du transport, et s'embarqua pour aller avec les passagers à Tarsis, loin de la face de l'Éternel.","Et Jonas se leva pour s'enfuir à Tarsis, loin de la face de l'Éternel. Il descendit à Japho, et il trouva un navire qui allait à Tarsis; il paya le prix du transport, et s'embarqua pour aller avec les passagers à Tarsis, loin de la face de l'Éternel."],[1,4,"Mais l'Éternel fit souffler sur la mer un vent impétueux, et il s'éleva sur la mer une grande tempête. Le navire menaçait de faire naufrage.","Mais l'Éternel fit souffler sur la mer un vent impétueux, et il s'éleva sur la mer une grande tempête. Le navire menaçait de faire naufrage."],[1,5,"Les mariniers eurent peur, ils implorèrent chacun leur dieu, et ils jetèrent dans la mer les objets qui étaient sur le navire, afin de le rendre plus léger. Jonas descendit au fond du navire, se coucha, et s'endormit profondément.","Les mariniers eurent peur, ils implorèrent chacun leur dieu, et ils jetèrent dans la mer les objets qui étaient sur le navire, afin de le rendre plus léger. Jonas descendit au fond du navire, se coucha, et s'endormit profondément."],[1,6,"Le pilote s'approcha de lui, et lui dit: Pourquoi dors-tu? Lève-toi, invoque ton Dieu! peut-être voudra-t-il penser à nous, et nous ne périrons pas.","Le pilote s'approcha de lui, et lui dit: Pourquoi dors-tu? Lève-toi, invoque ton Dieu! peut-être voudra-t-il penser à nous, et nous ne périrons pas."],[1,7,"Et ils se dirent l'un à l'autre: Venez, et tirons au sort, pour savoir qui nous attire ce malheur. Ils tirèrent au sort, et le sort tomba sur Jonas.","Et ils se dirent l'un à l'autre: Venez, et tirons au sort, pour savoir qui nous attire ce malheur. Ils tirèrent au sort, et le sort tomba sur Jonas."],[1,8,"Alors ils lui dirent: Dis-nous qui nous attire ce malheur. Quelles sont tes affaires, et d'où viens-tu? Quel est ton pays, et de quel peuple es-tu?","Alors ils lui dirent: Dis-nous qui nous attire ce malheur. Quelles sont tes affaires, et d'où viens-tu? Quel est ton pays, et de quel peuple es-tu?"],[1,9,"Il leur répondit: Je suis Hébreu, et je crains l'Éternel, le Dieu des cieux, qui a fait la mer et la terre.","Il leur répondit: Je suis Hébreu, et je crains l'Éternel, le Dieu des cieux, qui a fait la mer et la terre."],[1,10,"Ces hommes eurent une grande frayeur, et ils lui dirent: Pourquoi as-tu fait cela? Car ces hommes savaient qu'il fuyait loin de la face de l'Éternel, parce qu'il le leur avait déclaré.","Ces hommes eurent une grande frayeur, et ils lui dirent: Pourquoi as-tu fait cela? Car ces hommes savaient qu'il fuyait loin de la face de l'Éternel, parce qu'il le leur avait déclaré."],[1,11,"Ils lui dirent: Que te ferons-nous, pour que la mer se calme envers nous? Car la mer était de plus en plus orageuse.","Ils lui dirent: Que te ferons-nous, pour que la mer se calme envers nous? Car la mer était de plus en plus orageuse."],[1,12,"Il leur répondit: Prenez-moi, et jetez-moi dans la mer, et la mer se calmera envers vous; car je sais que c'est moi qui attire sur vous cette grande tempête.","Il leur répondit: Prenez-moi, et jetez-moi dans la mer, et la mer se calmera envers vous; car je sais que c'est moi qui attire sur vous cette grande tempête."],[1,13,"Ces hommes ramaient pour gagner la terre, mais ils ne le purent, parce que la mer s'agitait toujours plus contre eux.","Ces hommes ramaient pour gagner la terre, mais ils ne le purent, parce que la mer s'agitait toujours plus contre eux."],[1,14,"Alors ils invoquèrent l'Éternel, et dirent: O Éternel, ne nous fais pas périr à cause de la vie de cet homme, et ne nous charge pas du sang innocent! Car toi, Éternel, tu fais ce que tu veux.","Alors ils invoquèrent l'Éternel, et dirent: O Éternel, ne nous fais pas périr à cause de la vie de cet homme, et ne nous charge pas du sang innocent! Car toi, Éternel, tu fais ce que tu veux."],[1,15,"Puis ils prirent Jonas, et le jetèrent dans la mer. Et la fureur de la mer s'apaisa.","Puis ils prirent Jonas, et le jetèrent dans la mer. Et la fureur de la mer s'apaisa."],[1,16,"Ces hommes furent saisis d'une grande crainte de l'Éternel, et ils offrirent un sacrifice à l'Éternel, et firent des voeux.","Ces hommes furent saisis d'une grande crainte de l'Éternel, et ils offrirent un sacrifice à l'Éternel, et firent des voeux."],[1,17,"L'Éternel fit venir un grand poisson pour engloutir Jonas, et Jonas fut dans le ventre du poisson trois jours et trois nuits.","L'Éternel fit venir un grand poisson pour engloutir Jonas, et Jonas fut dans le ventre du poisson trois jours et trois nuits."],[2,1,"Jonas, dans le ventre du poisson, pria l'Éternel, son Dieu.","Jonas, dans le ventre du poisson, pria l'Éternel, son Dieu."],[2,2,"Il dit: Dans ma détresse, j'ai invoqué l'Éternel, Et il m'a exaucé; Du sein du séjour des morts j'ai crié, Et tu as entendu ma voix.","Il dit: Dans ma détresse, j'ai invoqué l'Éternel, Et il m'a exaucé; Du sein du séjour des morts j'ai crié, Et tu as entendu ma voix."],[2,3,"Tu m'as jeté dans l'abîme, dans le coeur de la mer, Et les courants d'eau m'ont environné; Toutes tes vagues et tous tes flots ont passé sur moi.","Tu m'as jeté dans l'abîme, dans le coeur de la mer, Et les courants d'eau m'ont environné; Toutes tes vagues et tous tes flots ont passé sur moi."],[2,4,"Je disais: Je suis chassé loin de ton regard! Mais je verrai encore ton saint temple.","Je disais: Je suis chassé loin de ton regard! Mais je verrai encore ton saint temple."],[2,5,"Les eaux m'ont couvert jusqu'à m'ôter la vie, L'abîme m'a enveloppé, Les roseaux ont entouré ma tête.","Les eaux m'ont couvert jusqu'à m'ôter la vie, L'abîme m'a enveloppé, Les roseaux ont entouré ma tête."],[2,6,"Je suis descendu jusqu'aux racines des montagnes, Les barres de la terre m'enfermaient pour toujours; Mais tu m'as fait remonter vivant de la fosse, Éternel, mon Dieu!","Je suis descendu jusqu'aux racines des montagnes, Les barres de la terre m'enfermaient pour toujours; Mais tu m'as fait remonter vivant de la fosse, Éternel, mon Dieu!"],[2,7,"Quand mon âme était abattue au dedans de moi, Je me suis souvenu de l'Éternel, Et ma prière est parvenue jusqu'à toi, Dans ton saint temple.","Quand mon âme était abattue au dedans de moi, Je me suis souvenu de l'Éternel, Et ma prière est parvenue jusqu'à toi, Dans ton saint temple."],[2,8,"Ceux qui s'attachent à de vaines idoles Éloignent d'eux la miséricorde.","Ceux qui s'attachent à de vaines idoles Éloignent d'eux la miséricorde."],[2,9,"Pour moi, je t'offrirai des sacrifices avec un cri d'actions de grâces, J'accomplirai les voeux que j'ai faits: Le salut vient de l'Éternel.","Pour moi, je t'offrirai des sacrifices avec un cri d'actions de grâces, J'accomplirai les voeux que j'ai faits: Le salut vient de l'Éternel."],[2,10,"L'Éternel parla au poisson, et le poisson vomit Jonas sur la terre.","L'Éternel parla au poisson, et le poisson vomit Jonas sur la terre."],[3,1,"La parole de l'Éternel fut adressée à Jonas une seconde fois, en ces mots:","La parole de l'Éternel fut adressée à Jonas une seconde fois, en ces mots:"],[3,2,"Lève-toi, va à Ninive, la grande ville, et proclames-y la publication que je t'ordonne!","Lève-toi, va à Ninive, la grande ville, et proclames-y la publication que je t'ordonne!"],[3,3,"Et Jonas se leva, et alla à Ninive, selon la parole de l'Éternel. Or Ninive était une très grande ville, de trois jours de marche.","Et Jonas se leva, et alla à Ninive, selon la parole de l'Éternel. Or Ninive était une très grande ville, de trois jours de marche."],[3,4,"Jonas fit d'abord dans la ville une journée de marche; il criait et disait: Encore quarante jours, et Ninive est détruite!","Jonas fit d'abord dans la ville une journée de marche; il criait et disait: Encore quarante jours, et Ninive est détruite!"],[3,5,"Les gens de Ninive crurent à Dieu, ils publièrent un jeûne, et se revêtirent de sacs, depuis les plus grands jusqu'aux plus petits.","Les gens de Ninive crurent à Dieu, ils publièrent un jeûne, et se revêtirent de sacs, depuis les plus grands jusqu'aux plus petits."],[3,6,"La chose parvint au roi de Ninive; il se leva de son trône, ôta son manteau, se couvrit d'un sac, et s'assit sur la cendre.","La chose parvint au roi de Ninive; il se leva de son trône, ôta son manteau, se couvrit d'un sac, et s'assit sur la cendre."],[3,7,"Et il fit faire dans Ninive cette publication, par ordre du roi et de ses grands; Que les hommes et les bêtes, les boeufs et les brebis, ne goûtent de rien, ne paissent point, et ne boivent point d'eau!","Et il fit faire dans Ninive cette publication, par ordre du roi et de ses grands; Que les hommes et les bêtes, les boeufs et les brebis, ne goûtent de rien, ne paissent point, et ne boivent point d'eau!"],[3,8,"Que les hommes et les bêtes soient couverts de sacs, qu'ils crient à Dieu avec force, et qu'ils reviennent tous de leur mauvaise voie et des actes de violence dont leurs mains sont coupables!","Que les hommes et les bêtes soient couverts de sacs, qu'ils crient à Dieu avec force, et qu'ils reviennent tous de leur mauvaise voie et des actes de violence dont leurs mains sont coupables!"],[3,9,"Qui sait si Dieu ne reviendra pas et ne se repentira pas, et s'il ne renoncera pas à son ardente colère, en sorte que nous ne périssions point?","Qui sait si Dieu ne reviendra pas et ne se repentira pas, et s'il ne renoncera pas à son ardente colère, en sorte que nous ne périssions point?"],[3,10,"Dieu vit qu'ils agissaient ainsi et qu'ils revenaient de leur mauvaise voie. Alors Dieu se repentit du mal qu'il avait résolu de leur faire, et il ne le fit pas.","Dieu vit qu'ils agissaient ainsi et qu'ils revenaient de leur mauvaise voie. Alors Dieu se repentit du mal qu'il avait résolu de leur faire, et il ne le fit pas."],[4,1,"Cela déplut fort à Jonas, et il fut irrité.","Cela déplut fort à Jonas, et il fut irrité."],[4,2,"Il implora l'Éternel, et il dit: Ah! Éternel, n'est-ce pas ce que je disais quand j'étais encore dans mon pays? C'est ce que je voulais prévenir en fuyant à Tarsis. Car je savais que tu es un Dieu compatissant et miséricordieux, lent à la colère et riche en bonté, et qui te repens du mal.","Il implora l'Éternel, et il dit: Ah! Éternel, n'est-ce pas ce que je disais quand j'étais encore dans mon pays? C'est ce que je voulais prévenir en fuyant à Tarsis. Car je savais que tu es un Dieu compatissant et miséricordieux, lent à la colère et riche en bonté, et qui te repens du mal."],[4,3,"Maintenant, Éternel, prends-moi donc la vie, car la mort m'est préférable à la vie.","Maintenant, Éternel, prends-moi donc la vie, car la mort m'est préférable à la vie."],[4,4,"L'Éternel répondit: Fais-tu bien de t'irriter?","L'Éternel répondit: Fais-tu bien de t'irriter?"],[4,5,"Et Jonas sortit de la ville, et s'assit à l'orient de la ville, Là il se fit une cabane, et s'y tint à l'ombre, jusqu'à ce qu'il vît ce qui arriverait dans la ville.","Et Jonas sortit de la ville, et s'assit à l'orient de la ville, Là il se fit une cabane, et s'y tint à l'ombre, jusqu'à ce qu'il vît ce qui arriverait dans la ville."],[4,6,"L'Éternel Dieu fit croître un ricin, qui s'éleva au-dessus de Jonas, pour donner de l'ombre sur sa tête et pour lui ôter son irritation. Jonas éprouva une grande joie à cause de ce ricin.","L'Éternel Dieu fit croître un ricin, qui s'éleva au-dessus de Jonas, pour donner de l'ombre sur sa tête et pour lui ôter son irritation. Jonas éprouva une grande joie à cause de ce ricin."],[4,7,"Mais le lendemain, à l'aurore, Dieu fit venir un ver qui piqua le ricin, et le ricin sécha.","Mais le lendemain, à l'aurore, Dieu fit venir un ver qui piqua le ricin, et le ricin sécha."],[4,8,"Au lever du soleil, Dieu fit souffler un vent chaud d'orient, et le soleil frappa la tête de Jonas, au point qu'il tomba en défaillance. Il demanda la mort, et dit: La mort m'est préférable à la vie.","Au lever du soleil, Dieu fit souffler un vent chaud d'orient, et le soleil frappa la tête de Jonas, au point qu'il tomba en défaillance. Il demanda la mort, et dit: La mort m'est préférable à la vie."],[4,9,"Dieu dit à Jonas: Fais-tu bien de t'irriter à cause du ricin? Il répondit: Je fais bien de m'irriter jusqu'à la mort.","Dieu dit à Jonas: Fais-tu bien de t'irriter à cause du ricin? Il répondit: Je fais bien de m'irriter jusqu'à la mort."],[4,10,"Et l'Éternel dit: Tu as pitié du ricin qui ne t'a coûté aucune peine et que tu n'as pas fait croître, qui est né dans une nuit et qui a péri dans une nuit.","Et l'Éternel dit: Tu as pitié du ricin qui ne t'a coûté aucune peine et que tu n'as pas fait croître, qui est né dans une nuit et qui a péri dans une nuit."],[4,11,"Et moi, je n'aurais pas pitié de Ninive, la grande ville, dans laquelle se trouvent plus de cent vingt mille hommes qui ne savent pas distinguer leur droite de leur gauche, et des animaux en grand nombre!","Et moi, je n'aurais pas pitié de Ninive, la grande ville, dans laquelle se trouvent plus de cent vingt mille hommes qui ne savent pas distinguer leur droite de leur gauche, et des animaux en grand nombre!"]],"spa-rv1909":[[1,1,"Y FUÉpalabrade JehovááJonás, hijode Amittai, diciendo:","Y FUÉpalabrade JehovááJonás, hijode Amittai, diciendo:"],[1,2,"Levántate, y veáNínive, ciudadgrande, y pregonacontraella; porquesu maldadha subidodelantede mí.","Levántate, y veáNínive, ciudadgrande, y pregonacontraella; porquesu maldadha subidodelantede mí."],[1,3,"Y Jonásse levantópara huirde la presenciade Jehováá Tarsis, y descendióá Joppe; y hallóun navíoque partía para Tarsis; y pagandosu pasajeentróen él, para irseconellos á Tarsisde delantede Jehová.","Y Jonásse levantópara huirde la presenciade Jehováá Tarsis, y descendióá Joppe; y hallóun navíoque partía para Tarsis; y pagandosu pasajeentróen él, para irseconellos á Tarsisde delantede Jehová."],[1,4,"Mas Jehováhizo levantar un granvientoenla mar, é hízose una tangrantempestadenla mar, que pensósese rompería la nave.","Mas Jehováhizo levantar un granvientoenla mar, é hízose una tangrantempestadenla mar, que pensósese rompería la nave."],[1,5,"Y los marinerostuvieron miedo, y cada unollamabaá su dios: y echaron á la marlos enseresquehabía en la nave, para descargarlade ellos. Jonásempero se había bajadoá los lados del buque, y se había echadoá dormir.","Y los marinerostuvieron miedo, y cada unollamabaá su dios: y echaron á la marlos enseresquehabía en la nave, para descargarlade ellos. Jonásempero se había bajadoá los lados del buque, y se había echadoá dormir."],[1,6,"Y el maestre de la navese llegó á él, y le dijo: ¿Quétienes, dormilón? Levántate, y clamaátu Dios; quizáél tendrá compasiónde nosotros, y nopereceremos.","Y el maestre de la navese llegó á él, y le dijo: ¿Quétienes, dormilón? Levántate, y clamaátu Dios; quizáél tendrá compasiónde nosotros, y nopereceremos."],[1,7,"Y dijeroncada unoásu compañero: Venid, y echemossuertes, para saberpor quiénnos ha venido este mal. Y echaronsuertes, y la suertecayósobreJonás.","Y dijeroncada unoásu compañero: Venid, y echemossuertes, para saberpor quiénnos ha venido este mal. Y echaronsuertes, y la suertecayósobreJonás."],[1,8,"Entonces ledijeronellos: Decláranosahorapor quénos ha venido este mal. ¿Quéoficiotienes, y de dóndevienes? ¿cuáles tutierra, y de quépuebloeres?","Entonces ledijeronellos: Decláranosahorapor quénos ha venido este mal. ¿Quéoficiotienes, y de dóndevienes? ¿cuáles tutierra, y de quépuebloeres?"],[1,9,"Y él lesrespondió: Hebreosoy, y temoá Jehová, Diosde los cielos, quehizola mary la tierra.","Y él lesrespondió: Hebreosoy, y temoá Jehová, Diosde los cielos, quehizola mary la tierra."],[1,10,"Y aquellos hombrestemieronsobremanera, y dijéronle: ¿Por quéhas hechoesto? Porqueellos entendieronquehuíade delantede Jehová, porquese lo había declarado.","Y aquellos hombrestemieronsobremanera, y dijéronle: ¿Por quéhas hechoesto? Porqueellos entendieronquehuíade delantede Jehová, porquese lo había declarado."],[1,11,"Y dijéronle: ¿Quéte haremos, para que la marse nosquiete? porquela maribaá más, y se embravecía.","Y dijéronle: ¿Quéte haremos, para que la marse nosquiete? porquela maribaá más, y se embravecía."],[1,12,"El lesrespondió: Tomadme, y echadmeá la mar, y la marse osquietará: porqueyoséquepor mí ha venido esta grandetempestadsobrevosotros.","El lesrespondió: Tomadme, y echadmeá la mar, y la marse osquietará: porqueyoséquepor mí ha venido esta grandetempestadsobrevosotros."],[1,13,"Y aquellos hombrestrabajaronpor tornarla nave átierra; mas nopudieron, porquela maribaá más, y se embravecíasobreellos.","Y aquellos hombrestrabajaronpor tornarla nave átierra; mas nopudieron, porquela maribaá más, y se embravecíasobreellos."],[1,14,"Entonces clamaronáJehová, y dijeron: Rogámosteahora, Jehová, que noperezcamosnosotros por la vidade aqueste hombre, nipongassobrenosotrosla sangreinocente: porquetú, Jehová, has hechocomo has querido.","Entonces clamaronáJehová, y dijeron: Rogámosteahora, Jehová, que noperezcamosnosotros por la vidade aqueste hombre, nipongassobrenosotrosla sangreinocente: porquetú, Jehová, has hechocomo has querido."],[1,15,"Y tomaroná Jonás, y echáronlo ála mar; y la marse quietóde su furia.","Y tomaroná Jonás, y echáronlo ála mar; y la marse quietóde su furia."],[1,16,"Y temieronaquellos hombresá Jehovácon grantemor; y ofrecieronsacrificioá Jehová, y prometieronvotos.","Y temieronaquellos hombresá Jehovácon grantemor; y ofrecieronsacrificioá Jehová, y prometieronvotos."],[1,17,"",""],[2,1,"MAS Jehováhabía prevenidoun granpezque tragaseá Jonás: y estuvoJonásen el vientre del peztresdíasy tresnoches.","MAS Jehováhabía prevenidoun granpezque tragaseá Jonás: y estuvoJonásen el vientre del peztresdíasy tresnoches."],[2,2,"Y oróJonásdesde el vientre del pezáJehovásu Dios,","Y oróJonásdesde el vientre del pezáJehovásu Dios,"],[2,3,"Y dijo: Claméde mi tribulaciónáJehová, y él me oyó; del vientredel sepulcroclamé, y mi vozoiste.","Y dijo: Claméde mi tribulaciónáJehová, y él me oyó; del vientredel sepulcroclamé, y mi vozoiste."],[2,4,"Echástemeen el profundo, en mediode los mares, y rodeómela corriente; todastus ondasy tus olaspasaronsobremí.","Echástemeen el profundo, en mediode los mares, y rodeómela corriente; todastus ondasy tus olaspasaronsobremí."],[2,5,"Y yo dije: Echadosoy de delantede tus ojos: masaunveré tu santotemplo.","Y yo dije: Echadosoy de delantede tus ojos: masaunveré tu santotemplo."],[2,6,"Las aguasme rodearonhastael alma, rodeómeel abismo; la ova se enredóá mi cabeza.","Las aguasme rodearonhastael alma, rodeómeel abismo; la ova se enredóá mi cabeza."],[2,7,"Descendíá las raíces de los montes; la tierraechósus cerraduras sobre mípara siempre: mas tú sacastemi vidade la sepultura, oh JehováDiosmío.","Descendíá las raíces de los montes; la tierraechósus cerraduras sobre mípara siempre: mas tú sacastemi vidade la sepultura, oh JehováDiosmío."],[2,8,"Cuando mi almadesfallecíaenmí, acordémede Jehová; y mi oraciónentró hastati entu santotemplo.","Cuando mi almadesfallecíaenmí, acordémede Jehová; y mi oraciónentró hastati entu santotemplo."],[2,9,"Los que guardan las vanidadesilusorias, su misericordiaabandonan.","Los que guardan las vanidadesilusorias, su misericordiaabandonan."],[2,10,"Yoempero con vozde alabanzate sacrificaré; pagarélo queprometí. La salvaciónperteneceá Jehová. Y mandóJehováal pez, y vomitóá Jonásentierra.","Yoempero con vozde alabanzate sacrificaré; pagarélo queprometí. La salvaciónperteneceá Jehová. Y mandóJehováal pez, y vomitóá Jonásentierra."],[3,1,"Y FUÉpalabrade Jehovásegundavez áJonás, diciendo:","Y FUÉpalabrade Jehovásegundavez áJonás, diciendo:"],[3,2,"Levántate, y veáNínive, aquella granciudad, y publicaenella el pregónqueyotediré.","Levántate, y veáNínive, aquella granciudad, y publicaenella el pregónqueyotediré."],[3,3,"Y levantóseJonás, y fuéá Nínive, conforme á la palabrade Jehová. Y eraNíniveciudadsobremanera grande, de tresdíasde camino.","Y levantóseJonás, y fuéá Nínive, conforme á la palabrade Jehová. Y eraNíniveciudadsobremanera grande, de tresdíasde camino."],[3,4,"Y comenzóJonásá entrarpor la ciudad, caminode undía, y pregonabadiciendo: De aquíá cuarentadíasNíniveserá destruída.","Y comenzóJonásá entrarpor la ciudad, caminode undía, y pregonabadiciendo: De aquíá cuarentadíasNíniveserá destruída."],[3,5,"Y los hombresde Nínivecreyeroná Dios, y pregonaronayuno, y vistiéronsede sacosdesde el mayorde ellos hastael menorde ellos.","Y los hombresde Nínivecreyeroná Dios, y pregonaronayuno, y vistiéronsede sacosdesde el mayorde ellos hastael menorde ellos."],[3,6,"Y llegóel negociohastael reyde Nínive, y levantósede su silla, y echóde sí su vestido, y cubriósede saco, y se sentósobreceniza.","Y llegóel negociohastael reyde Nínive, y levantósede su silla, y echóde sí su vestido, y cubriósede saco, y se sentósobreceniza."],[3,7,"E hizo pregonar y anunciaren Nínive, por mandado del reyy de sus grandes, diciendo: Hombresy animales, bueyesy ovejas, nogustencosa alguna, nose les dé alimento, nibebanagua:","E hizo pregonar y anunciaren Nínive, por mandado del reyy de sus grandes, diciendo: Hombresy animales, bueyesy ovejas, nogustencosa alguna, nose les dé alimento, nibebanagua:"],[3,8,"Y quese cubrande sacolos hombresy los animales, y clamenáDiosfuertemente: y conviértasecada unodesu malcamino, dela rapiñaqueestá en sus manos.","Y quese cubrande sacolos hombresy los animales, y clamenáDiosfuertemente: y conviértasecada unodesu malcamino, dela rapiñaqueestá en sus manos."],[3,9,"¿Quiénsabesi se volveráy arrepentiráDios, y se apartarádel furorde su ira, y nopereceremos?","¿Quiénsabesi se volveráy arrepentiráDios, y se apartarádel furorde su ira, y nopereceremos?"],[3,10,"Y vióDioslo que hicieron, quese convirtieronde sumalcamino: y arrepintiósedel malquehabía dicholes había de hacer, y nolo hizo.","Y vióDioslo que hicieron, quese convirtieronde sumalcamino: y arrepintiósedel malquehabía dicholes había de hacer, y nolo hizo."],[4,1,"PERO Jonásse apesadumbróen extremo, y enojóse.","PERO Jonásse apesadumbróen extremo, y enojóse."],[4,2,"Y oróá Jehová, y dijo: Ahora, oh Jehová, ¿noes estolo que yo decíaestandoaúnenmi tierra? Poresome precaví huyendo á Tarsis: porquesabíayo quetúeres Diosclementey piadoso, tardoá enojarte, y de grandemisericordia, y quete arrepientesdel mal.","Y oróá Jehová, y dijo: Ahora, oh Jehová, ¿noes estolo que yo decíaestandoaúnenmi tierra? Poresome precaví huyendo á Tarsis: porquesabíayo quetúeres Diosclementey piadoso, tardoá enojarte, y de grandemisericordia, y quete arrepientesdel mal."],[4,3,"Ahorapues, oh Jehová, ruégoteque me mates; porquemejorme es la muertequela vida.","Ahorapues, oh Jehová, ruégoteque me mates; porquemejorme es la muertequela vida."],[4,4,"Y Jehovále dijo: ¿Haces tú bienen enojartetanto?","Y Jehovále dijo: ¿Haces tú bienen enojartetanto?"],[4,5,"Y salióseJonásdela ciudad, y asentóhaciael orientede la ciudad, é hízose allíuna choza, y se sentódebajode ella á la sombra, hastaverquéseríade la ciudad.","Y salióseJonásdela ciudad, y asentóhaciael orientede la ciudad, é hízose allíuna choza, y se sentódebajode ella á la sombra, hastaverquéseríade la ciudad."],[4,6,"Y preparóJehováDiosuna calabacera, la cual creciósobreJonáspara que hiciesesombrasobresu cabeza, y le defendiese de su mal: y Jonásse alegrógrandementeporla calabacera.","Y preparóJehováDiosuna calabacera, la cual creciósobreJonáspara que hiciesesombrasobresu cabeza, y le defendiese de su mal: y Jonásse alegrógrandementeporla calabacera."],[4,7,"Mas Diospreparóun gusanoal venirla mañana del día siguiente, el cual hirióá la calabacera, y secóse.","Mas Diospreparóun gusanoal venirla mañana del día siguiente, el cual hirióá la calabacera, y secóse."],[4,8,"Y acaecióque al salirel sol, preparóDiosun recio vientosolano; y el solhirióáJonásen la cabeza, y desmayábase, y se deseabala muerte, diciendo: Mejorsería para mí la muerteque mi vida.","Y acaecióque al salirel sol, preparóDiosun recio vientosolano; y el solhirióáJonásen la cabeza, y desmayábase, y se deseabala muerte, diciendo: Mejorsería para mí la muerteque mi vida."],[4,9,"Entonces dijoDiosáJonás: ¿Tantote enojasporla calabacera? Y él respondió: Muchome enojo, hastala muerte.","Entonces dijoDiosáJonás: ¿Tantote enojasporla calabacera? Y él respondió: Muchome enojo, hastala muerte."],[4,10,"Y dijoJehová: Tuviste túlástima dela calabacera, en la cualnotrabajaste, nitúla hicistecrecer; que en espacio deuna nochenació, y en espacio deotra nochepereció:","Y dijoJehová: Tuviste túlástima dela calabacera, en la cualnotrabajaste, nitúla hicistecrecer; que en espacio deuna nochenació, y en espacio deotra nochepereció:"],[4,11,"¿Y notendré yopiedad deNínive, aquella grandeciudaddondehaymásdecientoy veintemilpersonasquenoconocen su mano derechani su mano izquierda, y muchosanimales?","¿Y notendré yopiedad deNínive, aquella grandeciudaddondehaymásdecientoy veintemilpersonasquenoconocen su mano derechani su mano izquierda, y muchosanimales?"]],"rus-synodal":[[1,1,"И было слово Господне к Ионе, сыну Амафиину:","I bylo slovo Gospodne k Ione, synu Amafiinu:"],[1,2,"встань, иди в Ниневию, город великий, и проповедуй в нем, ибо злодеяния его дошли до Меня.","vstanʹ, idi v Nineviû, gorod velikij, i propoveduj v nem, ibo zlodeâniâ ego došli do Menâ."],[1,3,"И встал Иона, чтобы бежать в Фарсис от лица Господня, и пришел в Иоппию, и нашел корабль, отправлявшийся в Фарсис, отдал плату за провоз и вошел в него, чтобы плыть с ними в Фарсис от лица Господа.","I vstal Iona, čtoby bežatʹ v Farsis ot lica Gospodnâ, i prišel v Ioppiû, i našel korablʹ, otpravlâvšijsâ v Farsis, otdal platu za provoz i vošel v nego, čtoby plytʹ s nimi v Farsis ot lica Gospoda."],[1,4,"Но Господь воздвиг на море крепкий ветер, и сделалась на море великая буря, и корабль готов был разбиться.","No Gospodʹ vozdvig na more krepkij veter, i sdelalasʹ na more velikaâ burâ, i korablʹ gotov byl razbitʹsâ."],[1,5,"И устрашились корабельщики, и взывали каждый к своему богу, и стали бросать в море кладь с корабля, чтобы облегчить его от нее; Иона же спустился во внутренность корабля, лег и крепко заснул.","I ustrašilisʹ korabelʹŝiki, i vzyvali každyj k svoemu bogu, i stali brosatʹ v more kladʹ s korablâ, čtoby oblegčitʹ ego ot nee; Iona že spustilsâ vo vnutrennostʹ korablâ, leg i krepko zasnul."],[1,6,"И пришел к нему начальник корабля и сказал ему: что ты спишь? встань, воззови к Богу твоему; может быть, Бог вспомнит о нас и мы не погибнем.","I prišel k nemu načalʹnik korablâ i skazal emu: čto ty spišʹ? vstanʹ, vozzovi k Bogu tvoemu; možet bytʹ, Bog vspomnit o nas i my ne pogibnem."],[1,7,"И сказали друг другу: пойдем, бросим жребии, чтобы узнать, за кого постигает нас эта беда. И бросили жребии, и пал жребий на Иону.","I skazali drug drugu: pojdem, brosim žrebii, čtoby uznatʹ, za kogo postigaet nas éta beda. I brosili žrebii, i pal žrebij na Ionu."],[1,8,"Тогда сказали ему: скажи нам, за кого постигла нас эта беда? какое твое занятие и откуда идешь ты? где твоя страна и из какого ты народа?","Togda skazali emu: skaži nam, za kogo postigla nas éta beda? kakoe tvoe zanâtie i otkuda idešʹ ty? gde tvoâ strana i iz kakogo ty naroda?"],[1,9,"И он сказал им: я Еврей, чту Господа Бога небес, сотворившего море и сушу.","I on skazal im: â Evrej, čtu Gospoda Boga nebes, sotvorivšego more i sušu."],[1,10,"И устрашились люди страхом великим и сказали ему: для чего ты это сделал? Ибо узнали эти люди, что он бежит от лица Господня, как он сам объявил им.","I ustrašilisʹ lûdi strahom velikim i skazali emu: dlâ čego ty éto sdelal? Ibo uznali éti lûdi, čto on bežit ot lica Gospodnâ, kak on sam obʺâvil im."],[1,11,"И сказали ему: что сделать нам с тобою, чтобы море утихло для нас? Ибо море не переставало волноваться.","I skazali emu: čto sdelatʹ nam s toboû, čtoby more utihlo dlâ nas? Ibo more ne perestavalo volnovatʹsâ."],[1,12,"Тогда он сказал им: возьмите меня и бросьте меня в море, и море утихнет для вас, ибо я знаю, что ради меня постигла вас эта великая буря.","Togda on skazal im: vozʹmite menâ i brosʹte menâ v more, i more utihnet dlâ vas, ibo â znaû, čto radi menâ postigla vas éta velikaâ burâ."],[1,13,"Но эти люди начали усиленно грести, чтобы пристать к земле, но не могли, потому что море все продолжало бушевать против них.","No éti lûdi načali usilenno gresti, čtoby pristatʹ k zemle, no ne mogli, potomu čto more vse prodolžalo buševatʹ protiv nih."],[1,14,"Тогда воззвали они к Господу и сказали: молим Тебя, Господи, да не погибнем за душу человека сего, и да не вменишь нам кровь невинную; ибо Ты, Господи, соделал, что угодно Тебе!","Togda vozzvali oni k Gospodu i skazali: molim Tebâ, Gospodi, da ne pogibnem za dušu čeloveka sego, i da ne vmenišʹ nam krovʹ nevinnuû; ibo Ty, Gospodi, sodelal, čto ugodno Tebe!"],[1,15,"И взяли Иону и бросили его в море, и утихло море от ярости своей.","I vzâli Ionu i brosili ego v more, i utihlo more ot ârosti svoej."],[1,16,"И устрашились эти люди Господа великим страхом, и принесли Господу жертву, и дали обеты.","I ustrašilisʹ éti lûdi Gospoda velikim strahom, i prinesli Gospodu žertvu, i dali obety."],[2,1,"И повелел Господь большому киту поглотить Иону; и был Иона во чреве этого кита три дня и три ночи.","I povelel Gospodʹ bolʹšomu kitu poglotitʹ Ionu; i byl Iona vo čreve étogo kita tri dnâ i tri noči."],[2,2,"И помолился Иона Господу Богу своему из чрева кита","I pomolilsâ Iona Gospodu Bogu svoemu iz čreva kita"],[2,3,"и сказал: к Господу воззвал я в скорби моей, и Он услышал меня; из чрева преисподней я возопил, и Ты услышал голос мой.","i skazal: k Gospodu vozzval â v skorbi moej, i On uslyšal menâ; iz čreva preispodnej â vozopil, i Ty uslyšal golos moj."],[2,4,"Ты вверг меня в глубину, в сердце моря, и потоки окружили меня, все воды Твои и волны Твои проходили надо мною.","Ty vverg menâ v glubinu, v serdce morâ, i potoki okružili menâ, vse vody Tvoi i volny Tvoi prohodili nado mnoû."],[2,5,"И я сказал: отринут я от очей Твоих, однако я опять увижу святой храм Твой.","I â skazal: otrinut â ot očej Tvoih, odnako â opâtʹ uvižu svâtoj hram Tvoj."],[2,6,"Объяли меня воды до души моей, бездна заключила меня; морскою травою обвита была голова моя.","Obʺâli menâ vody do duši moej, bezdna zaklûčila menâ; morskoû travoû obvita byla golova moâ."],[2,7,"До основания гор я нисшел, земля своими запорами навек заградила меня; но Ты, Господи Боже мой, изведешь душу мою из ада.","Do osnovaniâ gor â nisšel, zemlâ svoimi zaporami navek zagradila menâ; no Ty, Gospodi Bože moj, izvedešʹ dušu moû iz ada."],[2,8,"Когда изнемогла во мне душа моя, я вспомнил о Господе, и молитва моя дошла до Тебя, до храма святого Твоего.","Kogda iznemogla vo mne duša moâ, â vspomnil o Gospode, i molitva moâ došla do Tebâ, do hrama svâtogo Tvoego."],[2,9,"Чтущие суетных и ложных богов оставили Милосердого своего,","Čtuŝie suetnyh i ložnyh bogov ostavili Miloserdogo svoego,"],[2,10,"а я гласом хвалы принесу Тебе жертву; что обещал, исполню: у Господа спасение!","a â glasom hvaly prinesu Tebe žertvu; čto obeŝal, ispolnû: u Gospoda spasenie!"],[2,11,"И сказал Господь киту, и он изверг Иону на сушу.","I skazal Gospodʹ kitu, i on izverg Ionu na sušu."],[3,1,"И было слово Господне к Ионе вторично:","I bylo slovo Gospodne k Ione vtorično:"],[3,2,"встань, иди в Ниневию, город великий, и проповедуй в ней, что Я повелел тебе.","vstanʹ, idi v Nineviû, gorod velikij, i propoveduj v nej, čto Â povelel tebe."],[3,3,"И встал Иона и пошел в Ниневию, по слову Господню; Ниневия же была город великий у Бога, на три дня ходьбы.","I vstal Iona i pošel v Nineviû, po slovu Gospodnû; Nineviâ že byla gorod velikij u Boga, na tri dnâ hodʹby."],[3,4,"И начал Иона ходить по городу, сколько можно пройти в один день, и проповедовал, говоря: еще сорок дней – и Ниневия будет разрушена!","I načal Iona hoditʹ po gorodu, skolʹko možno projti v odin denʹ, i propovedoval, govorâ: eŝe sorok dnej – i Nineviâ budet razrušena!"],[3,5,"И поверили Ниневитяне Богу, и объявили пост, и оделись во вретища, от большого из них до малого.","I poverili Ninevitâne Bogu, i obʺâvili post, i odelisʹ vo vretiŝa, ot bolʹšogo iz nih do malogo."],[3,6,"Это слово дошло до царя Ниневии, и он встал с престола своего, и снял с себя царское облачение свое, и оделся во вретище, и сел на пепле,","Éto slovo došlo do carâ Ninevii, i on vstal s prestola svoego, i snâl s sebâ carskoe oblačenie svoe, i odelsâ vo vretiŝe, i sel na peple,"],[3,7,"и повелел провозгласить и сказать в Ниневии от имени царя и вельмож его: «чтобы ни люди, ни скот, ни волы, ни овцы ничего не ели, не ходили на пастбище и воды не пили,","i povelel provozglasitʹ i skazatʹ v Ninevii ot imeni carâ i velʹmož ego: «čtoby ni lûdi, ni skot, ni voly, ni ovcy ničego ne eli, ne hodili na pastbiŝe i vody ne pili,"],[3,8,"и чтобы покрыты были вретищем люди и скот и крепко вопияли к Богу, и чтобы каждый обратился от злого пути своего и от насилия рук своих.","i čtoby pokryty byli vretiŝem lûdi i skot i krepko vopiâli k Bogu, i čtoby každyj obratilsâ ot zlogo puti svoego i ot nasiliâ ruk svoih."],[3,9,"Кто знает, может быть, еще Бог умилосердится и отвратит от нас пылающий гнев Свой, и мы не погибнем».","Kto znaet, možet bytʹ, eŝe Bog umiloserditsâ i otvratit ot nas pylaûŝij gnev Svoj, i my ne pogibnem»."],[3,10,"И увидел Бог дела их, что они обратились от злого пути своего, и пожалел Бог о бедствии, о котором сказал, что наведет на них, и не навел.","I uvidel Bog dela ih, čto oni obratilisʹ ot zlogo puti svoego, i požalel Bog o bedstvii, o kotorom skazal, čto navedet na nih, i ne navel."],[4,1,"Иона сильно огорчился этим и был раздражен.","Iona silʹno ogorčilsâ étim i byl razdražen."],[4,2,"И молился он Господу и сказал: о, Господи! не это ли говорил я, когда еще был в стране моей? Потому я и побежал в Фарсис, ибо знал, что Ты Бог благий и милосердый, долготерпеливый и многомилостивый и сожалеешь о бедствии.","I molilsâ on Gospodu i skazal: o, Gospodi! ne éto li govoril â, kogda eŝe byl v strane moej? Potomu â i pobežal v Farsis, ibo znal, čto Ty Bog blagij i miloserdyj, dolgoterpelivyj i mnogomilostivyj i sožaleešʹ o bedstvii."],[4,3,"И ныне, Господи, возьми душу мою от меня, ибо лучше мне умереть, нежели жить.","I nyne, Gospodi, vozʹmi dušu moû ot menâ, ibo lučše mne umeretʹ, neželi žitʹ."],[4,4,"И сказал Господь: неужели это огорчило тебя так сильно?","I skazal Gospodʹ: neuželi éto ogorčilo tebâ tak silʹno?"],[4,5,"И вышел Иона из города, и сел с восточной стороны у города, и сделал себе там кущу, и сел под нею в тени, чтобы увидеть, что будет с городом.","I vyšel Iona iz goroda, i sel s vostočnoj storony u goroda, i sdelal sebe tam kuŝu, i sel pod neû v teni, čtoby uvidetʹ, čto budet s gorodom."],[4,6,"И произрастил Господь Бог растение, и оно поднялось над Ионою, чтобы над головою его была тень и чтобы избавить его от огорчения его; Иона весьма обрадовался этому растению.","I proizrastil Gospodʹ Bog rastenie, i ono podnâlosʹ nad Ionoû, čtoby nad golovoû ego byla tenʹ i čtoby izbavitʹ ego ot ogorčeniâ ego; Iona vesʹma obradovalsâ étomu rasteniû."],[4,7,"И устроил Бог так, что на другой день при появлении зари червь подточил растение, и оно засохло.","I ustroil Bog tak, čto na drugoj denʹ pri poâvlenii zari červʹ podtočil rastenie, i ono zasohlo."],[4,8,"Когда же взошло солнце, навел Бог знойный восточный ветер, и солнце стало палить голову Ионы, так что он изнемог и просил себе смерти, и сказал: лучше мне умереть, нежели жить.","Kogda že vzošlo solnce, navel Bog znojnyj vostočnyj veter, i solnce stalo palitʹ golovu Iony, tak čto on iznemog i prosil sebe smerti, i skazal: lučše mne umeretʹ, neželi žitʹ."],[4,9,"И сказал Бог Ионе: неужели так сильно огорчился ты за растение? Он сказал: очень огорчился, даже до смерти.","I skazal Bog Ione: neuželi tak silʹno ogorčilsâ ty za rastenie? On skazal: očenʹ ogorčilsâ, daže do smerti."],[4,10,"Тогда сказал Господь: ты сожалеешь о растении, над которым ты не трудился и которого не растил, которое в одну ночь выросло и в одну же ночь и пропало:","Togda skazal Gospodʹ: ty sožaleešʹ o rastenii, nad kotorym ty ne trudilsâ i kotorogo ne rastil, kotoroe v odnu nočʹ vyroslo i v odnu že nočʹ i propalo:"],[4,11,"Мне ли не пожалеть Ниневии, города великого, в котором более ста двадцати тысяч человек, не умеющих отличить правой руки от левой, и множество скота?","Mne li ne požaletʹ Ninevii, goroda velikogo, v kotorom bolee sta dvadcati tysâč čelovek, ne umeûŝih otličitʹ pravoj ruki ot levoj, i množestvo skota?"]],"cmn-cuv-hant":[[1,1,"耶和華的話臨到 亞米太的兒子 約拿，說：","yé hé huá de huà lín dào yà mǐ tài de ér zǐ yuē ná， shuō："],[1,2,"「你起來往 尼尼微大城去，向其中的居民呼喊，因為他們的惡達到我面前。」","‘nǐ qǐ lái wǎng ní ní wēi dà chéng qù， xiàng qí zhōng de jū mín hū hǎn， yīn wèi tā men de è dá dào wǒ miàn qián.’"],[1,3,"約拿卻起來，逃往 他施去躲避耶和華；下到 約帕，遇見一隻船，要往 他施去。他就給了船價，上了船，要與船上的人同往 他施去躲避耶和華。","yuē ná què qǐ lái， táo wǎng tā shī qù duǒ bì yé hé huá； xià dào yuē pà， yù jiàn yī zhī chuán， yào wǎng tā shī qù. tā jiù gěi le chuán jià， shàng le chuán， yào yǔ chuán shàng de rén tóng wǎng tā shī qù duǒ bì yé hé huá."],[1,4,"然而耶和華使海中起大風，海就狂風大作，甚至船幾乎破壞。","rán ér yé hé huá shǐ hǎi zhōng qǐ dà fēng， hǎi jiù kuáng fēng dà zuò， shèn zhì chuán jǐ hū pò huài."],[1,5,"水手便懼怕，各人哀求自己的神。他們將船上的貨物拋在海中，為要使船輕些。 約拿已下到底艙，躺臥沉睡。","shuǐ shǒu biàn jù pà， gè rén āi qiú zì jǐ de shén. tā men jiāng chuán shàng de huò wù pāo zài hǎi zhōng， wèi yào shǐ chuán qīng xiē. yuē ná yǐ xià dào dǐ cāng， tǎng wò chén shuì."],[1,6,"船主到他那裏對他說：「你這沉睡的人哪，為何這樣呢？起來，求告你的神，或者神顧念我們，使我們不致滅亡。」","chuán zhǔ dào tā nà lǐ duì tā shuō：‘nǐ zhè chén shuì de rén nǎ， wèi hé zhè yàng ne？ qǐ lái， qiú gào nǐ de shén， huò zhě shén gù niàn wǒ men， shǐ wǒ men bù zhì miè wáng.’"],[1,7,"船上的人彼此說：「來吧，我們掣籤，看看這災臨到我們是因誰的緣故。」於是他們掣籤，掣出 約拿來。","chuán shàng de rén bǐ cǐ shuō：‘lái ba， wǒ men chè qiān， kàn kàn zhè zāi lín dào wǒ men shì yīn shuí de yuán gù.’ yú shì tā men chè qiān， chè chū yuē ná lái."],[1,8,"眾人對他說：「請你告訴我們，這災臨到我們是因誰的緣故？你以何事為業？你從哪裏來？你是哪一國？屬哪一族的人？」","zhòng rén duì tā shuō：‘qǐng nǐ gào sù wǒ men， zhè zāi lín dào wǒ men shì yīn shuí de yuán gù？ nǐ yǐ hé shì wèi yè？ nǐ cóng nǎ lǐ lái？ nǐ shì nǎ yī guó？ shǔ nǎ yī zú de rén？’"],[1,9,"他說：「我是 希伯來人。我敬畏耶和華－那創造滄海旱地之天上的神。」","tā shuō：‘wǒ shì xī bó lái rén. wǒ jìng wèi yé hé huá－nà chuàng zào cāng hǎi hàn de zhī tiān shàng de shén.’"],[1,10,"他們就大大懼怕，對他說：「你做的是甚麼事呢？」他們已經知道他躲避耶和華，因為他告訴了他們。","tā men jiù dà dà jù pà， duì tā shuō：‘nǐ zuò de shì shèn me shì ne？’ tā men yǐ jīng zhī dào tā duǒ bì yé hé huá， yīn wèi tā gào sù le tā men."],[1,11,"他們問他說：「我們當向你怎樣行，使海浪平靜呢？」這話是因海浪越發翻騰。","tā men wèn tā shuō：‘wǒ men dāng xiàng nǐ zěn yàng xíng， shǐ hǎi làng píng jìng ne？’ zhè huà shì yīn hǎi làng yuè fā fān téng."],[1,12,"他對他們說：「你們將我抬起來，拋在海中，海就平靜了；我知道你們遭這大風是因我的緣故。」","tā duì tā men shuō：‘nǐ men jiāng wǒ tái qǐ lái， pāo zài hǎi zhōng， hǎi jiù píng jìng le； wǒ zhī dào nǐ men zāo zhè dà fēng shì yīn wǒ de yuán gù.’"],[1,13,"然而那些人竭力盪槳，要把船攏岸，卻是不能，因為海浪越發向他們翻騰。","rán ér nà xiē rén jié lì dàng jiǎng， yào bǎ chuán lǒng àn， què shì bù néng， yīn wèi hǎi làng yuè fā xiàng tā men fān téng."],[1,14,"他們便求告耶和華說：「耶和華啊，我們懇求你，不要因這人的性命使我們死亡，不要使流無辜血的罪歸與我們；因為你－耶和華是隨自己的意旨行事。」","tā men biàn qiú gào yé hé huá shuō：‘yé hé huá a， wǒ men kěn qiú nǐ， bù yào yīn zhè rén de xìng mìng shǐ wǒ men sǐ wáng， bù yào shǐ liú wú gū xuè de zuì guī yǔ wǒ men； yīn wèi nǐ－yé hé huá shì suí zì jǐ de yì zhǐ xíng shì.’"],[1,15,"他們遂將 約拿抬起，拋在海中，海的狂浪就平息了。","tā men suì jiāng yuē ná tái qǐ， pāo zài hǎi zhōng， hǎi de kuáng làng jiù píng xī le."],[1,16,"那些人便大大敬畏耶和華，向耶和華獻祭，並且許願。","nà xiē rén biàn dà dà jìng wèi yé hé huá， xiàng yé hé huá xiàn jì， bìng qiě xǔ yuàn."],[1,17,"耶和華安排一條大魚吞了 約拿，他在魚腹中三日三夜。","yé hé huá ān pái yī tiáo dà yú tūn le yuē ná， tā zài yú fù zhōng sān rì sān yè."],[2,1,"約拿在魚腹中禱告耶和華－他的神，","yuē ná zài yú fù zhōng dǎo gào yé hé huá－tā de shén，"],[2,2,"說： 我遭遇患難求告耶和華， 你就應允我； 從陰間的深處呼求， 你就俯聽我的聲音。","shuō： wǒ zāo yù huàn nán qiú gào yé hé huá， nǐ jiù yīng yǔn wǒ； cóng yīn jiān de shēn chù hū qiú， nǐ jiù fǔ tīng wǒ de shēng yīn."],[2,3,"你將我投下深淵， 就是海的深處； 大水環繞我， 你的波浪洪濤都漫過我身。","nǐ jiāng wǒ tóu xià shēn yuān， jiù shì hǎi de shēn chù； dà shuǐ huán rào wǒ， nǐ de bō làng hóng tāo dōu màn guò wǒ shēn."],[2,4,"我說：我從你眼前雖被驅逐， 我仍要仰望你的聖殿。","wǒ shuō： wǒ cóng nǐ yǎn qián suī bèi qū zhú， wǒ réng yào yǎng wàng nǐ de shèng diàn."],[2,5,"諸水環繞我，幾乎淹沒我； 深淵圍住我； 海草纏繞我的頭。","zhū shuǐ huán rào wǒ， jǐ hū yān méi wǒ； shēn yuān wéi zhù wǒ； hǎi cǎo chán rào wǒ de tóu."],[2,6,"我下到山根， 地的門將我永遠 關住。 耶和華－我的神啊， 你卻將我的性命從坑中救出來。","wǒ xià dào shān gēn， de de mén jiāng wǒ yǒng yuǎn guān zhù. yé hé huá－wǒ de shén a， nǐ què jiāng wǒ de xìng mìng cóng kēng zhōng jiù chū lái."],[2,7,"我心在我裏面發昏的時候， 我就想念耶和華。 我的禱告進入你的聖殿， 達到你的面前。","wǒ xīn zài wǒ lǐ miàn fā hūn de shí hòu， wǒ jiù xiǎng niàn yé hé huá. wǒ de dǎo gào jìn rù nǐ de shèng diàn， dá dào nǐ de miàn qián."],[2,8,"那信奉虛無 之神的人， 離棄憐愛他們的主；","nà xìn fèng xū wú zhī shén de rén， lí qì lián ài tā men de zhǔ；"],[2,9,"但我必用感謝的聲音獻祭與你。 我所許的願，我必償還。 救恩出於耶和華。","dàn wǒ bì yòng gǎn xiè de shēng yīn xiàn jì yǔ nǐ. wǒ suǒ xǔ de yuàn， wǒ bì cháng hái. jiù ēn chū yú yé hé huá."],[2,10,"耶和華吩咐魚，魚就把 約拿吐在旱地上。","yé hé huá fēn fù yú， yú jiù bǎ yuē ná tǔ zài hàn de shàng."],[3,1,"耶和華的話二次臨到 約拿說：","yé hé huá de huà èr cì lín dào yuē ná shuō："],[3,2,"「你起來！往 尼尼微大城去，向其中的居民宣告我所吩咐你的話。」","‘nǐ qǐ lái！ wǎng ní ní wēi dà chéng qù， xiàng qí zhōng de jū mín xuān gào wǒ suǒ fēn fù nǐ de huà.’"],[3,3,"約拿便照耶和華的話起來，往 尼尼微去。這 尼尼微是極大的城，有三日的路程。","yuē ná biàn zhào yé hé huá de huà qǐ lái， wǎng ní ní wēi qù. zhè ní ní wēi shì jí dà de chéng， yǒu sān rì de lù chéng."],[3,4,"約拿進城走了一日，宣告說：「再等四十日， 尼尼微必傾覆了！」","yuē ná jìn chéng zǒu le yī rì， xuān gào shuō：‘zài děng sì shí rì， ní ní wēi bì qīng fù le！’"],[3,5,"尼尼微人信服神，便宣告禁食，從最大的到至小的都穿麻衣。","ní ní wēi rén xìn fú shén， biàn xuān gào jìn shí， cóng zuì dà de dào zhì xiǎo de dōu chuān má yī."],[3,6,"這信息傳到 尼尼微王的耳中，他就下了寶座，脫下朝服，披上麻布，坐在灰中。","zhè xìn xī chuán dào ní ní wēi wáng de ěr zhōng， tā jiù xià le bǎo zuò， tuō xià cháo fú， pī shàng má bù， zuò zài huī zhōng."],[3,7,"他又使人遍告 尼尼微通城，說：「王和大臣有令，人不可嘗甚麼，牲畜、牛羊不可吃草，也不可喝水。","tā yòu shǐ rén biàn gào ní ní wēi tōng chéng， shuō：‘wáng hé dà chén yǒu lìng， rén bù kě cháng shèn me， shēng chù, niú yáng bù kě chī cǎo， yě bù kě hē shuǐ."],[3,8,"人與牲畜都當披上麻布；人要切切求告神。各人回頭離開所行的惡道，丟棄手中的強暴。","rén yǔ shēng chù dōu dāng pī shàng má bù； rén yào qiè qiè qiú gào shén. gè rén huí tóu lí kāi suǒ xíng de è dào， diū qì shǒu zhōng de qiáng bào."],[3,9,"或者神轉意後悔，不發烈怒，使我們不致滅亡，也未可知。」","huò zhě shén zhuǎn yì hòu huǐ， bù fā liè nù， shǐ wǒ men bù zhì miè wáng， yě wèi kě zhī.’"],[3,10,"於是神察看他們的行為，見他們離開惡道，他就後悔，不把所說的災禍降與他們了。","yú shì shén chá kàn tā men de xíng wèi， jiàn tā men lí kāi è dào， tā jiù hòu huǐ， bù bǎ suǒ shuō de zāi huò jiàng yǔ tā men le."],[4,1,"這事 約拿大大不悅，且甚發怒，","zhè shì yuē ná dà dà bù yuè， qiě shèn fā nù，"],[4,2,"就禱告耶和華說：「耶和華啊，我在本國的時候豈不是這樣說嗎？我知道你是有恩典、有憐憫的神，不輕易發怒，有豐盛的慈愛，並且後悔不降所說的災，所以我急速逃往 他施去。","jiù dǎo gào yé hé huá shuō：‘yé hé huá a， wǒ zài běn guó de shí hòu qǐ bù shì zhè yàng shuō ma？ wǒ zhī dào nǐ shì yǒu ēn diǎn, yǒu lián mǐn de shén， bù qīng yì fā nù， yǒu fēng shèng de cí ài， bìng qiě hòu huǐ bù jiàng suǒ shuō de zāi， suǒ yǐ wǒ jí sù táo wǎng tā shī qù."],[4,3,"耶和華啊，現在求你取我的命吧！因為我死了比活着還好。」","yé hé huá a， xiàn zài qiú nǐ qǔ wǒ de mìng ba！ yīn wèi wǒ sǐ le bǐ huó zhe hái hǎo.’"],[4,4,"耶和華說：「你這樣發怒合乎理嗎？」","yé hé huá shuō：‘nǐ zhè yàng fā nù hé hū lǐ ma？’"],[4,5,"於是 約拿出城，坐在城的東邊，在那裏為自己搭了一座棚，坐在棚的蔭下，要看看那城究竟如何。","yú shì yuē ná chū chéng， zuò zài chéng de dōng biān， zài nà lǐ wèi zì jǐ dā le yī zuò péng， zuò zài péng de yīn xià， yào kàn kàn nà chéng jiū jìng rú hé."],[4,6,"耶和華神安排一棵蓖麻，使其發生高過 約拿，影兒遮蓋他的頭，救他脫離苦楚； 約拿因這棵蓖麻大大喜樂。","yé hé huá shén ān pái yī kē bì má， shǐ qí fā shēng gāo guò yuē ná， yǐng ér zhē gài tā de tóu， jiù tā tuō lí kǔ chǔ； yuē ná yīn zhè kē bì má dà dà xǐ lè."],[4,7,"次日黎明，神卻安排一條蟲子咬這蓖麻，以致枯槁。","cì rì lí míng， shén què ān pái yī tiáo chóng zǐ yǎo zhè bì má， yǐ zhì kū gǎo."],[4,8,"日頭出來的時候，神安排炎熱的東風，日頭曝曬 約拿的頭，使他發昏，他就為自己求死，說：「我死了比活着還好！」","rì tóu chū lái de shí hòu， shén ān pái yán rè de dōng fēng， rì tóu pù shài yuē ná de tóu， shǐ tā fā hūn， tā jiù wèi zì jǐ qiú sǐ， shuō：‘wǒ sǐ le bǐ huó zhe hái hǎo！’"],[4,9,"神對 約拿說：「你因這棵蓖麻發怒合乎理嗎？」他說：「我發怒以至於死，都合乎理！」","shén duì yuē ná shuō：‘nǐ yīn zhè kē bì má fā nù hé hū lǐ ma？’ tā shuō：‘wǒ fā nù yǐ zhì yú sǐ， dōu hé hū lǐ！’"],[4,10,"耶和華說：「這蓖麻不是你栽種的，也不是你培養的；一夜發生，一夜乾死，你尚且愛惜；","yé hé huá shuō：‘zhè bì má bù shì nǐ zāi zhǒng de， yě bù shì nǐ péi yǎng de； yī yè fā shēng， yī yè qián sǐ， nǐ shàng qiě ài xī；"],[4,11,"何況這 尼尼微大城，其中不能分辨左手右手的有十二萬多人，並有許多牲畜，我豈能不愛惜呢？」","hé kuàng zhè ní ní wēi dà chéng， qí zhōng bù néng fēn biàn zuǒ shǒu yòu shǒu de yǒu shí èr wàn duō rén， bìng yǒu xǔ duō shēng chù， wǒ qǐ néng bù ài xī ne？’"]],"arb-vandyck":[[1,1,"وَصَارَ قَوْلُ ٱلرَّبِّ إِلَى يُونَانَ بْنِ أَمِتَّايَ قَائِلًا:","waṣāra qaẘlu ٱlrãbĩ ại̹lay̱ yūnāna b̊ni ạảmitãạya qāyỉlaⁿạ:"],[1,2,"«قُمِ ٱذْهَبْ إِلَى نِينَوَى ٱلْمَدِينَةِ ٱلْعَظِيمَةِ وَنَادِ عَلَيْهَا، لِأَنَّهُ قَدْ صَعِدَ شَرُّهُمْ أَمَامِي».","«qumi ٱdẖ̊hab̊ ại̹lay̱ nīnaway̱ ٱl̊madīnaẗi ٱl̊ʿaẓīmaẗi wanādi ʿalaẙhā, liạảnãhu qad̊ ṣaʿida sẖarũhum̊ ạảmāmī»."],[1,3,"فَقَامَ يُونَانُ لِيَهْرُبَ إِلَى تَرْشِيشَ مِنْ وَجْهِ ٱلرَّبِّ، فَنَزَلَ إِلَى يَافَا وَوَجَدَ سَفِينَةً ذَاهِبَةً إِلَى تَرْشِيشَ، فَدَفَعَ أُجْرَتَهَا وَنَزَلَ فِيهَا، لِيَذْهَبَ مَعَهُمْ إِلَى تَرْشِيشَ مِنْ وَجْهِ ٱلرَّبِّ.","faqāma yūnānu līah̊ruba ại̹lay̱ tar̊sẖīsẖa min̊ waj̊hi ٱlrãbĩ, fanazala ại̹lay̱ yāfā wawajada safīnaẗaⁿ dẖāhibaẗaⁿ ại̹lay̱ tar̊sẖīsẖa, fadafaʿa ạủj̊ratahā wanazala fīhā, līadẖ̊haba maʿahum̊ ại̹lay̱ tar̊sẖīsẖa min̊ waj̊hi ٱlrãbĩ."],[1,4,"فَأَرْسَلَ ٱلرَّبُّ رِيحًا شَدِيدَةً إِلَى ٱلْبَحْرِ، فَحَدَثَ نَوْءٌ عَظِيمٌ فِي ٱلْبَحْرِ حَتَّى كَادَتِ ٱلسَّفِينَةُ تَنْكَسِرُ.","fāảr̊sala ٱlrãbũ rīḥaⁿạ sẖadīdaẗaⁿ ại̹lay̱ ٱl̊baḥ̊ri, faḥadatẖa naẘʾuⁿ ʿaẓīmuⁿ fī ٱl̊baḥ̊ri ḥatãy̱ kādati ٱlsãfīnaẗu tan̊kasiru."],[1,5,"فَخَافَ ٱلْمَّلَاحُونَ وَصَرَخُوا كُلُّ وَاحِدٍ إِلَى إِلَهِهِ، وَطَرَحُوا ٱلْأَمْتِعَةَ ٱلَّتِي فِي ٱلسَّفِينَةِ إِلَى ٱلْبَحْرِ لِيُخَفِّفُوا عَنْهُمْ. وَأَمَّا يُونَانُ فَكَانَ قَدْ نَزَلَ إِلَى جَوْفِ ٱلسَّفِينَةِ وَٱضْطَجَعَ وَنَامَ نَوْمًا ثَقِيلًا.","fakẖāfa ٱl̊mãlāḥūna waṣarakẖūạ kulũ wāḥidiⁿ ại̹lay̱ ại̹lahihi, waṭaraḥūạ ٱl̊ạảm̊tiʿaẗa ٱlãtī fī ٱlsãfīnaẗi ại̹lay̱ ٱl̊baḥ̊ri līukẖafĩfūạ ʿan̊hum̊. wāảmãạ yūnānu fakāna qad̊ nazala ại̹lay̱ jaẘfi ٱlsãfīnaẗi waٱḍ̊ṭajaʿa wanāma naẘmaⁿạ tẖaqīlaⁿạ."],[1,6,"فَجَاءَ إِلَيْهِ رَئِيسُ ٱلنُّوتِيَّةِ وَقَالَ لَهُ: «مَا لَكَ نَائِمًا؟ قُمِ ٱصْرُخْ إِلَى إِلَهِكَ عَسَى أَنْ يَفْتَكِرَ ٱلإِلَهُ فِينَا فَلَا نَهْلِكَ».","fajāʾa ại̹laẙhi rayỉysu ٱlnũwtīãẗi waqāla lahu: «mā laka nāyỉmaⁿạ? qumi ٱṣ̊rukẖ̊ ại̹lay̱ ại̹lahika ʿasay̱ ạản̊ yaf̊takira ٱlại̹lahu fīnā falā nah̊lika»."],[1,7,"وَقَالَ بَعْضُهُمْ لِبَعْضٍ: «هَلُمَّ نُلْقِي قُرَعًا لِنَعْرِفَ بِسَبَبِ مَنْ هَذِهِ ٱلْبَلِيَّةُ». فَأَلْقَوْا قُرَعًا، فَوَقَعَتِ ٱلْقُرْعَةُ عَلَى يُونَانَ.","waqāla baʿ̊ḍuhum̊ libaʿ̊ḍiⁿ: «halumã nul̊qī quraʿaⁿạ linaʿ̊rifa bisababi man̊ hadẖihi ٱl̊balīãẗu». fāảl̊qaẘạ quraʿaⁿạ, fawaqaʿati ٱl̊qur̊ʿaẗu ʿalay̱ yūnāna."],[1,8,"فَقَالُوا لَهُ: «أَخْبِرْنَا بِسَبَبِ مَنْ هَذِهِ ٱلْمُصِيبَةُ عَلَيْنَا؟ مَا هُوَ عَمَلُكَ؟ وَمِنْ أَيْنَ أَتَيْتَ؟ مَا هِيَ أَرْضُكَ؟ وَمِنْ أَيِّ شَعْبٍ أَنْتَ؟»","faqālūạ lahu: «ạảkẖ̊bir̊nā bisababi man̊ hadẖihi ٱl̊muṣībaẗu ʿalaẙnā? mā hūa ʿamaluka? wamin̊ ạảẙna ạảtaẙta? mā hīa ạảr̊ḍuka? wamin̊ ạảyĩ sẖaʿ̊biⁿ ạản̊ta?»"],[1,9,"فَقَالَ لَهُمْ: «أَنَا عِبْرَانِيٌّ، وَأَنَا خَائِفٌ مِنَ ٱلرَّبِّ إِلَهِ ٱلسَّمَاءِ ٱلَّذِي صَنَعَ ٱلْبَحْرَ وَٱلْبَرَّ».","faqāla lahum̊: «ạảnā ʿib̊rānīuⁿ̃, wāảnā kẖāyỉfuⁿ mina ٱlrãbĩ ại̹lahi ٱlsãmāʾi ٱlãdẖī ṣanaʿa ٱl̊baḥ̊ra waٱl̊barã»."],[1,10,"فَخَافَ ٱلرِّجَالُ خَوْفًا عَظِيمًا، وَقَالُوا لَهُ: «لِمَاذَا فَعَلْتَ هَذَا؟» فَإِنَّ ٱلرِّجَالَ عَرَفُوا أَنَّهُ هَارِبٌ مِنْ وَجْهِ ٱلرَّبِّ، لِأَنَّهُ أَخْبَرَهُمْ.","fakẖāfa ٱlrĩjālu kẖaẘfaⁿạ ʿaẓīmaⁿạ, waqālūạ lahu: «limādẖā faʿal̊ta hadẖā?» fāi̹nã ٱlrĩjāla ʿarafūạ ạảnãhu hāribuⁿ min̊ waj̊hi ٱlrãbĩ, liạảnãhu ạảkẖ̊barahum̊."],[1,11,"فَقَالُوا لَهُ: «مَاذَا نَصْنَعُ بِكَ لِيَسْكُنَ ٱلْبَحْرُ عَنَّا؟» لِأَنَّ ٱلْبَحْرَ كَانَ يَزْدَادُ ٱضْطِرَابًا.","faqālūạ lahu: «mādẖā naṣ̊naʿu bika līas̊kuna ٱl̊baḥ̊ru ʿanãạ?» liạảnã ٱl̊baḥ̊ra kāna yaz̊dādu ٱḍ̊ṭirābaⁿạ."],[1,12,"فَقَالَ لَهُمْ: «خُذُونِي وَٱطْرَحُونِي فِي ٱلْبَحْرِ فَيَسْكُنَ ٱلْبَحْرُ عَنْكُمْ، لِأَنَّنِي عَالِمٌ أَنَّهُ بِسَبَبِي هَذَا ٱلنَّوْءُ ٱلْعَظِيمُ عَلَيْكُمْ».","faqāla lahum̊: «kẖudẖūnī waٱṭ̊raḥūnī fī ٱl̊baḥ̊ri fayas̊kuna ٱl̊baḥ̊ru ʿan̊kum̊, liạảnãnī ʿālimuⁿ ạảnãhu bisababī hadẖā ٱlnãẘʾu ٱl̊ʿaẓīmu ʿalaẙkum̊»."],[1,13,"وَلَكِنَّ ٱلرِّجَالَ جَذَفُوا لِيُرَجِّعُوا ٱلسَّفِينَةَ إِلَى ٱلْبَرِّ فَلَمْ يَسْتَطِيعُوا، لِأَنَّ ٱلْبَحْرَ كَانَ يَزْدَادُ ٱضْطِرَابًا عَلَيْهِمْ.","walakinã ٱlrĩjāla jadẖafūạ līurajĩʿūạ ٱlsãfīnaẗa ại̹lay̱ ٱl̊barĩ falam̊ yas̊taṭīʿūạ, liạảnã ٱl̊baḥ̊ra kāna yaz̊dādu ٱḍ̊ṭirābaⁿạ ʿalaẙhim̊."],[1,14,"فَصَرَخُوا إِلَى ٱلرَّبِّ وَقَالُوا: «آهِ يَارَبُّ، لَا نَهْلِكْ مِنْ أَجْلِ نَفْسِ هَذَا ٱلرَّجُلِ، وَلَا تَجْعَلْ عَلَيْنَا دَمًا بَرِيئًا، لِأَنَّكَ يَارَبُّ فَعَلْتَ كَمَا شِئْتَ».","faṣarakẖūạ ại̹lay̱ ٱlrãbĩ waqālūạ: «ậhi yārabũ, lā nah̊lik̊ min̊ ạảj̊li naf̊si hadẖā ٱlrãjuli, walā taj̊ʿal̊ ʿalaẙnā damaⁿạ barīyaⁿ̉ạ, liạảnãka yārabũ faʿal̊ta kamā sẖī̊̉ta»."],[1,15,"ثُمَّ أَخَذُوا يُونَانَ وَطَرَحُوهُ فِي ٱلْبَحْرِ، فَوَقَفَ ٱلْبَحْرُ عَنْ هَيَجَانِهِ.","tẖumã ạảkẖadẖūạ yūnāna waṭaraḥūhu fī ٱl̊baḥ̊ri, fawaqafa ٱl̊baḥ̊ru ʿan̊ hayajānihi."],[1,16,"فَخَافَ ٱلرِّجَالُ مِنَ ٱلرَّبِّ خَوْفًا عَظِيمًا، وَذَبَحُوا ذَبِيحَةً لِلرَّبِّ وَنَذَرُوا نُذُورًا.","fakẖāfa ٱlrĩjālu mina ٱlrãbĩ kẖaẘfaⁿạ ʿaẓīmaⁿạ, wadẖabaḥūạ dẖabīḥaẗaⁿ lilrãbĩ wanadẖarūạ nudẖūraⁿạ."],[1,17,"وَأَمَّا ٱلرَّبُّ فَأَعَدَّ حُوتًا عَظِيمًا لِيَبْتَلِعَ يُونَانَ. فَكَانَ يُونَانُ فِي جَوْفِ ٱلْحُوتِ ثَلَاثَةَ أَيَّامٍ وَثَلَاثَ لَيَالٍ.","wāảmãạ ٱlrãbũ fāảʿadã ḥūtaⁿạ ʿaẓīmaⁿạ līab̊taliʿa yūnāna. fakāna yūnānu fī jaẘfi ٱl̊ḥūti tẖalātẖaẗa ạảyãạmiⁿ watẖalātẖa layāliⁿ."],[2,1,"فَصَلَّى يُونَانُ إِلَى ٱلرَّبِّ إِلَهِهِ مِنْ جَوْفِ ٱلْحُوتِ،","faṣalãy̱ yūnānu ại̹lay̱ ٱlrãbĩ ại̹lahihi min̊ jaẘfi ٱl̊ḥūti,"],[2,2,"وَقَالَ: «دَعَوْتُ مِنْ ضِيقِي ٱلرَّبَّ، فَٱسْتَجَابَنِي. صَرَخْتُ مِنْ جَوْفِ ٱلْهَاوِيَةِ، فَسَمِعْتَ صَوْتِي.","waqāla: «daʿaẘtu min̊ ḍīqī ٱlrãbã, faٱs̊tajābanī. ṣarakẖ̊tu min̊ jaẘfi ٱl̊hāwīaẗi, fasamiʿ̊ta ṣaẘtī."],[2,3,"لِأَنَّكَ طَرَحْتَنِي فِي ٱلْعُمْقِ فِي قَلْبِ ٱلْبِحَارِ، فَأَحَاطَ بِي نَهْرٌ. جَازَتْ فَوْقِي جَمِيعُ تَيَّارَاتِكَ وَلُجَجِكَ.","liạảnãka ṭaraḥ̊tanī fī ٱl̊ʿum̊qi fī qal̊bi ٱl̊biḥāri, fāảḥāṭa bī nah̊ruⁿ. jāzat̊ faẘqī jamīʿu tayãạrātika walujajika."],[2,4,"فَقُلْتُ: قَدْ طُرِدْتُ مِنْ أَمَامِ عَيْنَيْكَ. وَلَكِنَّنِي أَعُودُ أَنْظُرُ إِلَى هَيْكَلِ قُدْسِكَ.","faqul̊tu: qad̊ ṭurid̊tu min̊ ạảmāmi ʿaẙnaẙka. walakinãnī ạảʿūdu ạản̊ẓuru ại̹lay̱ haẙkali qud̊sika."],[2,5,"قَدِ ٱكْتَنَفَتْنِي مِيَاهٌ إِلَى ٱلنَّفْسِ. أَحَاطَ بِي غَمْرٌ. ٱلْتَفَّ عُشْبُ ٱلْبَحْرِ بِرَأْسِي.","qadi ٱk̊tanafat̊nī mīāhuⁿ ại̹lay̱ ٱlnãf̊si. ạảḥāṭa bī gẖam̊ruⁿ. ٱl̊tafã ʿusẖ̊bu ٱl̊baḥ̊ri birā̊̉sī."],[2,6,"نَزَلْتُ إِلَى أَسَافِلِ ٱلْجِبَالِ. مَغَالِيقُ ٱلْأَرْضِ عَلَيَّ إِلَى ٱلْأَبَدِ. ثُمَّ أَصْعَدْتَ مِنَ ٱلْوَهْدَةِ حَيَاتِي أَيُّهَا ٱلرَّبُّ إِلَهِي.","nazal̊tu ại̹lay̱ ạảsāfili ٱl̊jibāli. magẖālīqu ٱl̊ạảr̊ḍi ʿalayã ại̹lay̱ ٱl̊ạảbadi. tẖumã ạảṣ̊ʿad̊ta mina ٱl̊wah̊daẗi ḥayātī ạảyũhā ٱlrãbũ ại̹lahī."],[2,7,"حِينَ أَعْيَتْ فِيَّ نَفْسِي ذَكَرْتُ ٱلرَّبَّ، فَجَاءَتْ إِلَيْكَ صَلَاتِي إِلَى هَيْكَلِ قُدْسِكَ.","ḥīna ạảʿ̊yat̊ fīã naf̊sī dẖakar̊tu ٱlrãbã, fajāʾat̊ ại̹laẙka ṣalātī ại̹lay̱ haẙkali qud̊sika."],[2,8,"اَلَّذِينَ يُرَاعُونَ أَبَاطِيلَ كَاذِبَةً يَتْرُكُونَ نِعْمَتَهُمْ.","ạalãdẖīna yurāʿūna ạảbāṭīla kādẖibaẗaⁿ yat̊rukūna niʿ̊matahum̊."],[2,9,"أَمَّا أَنَا فَبِصَوْتِ ٱلْحَمْدِ أَذْبَحُ لَكَ، وَأُوفِي بِمَا نَذَرْتُهُ. لِلرَّبِّ ٱلْخَلَاصُ».","ạảmãạ ạảnā fabiṣaẘti ٱl̊ḥam̊di ạảdẖ̊baḥu laka, wāủwfī bimā nadẖar̊tuhu. lilrãbĩ ٱl̊kẖalāṣu»."],[2,10,"وَأَمَرَ ٱلرَّبُّ ٱلْحُوتَ فَقَذَفَ يُونَانَ إِلَى ٱلْبَرِّ.","wāảmara ٱlrãbũ ٱl̊ḥūta faqadẖafa yūnāna ại̹lay̱ ٱl̊barĩ."],[3,1,"ثُمَّ صَارَ قَوْلُ ٱلرَّبِّ إِلَى يُونَانَ ثَانِيَةً قَائِلًا:","tẖumã ṣāra qaẘlu ٱlrãbĩ ại̹lay̱ yūnāna tẖānīaẗaⁿ qāyỉlaⁿạ:"],[3,2,"«قُمِ ٱذْهَبْ إِلَى نِينَوَى ٱلْمَدِينَةِ ٱلْعَظِيمَةِ، وَنَادِ لَهَا ٱلْمُنَادَاةَ ٱلَّتِي أَنَا مُكَلِّمُكَ بِهَا».","«qumi ٱdẖ̊hab̊ ại̹lay̱ nīnaway̱ ٱl̊madīnaẗi ٱl̊ʿaẓīmaẗi, wanādi lahā ٱl̊munādāẗa ٱlãtī ạảnā mukalĩmuka bihā»."],[3,3,"فَقَامَ يُونَانُ وَذَهَبَ إِلَى نِينَوَى بِحَسَبِ قَوْلِ ٱلرَّبِّ. أَمَّا نِينَوَى فَكَانَتْ مَدِينَةً عَظِيمَةً لِلهِ مَسِيرَةَ ثَلَاثَةِ أَيَّامٍ.","faqāma yūnānu wadẖahaba ại̹lay̱ nīnaway̱ biḥasabi qaẘli ٱlrãbĩ. ạảmãạ nīnaway̱ fakānat̊ madīnaẗaⁿ ʿaẓīmaẗaⁿ lilhi masīraẗa tẖalātẖaẗi ạảyãạmiⁿ."],[3,4,"فَٱبْتَدَأَ يُونَانُ يَدْخُلُ ٱلْمَدِينَةَ مَسِيرَةَ يَوْمٍ وَاحِدٍ، وَنَادَى وَقَالَ: «بَعْدَ أَرْبَعِينَ يَوْمًا تَنْقَلِبُ نِينَوَى».","faٱb̊tadāả yūnānu yad̊kẖulu ٱl̊madīnaẗa masīraẗa yaẘmiⁿ wāḥidiⁿ, wanāday̱ waqāla: «baʿ̊da ạảr̊baʿīna yaẘmaⁿạ tan̊qalibu nīnaway̱»."],[3,5,"فَآمَنَ أَهْلُ نِينَوَى بِٱللهِ وَنَادَوْا بِصَوْمٍ وَلَبِسُوا مُسُوحًا مِنْ كَبِيرِهِمْ إِلَى صَغِيرِهِمْ.","fā̂mana ạảh̊lu nīnaway̱ biٱllhi wanādaẘạ biṣaẘmiⁿ walabisūạ musūḥaⁿạ min̊ kabīrihim̊ ại̹lay̱ ṣagẖīrihim̊."],[3,6,"وَبَلَغَ ٱلْأَمْرُ مَلِكَ نِينَوَى، فَقَامَ عَنْ كُرْسِيِّهِ وَخَلَعَ رِدَاءَهُ عَنْهُ، وَتَغَطَّى بِمِسْحٍ وَجَلَسَ عَلَى ٱلرَّمَادِ.","wabalagẖa ٱl̊ạảm̊ru malika nīnaway̱, faqāma ʿan̊ kur̊sīĩhi wakẖalaʿa ridāʾahu ʿan̊hu, watagẖaṭãy̱ bimis̊ḥiⁿ wajalasa ʿalay̱ ٱlrãmādi."],[3,7,"وَنُودِيَ وَقِيلَ فِي نِينَوَى عَنْ أَمْرِ ٱلْمَلِكِ وَعُظَمَائِهِ قَائِلًا: «لَا تَذُقِ ٱلنَّاسُ وَلَا ٱلْبَهَائِمُ وَلَا ٱلْبَقَرُ وَلَا ٱلْغَنَمُ شَيْئًا. لَا تَرْعَ وَلَا تَشْرَبْ مَاءً.","wanūdīa waqīla fī nīnaway̱ ʿan̊ ạảm̊ri ٱl̊maliki waʿuẓamāyỉhi qāyỉlaⁿạ: «lā tadẖuqi ٱlnãạsu walā ٱl̊bahāyỉmu walā ٱl̊baqaru walā ٱl̊gẖanamu sẖaẙyaⁿ̉ạ. lā tar̊ʿa walā tasẖ̊rab̊ māʾaⁿ."],[3,8,"وَلْيَتَغَطَّ بِمُسُوحٍ ٱلنَّاسُ وَٱلْبَهَائِمُ، وَيَصْرُخُوا إِلَى ٱللهِ بِشِدَّةٍ، وَيَرْجِعُوا كُلُّ وَاحِدٍ عَنْ طَرِيقِهِ ٱلرَّدِيئَةِ وَعَنِ ٱلظُّلْمِ ٱلَّذِي فِي أَيْدِيهِمْ،","wal̊yatagẖaṭã bimusūḥiⁿ ٱlnãạsu waٱl̊bahāyỉmu, wayaṣ̊rukẖūạ ại̹lay̱ ٱllhi bisẖidãẗiⁿ, wayar̊jiʿūạ kulũ wāḥidiⁿ ʿan̊ ṭarīqihi ٱlrãdīyảẗi waʿani ٱlẓũl̊mi ٱlãdẖī fī ạảẙdīhim̊,"],[3,9,"لَعَلَّ ٱللهَ يَعُودُ وَيَنْدَمُ وَيَرْجِعُ عَنْ حُمُوِّ غَضَبِهِ فَلَا نَهْلِكَ».","laʿalã ٱllha yaʿūdu wayan̊damu wayar̊jiʿu ʿan̊ ḥumūĩ gẖaḍabihi falā nah̊lika»."],[3,10,"فَلَمَّا رَأَى ٱللهُ أَعْمَالَهُمْ أَنَّهُمْ رَجَعُوا عَنْ طَرِيقِهِمِ ٱلرَّدِيئَةِ، نَدِمَ ٱللهُ عَلَى ٱلشَّرِّ ٱلَّذِي تَكَلَّمَ أَنْ يَصْنَعَهُ بِهِمْ، فَلَمْ يَصْنَعْهُ.","falamãạ rāảy̱ ٱllhu ạảʿ̊mālahum̊ ạảnãhum̊ rajaʿūạ ʿan̊ ṭarīqihimi ٱlrãdīyảẗi, nadima ٱllhu ʿalay̱ ٱlsẖãrĩ ٱlãdẖī takalãma ạản̊ yaṣ̊naʿahu bihim̊, falam̊ yaṣ̊naʿ̊hu."],[4,1,"فَغَمَّ ذَلِكَ يُونَانَ غَمًّا شَدِيدًا، فَٱغْتَاظَ.","fagẖamã dẖalika yūnāna gẖamaⁿ̃ạ sẖadīdaⁿạ, faٱgẖ̊tāẓa."],[4,2,"وَصَلَّى إِلَى ٱلرَّبِّ وَقَالَ: «آهِ يَارَبُّ، أَلَيْسَ هَذَا كَلَامِي إِذْ كُنْتُ بَعْدُ فِي أَرْضِي؟ لِذَلِكَ بَادَرْتُ إِلَى ٱلْهَرَبِ إِلَى تَرْشِيشَ، لِأَنِّي عَلِمْتُ أَنَّكَ إِلَهٌ رَؤُوفٌ وَرَحِيمٌ بَطِيءُ ٱلْغَضَبِ وَكَثِيرُ ٱلرَّحْمَةِ وَنَادِمٌ عَلَى ٱلشَّرِّ.","waṣalãy̱ ại̹lay̱ ٱlrãbĩ waqāla: «ậhi yārabũ, ạảlaẙsa hadẖā kalāmī ại̹dẖ̊ kun̊tu baʿ̊du fī ạảr̊ḍī? lidẖalika bādar̊tu ại̹lay̱ ٱl̊harabi ại̹lay̱ tar̊sẖīsẖa, liạảnĩy ʿalim̊tu ạảnãka ại̹lahuⁿ rawủwfuⁿ waraḥīmuⁿ baṭīʾu ٱl̊gẖaḍabi wakatẖīru ٱlrãḥ̊maẗi wanādimuⁿ ʿalay̱ ٱlsẖãrĩ."],[4,3,"فَٱلْآنَ يَارَبُّ، خُذْ نَفْسِي مِنِّي، لِأَنَّ مَوْتِي خَيْرٌ مِنْ حَيَاتِي».","faٱl̊ậna yārabũ, kẖudẖ̊ naf̊sī minĩy, liạảnã maẘtī kẖaẙruⁿ min̊ ḥayātī»."],[4,4,"فَقَالَ ٱلرَّبُّ: «هَلِ ٱغْتَظْتَ بِٱلصَّوَابِ؟».","faqāla ٱlrãbũ: «hali ٱgẖ̊taẓ̊ta biٱlṣãwābi?»."],[4,5,"وَخَرَجَ يُونَانُ مِنَ ٱلْمَدِينَةِ وَجَلَسَ شَرْقِيَّ ٱلْمَدِينَةِ، وَصَنَعَ لِنَفْسِهِ هُنَاكَ مَظَلَّةً وَجَلَسَ تَحْتَهَا فِي ٱلظِّلِّ، حَتَّى يَرَى مَاذَا يَحْدُثُ فِي ٱلْمَدِينَةِ.","wakẖaraja yūnānu mina ٱl̊madīnaẗi wajalasa sẖar̊qīã ٱl̊madīnaẗi, waṣanaʿa linaf̊sihi hunāka maẓalãẗaⁿ wajalasa taḥ̊tahā fī ٱlẓĩlĩ, ḥatãy̱ yaray̱ mādẖā yaḥ̊dutẖu fī ٱl̊madīnaẗi."],[4,6,"فَأَعَدَّ ٱلرَّبُّ ٱلإِلَهُ يَقْطِينَةً فَٱرْتَفَعَتْ فَوْقَ يُونَانَ لِتَكُونَ ظِلًّا عَلَى رَأْسِهِ، لِكَيْ يُخَلِّصَهُ مِنْ غَمِّهِ. فَفَرِحَ يُونَانُ مِنْ أَجْلِ ٱلْيَقْطِينَةِ فَرَحًا عَظِيمًا.","fāảʿadã ٱlrãbũ ٱlại̹lahu yaq̊ṭīnaẗaⁿ faٱr̊tafaʿat̊ faẘqa yūnāna litakūna ẓilaⁿ̃ạ ʿalay̱ rā̊̉sihi, likaẙ yukẖalĩṣahu min̊ gẖamĩhi. fafariḥa yūnānu min̊ ạảj̊li ٱl̊yaq̊ṭīnaẗi faraḥaⁿạ ʿaẓīmaⁿạ."],[4,7,"ثُمَّ أَعَدَّ ٱللهُ دُودَةً عِنْدَ طُلُوعِ ٱلْفَجْرِ في ٱلْغَدِ، فَضَرَبَتِ ٱلْيَقْطِينَةَ فَيَبِسَتْ.","tẖumã ạảʿadã ٱllhu dūdaẗaⁿ ʿin̊da ṭulūʿi ٱl̊faj̊ri fy ٱl̊gẖadi, faḍarabati ٱl̊yaq̊ṭīnaẗa fayabisat̊."],[4,8,"وَحَدَثَ عِنْدَ طُلُوعِ ٱلشَّمْسِ أَنَّ ٱللهَ أَعَدَّ رِيحًا شَرْقِيَّةً حَارَّةً، فَضَرَبَتِ ٱلشَّمْسُ عَلَى رَأْسِ يُونَانَ فَذَبُلَ. فَطَلَبَ لِنَفْسِهِ ٱلْمَوْتَ، وَقَالَ: «مَوْتِي خَيْرٌ مِنْ حَيَاتِي».","waḥadatẖa ʿin̊da ṭulūʿi ٱlsẖãm̊si ạảnã ٱllha ạảʿadã rīḥaⁿạ sẖar̊qīãẗaⁿ ḥārãẗaⁿ, faḍarabati ٱlsẖãm̊su ʿalay̱ rā̊̉si yūnāna fadẖabula. faṭalaba linaf̊sihi ٱl̊maẘta, waqāla: «maẘtī kẖaẙruⁿ min̊ ḥayātī»."],[4,9,"فَقَالَ ٱللهُ لِيُونَانَ: «هَلِ ٱغْتَظْتَ بِٱلصَّوَابِ مِنْ أَجْلِ ٱلْيَقْطِينَةِ؟» فَقَالَ: «ٱغْتَظْتُ بِٱلصَّوَابِ حَتَّى ٱلْمَوْتِ».","faqāla ٱllhu līūnāna: «hali ٱgẖ̊taẓ̊ta biٱlṣãwābi min̊ ạảj̊li ٱl̊yaq̊ṭīnaẗi?» faqāla: «ٱgẖ̊taẓ̊tu biٱlṣãwābi ḥatãy̱ ٱl̊maẘti»."],[4,10,"فَقَالَ ٱلرَّبُّ: «أَنْتَ شَفِقْتَ عَلَى ٱلْيَقْطِينَةِ ٱلَّتِي لَمْ تَتْعَبْ فِيهَا وَلَا رَبَّيْتَهَا، ٱلَّتِي بِنْتَ لَيْلَةٍ كَانَتْ وَبِنْتَ لَيْلَةٍ هَلَكَتْ.","faqāla ٱlrãbũ: «ạản̊ta sẖafiq̊ta ʿalay̱ ٱl̊yaq̊ṭīnaẗi ٱlãtī lam̊ tat̊ʿab̊ fīhā walā rabãẙtahā, ٱlãtī bin̊ta laẙlaẗiⁿ kānat̊ wabin̊ta laẙlaẗiⁿ halakat̊."],[4,11,"أَفَلَا أَشْفَقُ أَنَا عَلَى نِينَوَى ٱلْمَدِينَةِ ٱلْعَظِيمَةِ ٱلَّتِي يُوجَدُ فِيهَا أَكْثَرُ مِنِ ٱثْنَتَيْ عَشَرَةَ رِبْوَةً مِنَ ٱلنَّاسِ ٱلَّذِينَ لَا يَعْرِفُونَ يَمِينَهُمْ مِنْ شِمَالِهِمْ، وَبَهَائِمُ كَثِيرَةٌ؟».","ạảfalā ạảsẖ̊faqu ạảnā ʿalay̱ nīnaway̱ ٱl̊madīnaẗi ٱl̊ʿaẓīmaẗi ٱlãtī yūjadu fīhā ạảk̊tẖaru mini ٱtẖ̊nataẙ ʿasẖaraẗa rib̊waẗaⁿ mina ٱlnãạsi ٱlãdẖīna lā yaʿ̊rifūna yamīnahum̊ min̊ sẖimālihim̊, wabahāyỉmu katẖīraẗuⁿ?»."]],"bis-obbr":[[1,1,"Nao Hae God i toktok long Profet Jona, we papa blong hem Amitae, i talem se,","Nao Hae God i toktok long Profet Jona, we papa blong hem Amitae, i talem se,"],[1,2,"“Jona. Yu girap, yu go long bigfala taon ya Nineve, yu tok long olgeta, from we mi luk se fasin blong olgeta i nogud we i nogud.”","“Jona. Yu girap, yu go long bigfala taon ya Nineve, yu tok long olgeta, from we mi luk se fasin blong olgeta i nogud we i nogud.”"],[1,3,"Be profet i no wantem, nao hem i girap, i traem ronwe long Hae God, i tekem narafala rod olgeta, i go long wan ples klosap long solwota, nem blong hem Jopa. Nao hem i faenem wan sip we i stap rere blong aot blong go long kantri ya Spen. Hem i pem pasis blong hem, nao i jam long sip ya wetem olgeta, blong i ronwe long Hae God. Mo taem sip ya i aot, hem i godaon long damblo, i slip.","Be profet i no wantem, nao hem i girap, i traem ronwe long Hae God, i tekem narafala rod olgeta, i go long wan ples klosap long solwota, nem blong hem Jopa. Nao hem i faenem wan sip we i stap rere blong aot blong go long kantri ya Spen. Hem i pem pasis blong hem, nao i jam long sip ya wetem olgeta, blong i ronwe long Hae God. Mo taem sip ya i aot, hem i godaon long damblo, i slip."],[1,4,"Be Hae God i mekem bigfala win i blu, i mekem solwota i raf we i raf we klosap sip ya i brok.","Be Hae God i mekem bigfala win i blu, i mekem solwota i raf we i raf we klosap sip ya i brok."],[1,5,"Nao ol boskru oli fraet tumas, mo olgeta evriwan oli stap prea long ol god blong olgeta blong oli givhan long olgeta, wan i prea long god blong hem, wan i prea long god blong hem. Mo oli sakem ol kago i go long solwota from we sip ya i fulap tumas. Be Profet Jona i stap long damblo, i slip we i slip.","Nao ol boskru oli fraet tumas, mo olgeta evriwan oli stap prea long ol god blong olgeta blong oli givhan long olgeta, wan i prea long god blong hem, wan i prea long god blong hem. Mo oli sakem ol kago i go long solwota from we sip ya i fulap tumas. Be Profet Jona i stap long damblo, i slip we i slip."],[1,6,"Nao kapten i faenem hem, mo i tok long hem, i talem se, “!Ei! ?From wanem yu stap slip olsem? !Yu girap! Yu prea long god blong yu blong i givhan long yumi. Maet hem i save sore long yumi, i sevem yumi.”","Nao kapten i faenem hem, mo i tok long hem, i talem se, “!Ei! ?From wanem yu stap slip olsem? !Yu girap! Yu prea long god blong yu blong i givhan long yumi. Maet hem i save sore long yumi, i sevem yumi.”"],[1,7,"Nao ol boskru oli stap taltalem long olgeta se, “I gud yumi sakem ol spesel ston* blong faenemaot se hu i stamba blong trabol ya we i kasem yumi.” Nao oli mekem olsem, mo nem blong Profet Jona i kamaot.","Nao ol boskru oli stap taltalem long olgeta se, “I gud yumi sakem ol spesel ston* blong faenemaot se hu i stamba blong trabol ya we i kasem yumi.” Nao oli mekem olsem, mo nem blong Profet Jona i kamaot."],[1,8,"Nao oli tok long hem, oli talem se, “!Ei! !Yu talemaot long mifala! ?Trabol ya i fol blong hu? ?Yu kam ya blong mekem wanem? ?Yu blong wanem kantri? ?Yu laen blong hu?”","Nao oli tok long hem, oli talem se, “!Ei! !Yu talemaot long mifala! ?Trabol ya i fol blong hu? ?Yu kam ya blong mekem wanem? ?Yu blong wanem kantri? ?Yu laen blong hu?”"],[1,9,"Nao hem i talem se, “Mi mi wan Hibru* ya, mo Hae God i God blong mi. Hem i stap long heven, mo hem nao i mekem graon mo solwota. Mi mi stap mekem wosip long hem.","Nao hem i talem se, “Mi mi wan Hibru* ya, mo Hae God i God blong mi. Hem i stap long heven, mo hem nao i mekem graon mo solwota. Mi mi stap mekem wosip long hem."],[1,10,"Mi mi man blong hem, be mi stap ronwe long hem.” Nao taem ol boskru oli harem samting ya, oli fraet we i fraet. Nao oli talem long hem se, “!Man! !Yu yu mekem i nogud tumas ya! ?Olsem wanem nao?”","Mi mi man blong hem, be mi stap ronwe long hem.” Nao taem ol boskru oli harem samting ya, oli fraet we i fraet. Nao oli talem long hem se, “!Man! !Yu yu mekem i nogud tumas ya! ?Olsem wanem nao?”"],[1,11,"Be hariken i stap kam strong moa, nao olgeta oli askem long hem se, “?Bambae mifala i mekem olsem wanem long yu blong win ya i godaon, mo solwota i kwaet?”","Be hariken i stap kam strong moa, nao olgeta oli askem long hem se, “?Bambae mifala i mekem olsem wanem long yu blong win ya i godaon, mo solwota i kwaet?”"],[1,12,"Mo hem i talem se, “Yufala i karem mi, yufala i sakem mi i go long solwota, nao bambae solwota i kwaet. Mi mi save se mi mekem wan samting we i nogud we i nogud, nao hariken ya i kam kasem yumi from.”","Mo hem i talem se, “Yufala i karem mi, yufala i sakem mi i go long solwota, nao bambae solwota i kwaet. Mi mi save se mi mekem wan samting we i nogud we i nogud, nao hariken ya i kam kasem yumi from.”"],[1,13,"Be ol boskru oli no wantem mekem olsem, nao oli traehad blong pul i gobak long soa, be oli no save go, from we si i kam bigwan tumas, mo win i stap kam strong moa.","Be ol boskru oli no wantem mekem olsem, nao oli traehad blong pul i gobak long soa, be oli no save go, from we si i kam bigwan tumas, mo win i stap kam strong moa."],[1,14,"Nao oli prea long Hae God, oli talem se, “Hae God. Sipos man ya blong yu i ded, be plis yu no panisim mifala, yu no mekem we mifala i ded from. Yu nomo yu wokem ol samting ya. Hemia i bisnes blong yu nomo. Plis yu no putum long mifala.”","Nao oli prea long Hae God, oli talem se, “Hae God. Sipos man ya blong yu i ded, be plis yu no panisim mifala, yu no mekem we mifala i ded from. Yu nomo yu wokem ol samting ya. Hemia i bisnes blong yu nomo. Plis yu no putum long mifala.”"],[1,15,"Nao oli karem Profet Jona, oli sakem hem i go long solwota, mo wantaem nomo, solwota i kwaet.","Nao oli karem Profet Jona, oli sakem hem i go long solwota, mo wantaem nomo, solwota i kwaet."],[1,16,"Mo taem ol boskru oli luk samting ya oli fraet tumas long Hae God, nao oli tekem wan anamol, oli mekem sakrefaes long hem blong mekem wosip long Hae God, mo oli promes se bambae oli kam man blong hem.","Mo taem ol boskru oli luk samting ya oli fraet tumas long Hae God, nao oli tekem wan anamol, oli mekem sakrefaes long hem blong mekem wosip long Hae God, mo oli promes se bambae oli kam man blong hem."],[1,17,"Be Hae God i sanem wan bigfala fis i kam, i solemdaon Profet Jona, mo hem i stap insaed long bel blong fis ya, tri dei mo tri naet.","Be Hae God i sanem wan bigfala fis i kam, i solemdaon Profet Jona, mo hem i stap insaed long bel blong fis ya, tri dei mo tri naet."],[2,1,"Nao taem Profet Jona i stap insaed long bel blong bigfala fis ya, hem i prea long Hae God we i God blong hem, i talem se,","Nao taem Profet Jona i stap insaed long bel blong bigfala fis ya, hem i prea long Hae God we i God blong hem, i talem se,"],[2,2,"“Hae God. Taem mi stap long trabol, mi krae i kam long yu, nao yu lesin long mi mo yu ansa long mi. Mi harem se mi stap finis long Hom* blong ol Dedman, be mi prea long yu blong yu givhan long mi, nao yu harem mi.","“Hae God. Taem mi stap long trabol, mi krae i kam long yu, nao yu lesin long mi mo yu ansa long mi. Mi harem se mi stap finis long Hom* blong ol Dedman, be mi prea long yu blong yu givhan long mi, nao yu harem mi."],[2,3,"“Yu yu sakem mi mi godaon long solwota we i dip we i dip, nao solwota i kavremapgud mi, mo ol bigbigfala si oli stap brok antap long mi.","“Yu yu sakem mi mi godaon long solwota we i dip we i dip, nao solwota i kavremapgud mi, mo ol bigbigfala si oli stap brok antap long mi."],[2,4,"Mi mi ting se yu sakemaot mi finis long fes blong yu, nao bambae mi no save luk tabu haos* blong yu bakegen.","Mi mi ting se yu sakemaot mi finis long fes blong yu, nao bambae mi no save luk tabu haos* blong yu bakegen."],[2,5,"Mi mi dring solwota we klosap mi ded from, solwota ya i kavremap mi olgeta, mo gras blong solwota i fulap long hed blong mi.","Mi mi dring solwota we klosap mi ded from, solwota ya i kavremap mi olgeta, mo gras blong solwota i fulap long hed blong mi."],[2,6,"Mi godaon olgeta, long stamba blong ol bigbigfala hil aninit long solwota. Mi harem olsem we mi go insaed long get blong Hom* blong ol Dedman, blong stap wetem olgeta, we get ya i no save open bakegen samtaem. Be yu Hae God, yu God blong mi, mo yu tekemaot mi bakegen long ples ya, we mi stap gud nomo.","Mi godaon olgeta, long stamba blong ol bigbigfala hil aninit long solwota. Mi harem olsem we mi go insaed long get blong Hom* blong ol Dedman, blong stap wetem olgeta, we get ya i no save open bakegen samtaem. Be yu Hae God, yu God blong mi, mo yu tekemaot mi bakegen long ples ya, we mi stap gud nomo."],[2,7,"Hae God. Taem mi harem we klosap laef blong mi i lus, mi tingbaot yu, mi prea long yu. Nao yu yu harem prea blong mi we i kam kasem yu long tabu haos blong yu.","Hae God. Taem mi harem we klosap laef blong mi i lus, mi tingbaot yu, mi prea long yu. Nao yu yu harem prea blong mi we i kam kasem yu long tabu haos blong yu."],[2,8,"Olgeta we oli stap prea long ol narafala god, oli lego yu finis, oli no moa tingbaot yu.","Olgeta we oli stap prea long ol narafala god, oli lego yu finis, oli no moa tingbaot yu."],[2,9,"!Be mi bambae mi sing blong presem nem blong yu! Bambae mi tekem wan anamol, mi mekem sakrefaes long hem blong mekem wosip long yu, mo blong talem tangkiu long yu. Mo bambae mi mekem ol wok ya we mi promes* long yu blong mekem. Yu, Hae God, yu nomo yu sevem mi.”","!Be mi bambae mi sing blong presem nem blong yu! Bambae mi tekem wan anamol, mi mekem sakrefaes long hem blong mekem wosip long yu, mo blong talem tangkiu long yu. Mo bambae mi mekem ol wok ya we mi promes* long yu blong mekem. Yu, Hae God, yu nomo yu sevem mi.”"],[2,10,"Nao Hae God i tok long fis ya, mo fis ya i goso, i traot, nao wantaem nomo Profet Jona i kamaot i foldaon long sanbij.","Nao Hae God i tok long fis ya, mo fis ya i goso, i traot, nao wantaem nomo Profet Jona i kamaot i foldaon long sanbij."],[3,1,"Nao Hae God i toktok bakegen long Profet Jona, i talem se,","Nao Hae God i toktok bakegen long Profet Jona, i talem se,"],[3,2,"“Jona. Yu go long bigfala taon ya Nineve, yu talemaot tok blong mi we bambae mi givim long yu.”","“Jona. Yu go long bigfala taon ya Nineve, yu talemaot tok blong mi we bambae mi givim long yu.”"],[3,3,"Nao hem i girap, i go long Nineve olsem we Hae God i talem long hem. Taon ya i bigwan we i bigwan, we man i save wokbaot tri dei blong kasem narasaed blong hem.","Nao hem i girap, i go long Nineve olsem we Hae God i talem long hem. Taon ya i bigwan we i bigwan, we man i save wokbaot tri dei blong kasem narasaed blong hem."],[3,4,"Nao hem i go insaed long taon ya, i wokbaot wan ful dei, mo biaen, hem i talemaot tok ya long olgeta. Hem i talem se, “Olgeta. !Yufala i lukaot! !Foti dei nomo i stap, nao God bambae i spolemgud bigfala taon ya blong yufala!”","Nao hem i go insaed long taon ya, i wokbaot wan ful dei, mo biaen, hem i talemaot tok ya long olgeta. Hem i talem se, “Olgeta. !Yufala i lukaot! !Foti dei nomo i stap, nao God bambae i spolemgud bigfala taon ya blong yufala!”"],[3,5,"Nao ol man Nineve oli bilif long tok ya blong God. Mo olgeta man, i stat long ol haeman i go kasem ol olbaot man, oli tanem tingting blong olgeta from ol rabis fasin blong olgeta, nao oli livim kakae, mo oli putum ol rabis klos blong soemaot we oli harem nogud tumas from sin blong olgeta.","Nao ol man Nineve oli bilif long tok ya blong God. Mo olgeta man, i stat long ol haeman i go kasem ol olbaot man, oli tanem tingting blong olgeta from ol rabis fasin blong olgeta, nao oli livim kakae, mo oli putum ol rabis klos blong soemaot we oli harem nogud tumas from sin blong olgeta."],[3,6,"Taem king blong Nineve i harem nius ya, hem i aot long jea blong hem, nao i tekemaot flas klos blong hem, i putum rabis klos, i go sidaon long asis faea.","Taem king blong Nineve i harem nius ya, hem i aot long jea blong hem, nao i tekemaot flas klos blong hem, i putum rabis klos, i go sidaon long asis faea."],[3,7,"Nao hem i sanem tok i go long ol man Nineve, i talem se, “Mi mi king blong yufala. Mi wetem ol haeman blong mi, mifala i putum tok ya, se yumi evriwan, ol man, wetem ol buluk mo ol sipsip blong yumi, bambae yumi no kakae wan samting, yumi no dring wan samting.","Nao hem i sanem tok i go long ol man Nineve, i talem se, “Mi mi king blong yufala. Mi wetem ol haeman blong mi, mifala i putum tok ya, se yumi evriwan, ol man, wetem ol buluk mo ol sipsip blong yumi, bambae yumi no kakae wan samting, yumi no dring wan samting."],[3,8,"Yumi mas putum ol rabis klos nomo, mo yumi mas fasem ol rabis blangket long ol anamol blong yumi, olsem klos blong olgeta. Mo yumi evriwan i mas prea strong long God, mo yumi mas lego ol rabis fasin blong yumi, mo yumi no moa mekem i strong tumas long ol man blong spolem olgeta.","Yumi mas putum ol rabis klos nomo, mo yumi mas fasem ol rabis blangket long ol anamol blong yumi, olsem klos blong olgeta. Mo yumi evriwan i mas prea strong long God, mo yumi mas lego ol rabis fasin blong yumi, mo yumi no moa mekem i strong tumas long ol man blong spolem olgeta."],[3,9,"Sipos God i luk ol samting ya, maet hem i save jenisim tingting blong hem, i no moa kros long yumi, nao bambae yumi no save ded.”","Sipos God i luk ol samting ya, maet hem i save jenisim tingting blong hem, i no moa kros long yumi, nao bambae yumi no save ded.”"],[3,10,"Taem God i luk ol samting ya we oli mekem, mo we oli lego ol rabis fasin blong olgeta, hem i jenisim tingting blong hem, i no panisim olgeta olsem we hem i talem fastaem.","Taem God i luk ol samting ya we oli mekem, mo we oli lego ol rabis fasin blong olgeta, hem i jenisim tingting blong hem, i no panisim olgeta olsem we hem i talem fastaem."],[4,1,"Be Profet Jona i no glad nating from samting ya, mo hem i kros tumas.","Be Profet Jona i no glad nating from samting ya, mo hem i kros tumas."],[4,2,"Nao hem i prea se, “Hae God. Taem mi mi stap yet long kantri blong mi, mi save finis, se bambae yu mekem olsem. Taswe mi traem ronwe blong go long Spen. Mi save we yu yu God we yu lavem man tumas, mo oltaem, yu gat sore long man. Mi save we tingting blong yu i longfala, mo oltaem, yu stap mekem i gud long ol man. Oltaem, yu yu rere blong jenisim tingting blong yu, blong yu no panisim ol man.","Nao hem i prea se, “Hae God. Taem mi mi stap yet long kantri blong mi, mi save finis, se bambae yu mekem olsem. Taswe mi traem ronwe blong go long Spen. Mi save we yu yu God we yu lavem man tumas, mo oltaem, yu gat sore long man. Mi save we tingting blong yu i longfala, mo oltaem, yu stap mekem i gud long ol man. Oltaem, yu yu rere blong jenisim tingting blong yu, blong yu no panisim ol man."],[4,3,"Be Hae God, naoia, plis yu letem mi mi ded. I moa gud mi ded nomo. !Mi wantem ded!”","Be Hae God, naoia, plis yu letem mi mi ded. I moa gud mi ded nomo. !Mi wantem ded!”"],[4,4,"Be Hae God i talem se, “Jona. ?Yu kros olsem, yu ting se i gud ya?”","Be Hae God i talem se, “Jona. ?Yu kros olsem, yu ting se i gud ya?”"],[4,5,"Nao Jona i girap, i aot long taon ya, i go long saed i go long is, nao i stap sidaon long ples ya. Hem i wokem wan wansaed haos i go sidaon aninit long hem blong haed long san, mo i stap wet blong luk se wanem samting bambae i kasem Nineve.","Nao Jona i girap, i aot long taon ya, i go long saed i go long is, nao i stap sidaon long ples ya. Hem i wokem wan wansaed haos i go sidaon aninit long hem blong haed long san, mo i stap wet blong luk se wanem samting bambae i kasem Nineve."],[4,6,"Nao Hae God we i God blong yumi i mekem wan kasroel tri i gru, i kam bigwan, klosap long Jona, blong sado blong hem i blokem hem, blong i save harem gud lelebet. Mo Jona i glad tumas from.","Nao Hae God we i God blong yumi i mekem wan kasroel tri i gru, i kam bigwan, klosap long Jona, blong sado blong hem i blokem hem, blong i save harem gud lelebet. Mo Jona i glad tumas from."],[4,7,"Be long moning blong hem, God i mekem waetanis i kakae kasroel tri ya, nao i drae.","Be long moning blong hem, God i mekem waetanis i kakae kasroel tri ya, nao i drae."],[4,8,"Biaen, taem san i kam antap, God i mekem iswin* i kam long hem we i hot we i hot. Mo Jona i harem we i hafded from san ya, we i stap bonem hed blong hem. Nao hem i talem se, “!Mi mi wantem ded! !I moa gud mi ded nomo!”","Biaen, taem san i kam antap, God i mekem iswin* i kam long hem we i hot we i hot. Mo Jona i harem we i hafded from san ya, we i stap bonem hed blong hem. Nao hem i talem se, “!Mi mi wantem ded! !I moa gud mi ded nomo!”"],[4,9,"Be God i talem long hem se, “?Yu ting se i stret we yu yu kros olsem from kasroel tri ya?” Nao hem i talem se, “!Yes! !I stret blong mi kros we mi kros we mi kros gogo mi ded from!”","Be God i talem long hem se, “?Yu ting se i stret we yu yu kros olsem from kasroel tri ya?” Nao hem i talem se, “!Yes! !I stret blong mi kros we mi kros we mi kros gogo mi ded from!”"],[4,10,"Nao Hae God i talem long hem se, “Kasroel tri ya we i gru, hem i kam bigwan long wan naet nomo, mo long tumora blong hem i drae bakegen. Yu yu no planem, mo yu no mekem hem i gru, be yu girap, yu sore tumas from.","Nao Hae God i talem long hem se, “Kasroel tri ya we i gru, hem i kam bigwan long wan naet nomo, mo long tumora blong hem i drae bakegen. Yu yu no planem, mo yu no mekem hem i gru, be yu girap, yu sore tumas from."],[4,11,"Ale, i stret nomo blong mi mi sore moa long bigfala taon ya Nineve, from we long ples ya i gat moa long wan handred twanti taosen pikinini oli stap, we oli no save wanem i gud mo wanem i nogud, mo bakegen i gat plante anamol tu oli stap long ples ya.”","Ale, i stret nomo blong mi mi sore moa long bigfala taon ya Nineve, from we long ples ya i gat moa long wan handred twanti taosen pikinini oli stap, we oli no save wanem i gud mo wanem i nogud, mo bakegen i gat plante anamol tu oli stap long ples ya.”"]],"hbo-wlc":[[1,1,"וַֽיְהִי֙ דְּבַר־יְהוָ֔ה אֶל־יוֹנָ֥ה בֶן־אֲמִתַּ֖י לֵאמֹֽר׃","waֽyĕhiy֙ dĕ̇bar-yĕhwá֔h ʼel-ywòná֥h ben-ʼàmiţȧ֖y léʼmòֽr׃"],[1,2,"ק֠וּם לֵ֧ךְ אֶל־נִֽינְוֵ֛ה הָעִ֥יר הַגְּדוֹלָ֖ה וּקְרָ֣א עָלֶ֑יהָ כִּֽי־עָלְתָ֥ה רָעָתָ֖ם לְפָנָֽי׃","q֠ẇm lé֧kĕ ʼel-niֽynĕwé֛h háʻi֥yr hagĕ̇dwòlá֖h ẇqĕrá֣ʼ ʻále֑yhá kiֽ̇y-ʻálĕţá֥h ráʻáţá֖m lĕpánáֽy׃"],[1,3,"וַיָּ֤קָם יוֹנָה֙ לִבְרֹ֣חַ תַּרְשִׁ֔ישָׁה מִלִּפְנֵ֖י יְהוָ֑ה וַיֵּ֨רֶד יָפ֜וֹ וַיִּמְצָ֥א אָנִיָּ֣ה ׀ בָּאָ֣ה תַרְשִׁ֗ישׁ וַיִּתֵּ֨ן שְׂכָרָ֜הּ וַיֵּ֤רֶד בָּהּ֙ לָב֤וֹא עִמָּהֶם֙ תַּרְשִׁ֔ישָׁה מִלִּפְנֵ֖י יְהוָֽה׃","wayá֤̇qám ywònáh֙ libĕrò֣ẖa ţȧrĕşǐ֔yşá̌h mili̇pĕné֖y yĕhwá֑h wayé̇֨red yáp֜wò wayi̇mĕẕá֥ʼ ʼániyá֣̇h ׀ bá̇ʼá֣h ţarĕşǐ֗yş̌ wayi̇ţé̇֨n şĕ̂kárá֜ḣ wayé֤̇red bá̇ḣ֙ láb֤wòʼ ʻimá̇hem֙ ţȧrĕşǐ֔yşá̌h mili̇pĕné֖y yĕhwáֽh׃"],[1,4,"וַֽיהוָ֗ה הֵטִ֤יל רֽוּחַ־גְּדוֹלָה֙ אֶל־הַיָּ֔ם וַיְהִ֥י סַֽעַר־גָּד֖וֹל בַּיָּ֑ם וְהָ֣אֳנִיָּ֔ה חִשְּׁבָ֖ה לְהִשָּׁבֵֽר׃","waֽyhwá֗h héti֤yl rֽẇẖa-gĕ̇dwòláh֙ ʼel-hayá̇֔m wayĕhi֥y saֽʻar-gá̇d֖wòl bȧyá֑̇m wĕhá֣ʼoniyá̇֔h ẖişĕ̇̌bá֖h lĕhişá̇̌béֽr׃"],[1,5,"וַיִּֽירְא֣וּ הַמַּלָּחִ֗ים וַֽיִּזְעֲקוּ֮ אִ֣ישׁ אֶל־אֱלֹהָיו֒ וַיָּטִ֨לוּ אֶת־הַכֵּלִ֜ים אֲשֶׁ֤ר בָּֽאֳנִיָּה֙ אֶל־הַיָּ֔ם לְהָקֵ֖ל מֵֽעֲלֵיהֶ֑ם וְיוֹנָ֗ה יָרַד֙ אֶל־יַרְכְּתֵ֣י הַסְּפִינָ֔ה וַיִּשְׁכַּ֖ב וַיֵּרָדַֽם׃","wayiֽ̇yrĕʼ֣ẇ hamȧlá̇ẖi֗ym waֽyi̇zĕʻàqẇ֮ ʼi֣yş̌ ʼel-ʼèlòháyw֒ wayá̇ti֨lẇ ʼeţ-haké̇li֜ym ʼàşě֤r báֽ̇ʼoniyá̇h֙ ʼel-hayá̇֔m lĕháqé֖l méֽʻàléyhe֑m wĕywòná֗h yárad֙ ʼel-yarĕkĕ̇ţé֣y hasĕ̇piyná֔h wayi̇şĕ̌kȧ֖b wayé̇rádaֽm׃"],[1,6,"וַיִּקְרַ֤ב אֵלָיו֙ רַ֣ב הַחֹבֵ֔ל וַיֹּ֥אמֶר ל֖וֹ מַה־לְּךָ֣ נִרְדָּ֑ם ק֚וּם קְרָ֣א אֶל־אֱלֹהֶ֔יךָ אוּלַ֞י יִתְעַשֵּׁ֧ת הָאֱלֹהִ֛ים לָ֖נוּ וְלֹ֥א נֹאבֵֽד׃","wayi̇qĕra֤b ʼéláyw֙ ra֣b haẖòbé֔l wayò֥̇ʼmer l֖wò mah-lĕ̇ká֣ nirĕdá֑̇m q֚ẇm qĕrá֣ʼ ʼel-ʼèlòhe֔yká ʼẇla֞y yiţĕʻaşé֧̇̌ţ háʼèlòhi֛ym lá֖nẇ wĕlò֥ʼ nòʼbéֽd׃"],[1,7,"וַיֹּאמְר֞וּ אִ֣ישׁ אֶל־רֵעֵ֗הוּ לְכוּ֙ וְנַפִּ֣ילָה גֽוֹרָל֔וֹת וְנֵ֣דְעָ֔ה בְּשֶׁלְּמִ֛י הָרָעָ֥ה הַזֹּ֖את לָ֑נוּ וַיַּפִּ֙לוּ֙ גּֽוֹרָל֔וֹת וַיִּפֹּ֥ל הַגּוֹרָ֖ל עַל־יוֹנָֽה׃","wayò̇ʼmĕr֞ẇ ʼi֣yş̌ ʼel-réʻé֗hẇ lĕkẇ֙ wĕnapi֣̇yláh gֽwòrál֔wòţ wĕné֣dĕʻá֔h bĕ̇şělĕ̇mi֛y háráʻá֥h hazò֖̇ʼţ lá֑nẇ wayȧpi̇֙lẇ֙ ġֽwòrál֔wòţ wayi̇pò֥̇l haġwòrá֖l ʻal-ywònáֽh׃"],[1,8,"וַיֹּאמְר֣וּ אֵלָ֔יו הַגִּידָה־ נָּ֣א לָ֔נוּ בַּאֲשֶׁ֛ר לְמִי־הָרָעָ֥ה הַזֹּ֖את לָ֑נוּ מַה־מְּלַאכְתְּךָ֙ וּמֵאַ֣יִן תָּב֔וֹא מָ֣ה אַרְצֶ֔ךָ וְאֵֽי־מִזֶּ֥ה עַ֖ם אָֽתָּה׃","wayò̇ʼmĕr֣ẇ ʼélá֔yw hagi̇ydáh- ná֣̇ʼ lá֔nẇ bȧʼàşě֛r lĕmiy-háráʻá֥h hazò֖̇ʼţ lá֑nẇ mah-mĕ̇laʼkĕţĕ̇ká֙ ẇméʼa֣yin ţá̇b֔wòʼ má֣h ʼarĕẕe֔ká wĕʼéֽy-mizė֥h ʻa֖m ʼáֽţá̇h׃"],[1,9,"וַיֹּ֥אמֶר אֲלֵיהֶ֖ם עִבְרִ֣י אָנֹ֑כִי וְאֶת־יְהוָ֞ה אֱלֹהֵ֤י הַשָּׁמַ֙יִם֙ אֲנִ֣י יָרֵ֔א אֲשֶׁר־עָשָׂ֥ה אֶת־הַיָּ֖ם וְאֶת־הַיַּבָּשָֽׁה׃","wayò֥̇ʼmer ʼàléyhe֖m ʻibĕri֣y ʼánò֑kiy wĕʼeţ-yĕhwá֞h ʼèlòhé֤y haşá̇̌ma֙yim֙ ʼàni֣y yáré֔ʼ ʼàşěr-ʻáşá֥̂h ʼeţ-hayá֖̇m wĕʼeţ-hayȧbá̇şáֽ̌h׃"],[1,10,"וַיִּֽירְא֤וּ הָֽאֲנָשִׁים֙ יִרְאָ֣ה גְדוֹלָ֔ה וַיֹּאמְר֥וּ אֵלָ֖יו מַה־זֹּ֣את עָשִׂ֑יתָ כִּֽי־יָדְע֣וּ הָאֲנָשִׁ֗ים כִּֽי־מִלִּפְנֵ֤י יְהוָה֙ ה֣וּא בֹרֵ֔חַ כִּ֥י הִגִּ֖יד לָהֶֽם׃","wayiֽ̇yrĕʼ֤ẇ háֽʼànáşǐym֙ yirĕʼá֣h gĕdwòlá֔h wayò̇ʼmĕr֥ẇ ʼélá֖yw mah-zò֣̇ʼţ ʻáşî֑yţá kiֽ̇y-yádĕʻ֣ẇ háʼànáşǐ֗ym kiֽ̇y-mili̇pĕné֤y yĕhwáh֙ h֣ẇʼ bòré֔ẖa ki֥̇y higi֖̇yd láheֽm׃"],[1,11,"וַיֹּאמְר֤וּ אֵלָיו֙ מַה־נַּ֣עֲשֶׂה לָּ֔ךְ וְיִשְׁתֹּ֥ק הַיָּ֖ם מֵֽעָלֵ֑ינוּ כִּ֥י הַיָּ֖ם הוֹלֵ֥ךְ וְסֹעֵֽר׃","wayò̇ʼmĕr֤ẇ ʼéláyw֙ mah-nȧ֣ʻàşêh lá̇֔kĕ wĕyişĕ̌ţò֥̇q hayá֖̇m méֽʻálé֑ynẇ ki֥̇y hayá֖̇m hwòlé֥kĕ wĕsòʻéֽr׃"],[1,12,"וַיֹּ֣אמֶר אֲלֵיהֶ֗ם שָׂא֙וּנִי֙ וַהֲטִילֻ֣נִי אֶל־הַיָּ֔ם וְיִשְׁתֹּ֥ק הַיָּ֖ם מֵֽעֲלֵיכֶ֑ם כִּ֚י יוֹדֵ֣עַ אָ֔נִי כִּ֣י בְשֶׁלִּ֔י הַסַּ֧עַר הַגָּד֛וֹל הַזֶּ֖ה עֲלֵיכֶֽם׃","wayò֣̇ʼmer ʼàléyhe֗m şá̂ʼ֙ẇniy֙ wahàtiylu֣niy ʼel-hayá̇֔m wĕyişĕ̌ţò֥̇q hayá֖̇m méֽʻàléyke֑m ki֚̇y ywòdé֣ʻa ʼá֔niy ki֣̇y bĕşěli̇֔y hasȧ֧ʻar hagá̇d֛wòl hazė֖h ʻàléykeֽm׃"],[1,13,"וַיַּחְתְּר֣וּ הָאֲנָשִׁ֗ים לְהָשִׁ֛יב אֶל־הַיַּבָּשָׁ֖ה וְלֹ֣א יָכֹ֑לוּ כִּ֣י הַיָּ֔ם הוֹלֵ֥ךְ וְסֹעֵ֖ר עֲלֵיהֶֽם׃","wayȧẖĕţĕ̇r֣ẇ háʼànáşǐ֗ym lĕháşǐ֛yb ʼel-hayȧbá̇şá֖̌h wĕlò֣ʼ yákò֑lẇ ki֣̇y hayá̇֔m hwòlé֥kĕ wĕsòʻé֖r ʻàléyheֽm׃"],[1,14,"וַיִּקְרְא֨וּ אֶל־יְהוָ֜ה וַיֹּאמְר֗וּ אָנָּ֤ה יְהוָה֙ אַל־נָ֣א נֹאבְדָ֗ה בְּנֶ֙פֶשׁ֙ הָאִ֣ישׁ הַזֶּ֔ה וְאַל־תִּתֵּ֥ן עָלֵ֖ינוּ דָּ֣ם נָקִ֑יא כִּֽי־אַתָּ֣ה יְהוָ֔ה כַּאֲשֶׁ֥ר חָפַ֖צְתָּ עָשִֽׂיתָ׃","wayi̇qĕrĕʼ֨ẇ ʼel-yĕhwá֜h wayò̇ʼmĕr֗ẇ ʼáná֤̇h yĕhwáh֙ ʼal-ná֣ʼ nòʼbĕdá֗h bĕ̇ne֙peş̌֙ háʼi֣yş̌ hazė֔h wĕʼal-ţi̇ţé֥̇n ʻálé֖ynẇ dá֣̇m náqi֑yʼ kiֽ̇y-ʼaţá֣̇h yĕhwá֔h kȧʼàşě֥r ẖápa֖ẕĕţá̇ ʻáşîֽyţá׃"],[1,15,"וַיִּשְׂאוּ֙ אֶת־יוֹנָ֔ה וַיְטִלֻ֖הוּ אֶל־הַיָּ֑ם וַיַּעֲמֹ֥ד הַיָּ֖ם מִזַּעְפּֽוֹ ׃","wayi̇şĕ̂ʼẇ֙ ʼeţ-ywòná֔h wayĕtilu֖hẇ ʼel-hayá֑̇m wayȧʻàmò֥d hayá֖̇m mizȧʻĕṗֽwò ׃"],[1,16,"וַיִּֽירְא֧וּ הָאֲנָשִׁ֛ים יִרְאָ֥ה גְדוֹלָ֖ה אֶת־יְהוָ֑ה וַיִּֽזְבְּחוּ־זֶ֙בַח֙ לַֽיהוָ֔ה וַֽיִּדְּר֖וּ נְדָרִֽים׃","wayiֽ̇yrĕʼ֧ẇ háʼànáşǐ֛ym yirĕʼá֥h gĕdwòlá֖h ʼeţ-yĕhwá֑h wayiֽ̇zĕbĕ̇ẖẇ-ze֙baẖ֙ laֽyhwá֔h waֽyi̇dĕ̇r֖ẇ nĕdáriֽym׃"],[2,1,"וַיְמַ֤ן יְהוָה֙ דָּ֣ג גָּד֔וֹל לִבְלֹ֖עַ אֶת־יוֹנָ֑ה וַיְהִ֤י יוֹנָה֙ בִּמְעֵ֣י הַדָּ֔ג שְׁלֹשָׁ֥ה יָמִ֖ים וּשְׁלֹשָׁ֥ה לֵילֽוֹת׃","wayĕma֤n yĕhwáh֙ dá֣̇g gá̇d֔wòl libĕlò֖ʻa ʼeţ-ywòná֑h wayĕhi֤y ywònáh֙ bi̇mĕʻé֣y hadá̇֔g şĕ̌lòşá֥̌h yámi֖ym ẇşĕ̌lòşá֥̌h léylֽwòţ׃"],[2,2,"וַיִּתְפַּלֵּ֣ל יוֹנָ֔ה אֶל־יְהוָ֖ה אֱלֹהָ֑יו מִמְּעֵ֖י הַדָּגָֽה׃","wayi̇ţĕpȧlé֣̇l ywòná֔h ʼel-yĕhwá֖h ʼèlòhá֑yw mimĕ̇ʻé֖y hadá̇gáֽh׃"],[2,3,"וַיֹּ֗אמֶר קָ֠רָאתִי מִצָּ֥רָה לִ֛י אֶל־יְהוָ֖ה וַֽיַּעֲנֵ֑נִי מִבֶּ֧טֶן שְׁא֛וֹל שִׁוַּ֖עְתִּי שָׁמַ֥עְתָּ קוֹלִֽי׃","wayò̇֗ʼmer qá֠ráʼţiy miẕá֥̇ráh li֛y ʼel-yĕhwá֖h waֽyȧʻàné֑niy mibė֧ten şĕ̌ʼ֛wòl şǐwȧ֖ʻĕţi̇y şá̌ma֥ʻĕţá̇ qwòliֽy׃"],[2,4,"וַתַּשְׁלִיכֵ֤נִי מְצוּלָה֙ בִּלְבַ֣ב יַמִּ֔ים וְנָהָ֖ר יְסֹבְבֵ֑נִי כָּל־מִשְׁבָּרֶ֥יךָ וְגַלֶּ֖יךָ עָלַ֥י עָבָֽרוּ׃","waţȧşĕ̌liyké֤niy mĕẕẇláh֙ bi̇lĕba֣b yami̇֔ym wĕnáhá֖r yĕsòbĕbé֑niy ká̇l-mişĕ̌bá̇re֥yká wĕgalė֖yká ʻála֥y ʻábáֽrẇ׃"],[2,5,"וַאֲנִ֣י אָמַ֔רְתִּי נִגְרַ֖שְׁתִּי מִנֶּ֣גֶד עֵינֶ֑יךָ אַ֚ךְ אוֹסִ֣יף לְהַבִּ֔יט אֶל־הֵיכַ֖ל קָדְשֶֽׁךָ׃","waʼàni֣y ʼáma֔rĕţi̇y nigĕra֖şĕ̌ţi̇y minė֣ged ʻéyne֑yká ʼa֚kĕ ʼwòsi֣yp lĕhabi̇֔yt ʼel-héyka֖l qádĕşěֽká׃"],[2,6,"אֲפָפ֤וּנִי מַ֙יִם֙ עַד־נֶ֔פֶשׁ תְּה֖וֹם יְסֹבְבֵ֑נִי ס֖וּף חָב֥וּשׁ לְרֹאשִֽׁי׃","ʼàpáp֤ẇniy ma֙yim֙ ʻad-ne֔peş̌ ţĕ̇h֖wòm yĕsòbĕbé֑niy s֖ẇp ẖáb֥ẇş̌ lĕròʼşǐֽy׃"],[2,7,"לְקִצְבֵ֤י הָרִים֙ יָרַ֔דְתִּי הָאָ֛רֶץ בְּרִחֶ֥יהָ בַעֲדִ֖י לְעוֹלָ֑ם וַתַּ֧עַל מִשַּׁ֛חַת חַיַּ֖י יְהוָ֥ה אֱלֹהָֽי׃","lĕqiẕĕbé֤y háriym֙ yára֔dĕţi̇y háʼá֛reẕ bĕ̇riẖe֥yhá baʻàdi֖y lĕʻwòlá֑m waţȧ֧ʻal mişȧ֛̌ẖaţ ẖayȧ֖y yĕhwá֥h ʼèlòháֽy׃"],[2,8,"בְּהִתְעַטֵּ֤ף עָלַי֙ נַפְשִׁ֔י אֶת־יְהוָ֖ה זָכָ֑רְתִּי וַתָּב֤וֹא אֵלֶ֙יךָ֙ תְּפִלָּתִ֔י אֶל־הֵיכַ֖ל קָדְשֶֽׁךָ׃","bĕ̇hiţĕʻaté֤̇p ʻálay֙ napĕşǐ֔y ʼeţ-yĕhwá֖h záká֑rĕţi̇y waţá̇b֤wòʼ ʼéle֙yká֙ ţĕ̇pilá̇ţi֔y ʼel-héyka֖l qádĕşěֽká׃"],[2,9,"מְשַׁמְּרִ֖ים הַבְלֵי־שָׁ֑וְא חַסְדָּ֖ם יַעֲזֹֽבוּ׃","mĕşǎmĕ̇ri֖ym habĕléy-şá֑̌wĕʼ ẖasĕdá֖̇m yaʻàzòֽbẇ׃"],[2,10,"וַאֲנִ֗י בְּק֤וֹל תּוֹדָה֙ אֶזְבְּחָה־לָּ֔ךְ אֲשֶׁ֥ר נָדַ֖רְתִּי אֲשַׁלֵּ֑מָה יְשׁוּעָ֖תָה לַיהוָֽה׃ ס","waʼàni֗y bĕ̇q֤wòl ţ̇wòdáh֙ ʼezĕbĕ̇ẖáh-lá̇֔kĕ ʼàşě֥r náda֖rĕţi̇y ʼàşǎlé֑̇máh yĕş̌ẇʻá֖ţáh layhwáֽh׃ s"],[2,11,"וַיֹּ֥אמֶר יְהוָ֖ה לַדָּ֑ג וַיָּקֵ֥א אֶת־יוֹנָ֖ה אֶל־הַיַּבָּשָֽׁה׃ פ","wayò֥̇ʼmer yĕhwá֖h ladá֑̇g wayá̇qé֥ʼ ʼeţ-ywòná֖h ʼel-hayȧbá̇şáֽ̌h׃ p"],[3,1,"וַיְהִ֧י דְבַר־יְהוָ֛ה אֶל־יוֹנָ֖ה שֵׁנִ֥ית לֵאמֹֽר׃","wayĕhi֧y dĕbar-yĕhwá֛h ʼel-ywòná֖h şé̌ni֥yţ léʼmòֽr׃"],[3,2,"ק֛וּם לֵ֥ךְ אֶל־נִֽינְוֵ֖ה הָעִ֣יר הַגְּדוֹלָ֑ה וִּקְרָ֤א אֵלֶ֙יהָ֙ אֶת־הַקְּרִיאָ֔ה אֲשֶׁ֥ר אָנֹכִ֖י דֹּבֵ֥ר אֵלֶֽיךָ׃","q֛ẇm lé֥kĕ ʼel-niֽynĕwé֖h háʻi֣yr hagĕ̇dwòlá֑h wi̇qĕrá֤ʼ ʼéle֙yhá֙ ʼeţ-haqĕ̇riyʼá֔h ʼàşě֥r ʼánòki֖y dò̇bé֥r ʼéleֽyká׃"],[3,3,"וַיָּ֣קָם יוֹנָ֗ה וַיֵּ֛לֶךְ אֶל־נִֽינְוֶ֖ה כִּדְבַ֣ר יְהוָ֑ה וְנִֽינְוֵ֗ה הָיְתָ֤ה עִיר־גְּדוֹלָה֙ לֵֽאלֹהִ֔ים מַהֲלַ֖ךְ שְׁלֹ֥שֶׁת יָמִֽים׃","wayá֣̇qám ywòná֗h wayé֛̇lekĕ ʼel-niֽynĕwe֖h ki̇dĕba֣r yĕhwá֑h wĕniֽynĕwé֗h háyĕţá֤h ʻiyr-gĕ̇dwòláh֙ léֽʼlòhi֔ym mahàla֖kĕ şĕ̌lò֥şěţ yámiֽym׃"],[3,4,"וַיָּ֤חֶל יוֹנָה֙ לָב֣וֹא בָעִ֔יר מַהֲלַ֖ךְ י֣וֹם אֶחָ֑ד וַיִּקְרָא֙ וַיֹּאמַ֔ר ע֚וֹד אַרְבָּעִ֣ים י֔וֹם וְנִֽינְוֵ֖ה נֶהְפָּֽכֶת׃","wayá֤̇ẖel ywònáh֙ láb֣wòʼ báʻi֔yr mahàla֖kĕ y֣wòm ʼeẖá֑d wayi̇qĕráʼ֙ wayò̇ʼma֔r ʻ֚wòd ʼarĕbá̇ʻi֣ym y֔wòm wĕniֽynĕwé֖h nehĕpáֽ̇keţ׃"],[3,5,"וַֽיַּאֲמִ֛ינוּ אַנְשֵׁ֥י נִֽינְוֵ֖ה בֵּֽאלֹהִ֑ים וַיִּקְרְאוּ־צוֹם֙ וַיִּלְבְּשׁ֣וּ שַׂקִּ֔ים מִגְּדוֹלָ֖ם וְעַד־קְטַנָּֽם ׃","waֽyȧʼàmi֛ynẇ ʼanĕşé֥̌y niֽynĕwé֖h béֽ̇ʼlòhi֑ym wayi̇qĕrĕʼẇ-ẕwòm֙ wayi̇lĕbĕ̇ş֣̌ẇ şâqi̇֔ym migĕ̇dwòlá֖m wĕʻad-qĕtanáֽ̇m ׃"],[3,6,"וַיִּגַּ֤ע הַדָּבָר֙ אֶל־מֶ֣לֶך נִֽינְוֵ֔ה וַיָּ֙קָם֙ מִכִּסְא֔וֹ וַיַּעֲבֵ֥ר אַדַּרְתּ֖וֹ מֵֽעָלָ֑יו וַיְכַ֣ס שַׂ֔ק וַיֵּ֖שֶׁב עַל־הָאֵֽפֶר׃","wayi̇gȧ֤ʻ hadá̇bár֙ ʼel-me֣lek niֽynĕwé֔h wayá̇֙qám֙ miki̇sĕʼ֔wò wayȧʻàbé֥r ʼadȧrĕţ֖̇wò méֽʻálá֑yw wayĕka֣s şâ֔q wayé֖̇şěb ʻal-háʼéֽper׃"],[3,7,"וַיַּזְעֵ֗ק וַיֹּ֙אמֶר֙ בְּנִֽינְוֵ֔ה מִטַּ֧עַם הַמֶּ֛לֶךְ וּגְדֹלָ֖יו לֵאמֹ֑ר הָאָדָ֨ם וְהַבְּהֵמָ֜ה הַבָּקָ֣ר וְהַצֹּ֗אן אַֽל־יִטְעֲמוּ֙ מְא֔וּמָה אַ֨ל־יִרְע֔וּ וּמַ֖יִם אַל־יִשְׁתּֽוּ׃","wayȧzĕʻé֗q wayò̇֙ʼmer֙ bĕ̇niֽynĕwé֔h mitȧ֧ʻam hamė֛lekĕ ẇgĕdòlá֖yw léʼmò֑r háʼádá֨m wĕhabĕ̇hémá֜h habá̇qá֣r wĕhaẕò̇֗ʼn ʼaֽl-yitĕʻàmẇ֙ mĕʼ֔ẇmáh ʼa֨l-yirĕʻ֔ẇ ẇma֖yim ʼal-yişĕ̌ţֽ̇ẇ׃"],[3,8,"וְיִתְכַּסּ֣וּ שַׂקִּ֗ים הָֽאָדָם֙ וְהַבְּהֵמָ֔ה וְיִקְרְא֥וּ אֶל־אֱלֹהִ֖ים בְּחָזְקָ֑ה וְיָשֻׁ֗בוּ אִ֚ישׁ מִדַּרְכּ֣וֹ הָֽרָעָ֔ה וּמִן־הֶחָמָ֖ס אֲשֶׁ֥ר בְּכַפֵּיהֶֽם ׃","wĕyiţĕkȧṡ֣ẇ şâqi̇֗ym háֽʼádám֙ wĕhabĕ̇hémá֔h wĕyiqĕrĕʼ֥ẇ ʼel-ʼèlòhi֖ym bĕ̇ẖázĕqá֑h wĕyáşǔ֗bẇ ʼi֚yş̌ midȧrĕk֣̇wò háֽráʻá֔h ẇmin-heẖámá֖s ʼàşě֥r bĕ̇kapé̇yheֽm ׃"],[3,9,"מִֽי־יוֹדֵ֣עַ יָשׁ֔וּב וְנִחַ֖ם הָאֱלֹהִ֑ים וְשָׁ֛ב מֵחֲר֥וֹן אַפּ֖וֹ וְלֹ֥א נֹאבֵֽד׃","miֽy-ywòdé֣ʻa yáş̌֔ẇb wĕniẖa֖m háʼèlòhi֑ym wĕşá֛̌b méẖàr֥wòn ʼaṗ֖wò wĕlò֥ʼ nòʼbéֽd׃"],[3,10,"וַיַּ֤רְא הָֽאֱלֹהִים֙ אֶֽת־מַ֣עֲשֵׂיהֶ֔ם כִּי־שָׁ֖בוּ מִדַּרְכָּ֣ם הָרָעָ֑ה וַיִּנָּ֣חֶם הָאֱלֹהִ֗ים עַל־הָרָעָ֛ה אֲשֶׁר־דִּבֶּ֥ר לַעֲשׂוֹת־לָהֶ֖ם וְלֹ֥א עָשָֽׂה׃","wayȧ֤rĕʼ háֽʼèlòhiym֙ ʼeֽţ-ma֣ʻàşé̂yhe֔m ki̇y-şá֖̌bẇ midȧrĕká֣̇m háráʻá֑h wayi̇ná֣̇ẖem háʼèlòhi֗ym ʻal-háráʻá֛h ʼàşěr-di̇bė֥r laʻàş̂wòţ-láhe֖m wĕlò֥ʼ ʻáşáֽ̂h׃"],[4,1,"וַיֵּ֥רַע אֶל־יוֹנָ֖ה רָעָ֣ה גְדוֹלָ֑ה וַיִּ֖חַר לֽוֹ׃","wayé֥̇raʻ ʼel-ywòná֖h ráʻá֣h gĕdwòlá֑h wayi֖̇ẖar lֽwò׃"],[4,2,"וַיִּתְפַּלֵּ֨ל אֶל־יְהוָ֜ה וַיֹּאמַ֗ר אָנָּ֤ה יְהוָה֙ הֲלוֹא־זֶ֣ה דְבָרִ֗י עַד־הֱיוֹתִי֙ עַל־אַדְמָתִ֔י עַל־כֵּ֥ן קִדַּ֖מְתִּי לִבְרֹ֣חַ תַּרְשִׁ֑ישָׁה כִּ֣י יָדַ֗עְתִּי כִּ֤י אַתָּה֙ אֵֽל־חַנּ֣וּן וְרַח֔וּם אֶ֤רֶךְ אַפַּ֙יִם֙ וְרַב־חֶ֔סֶד וְנִחָ֖ם עַל־הָרָעָֽה׃","wayi̇ţĕpȧlé̇֨l ʼel-yĕhwá֜h wayò̇ʼma֗r ʼáná֤̇h yĕhwáh֙ hàlwòʼ-ze֣h dĕbári֗y ʻad-hèywòţiy֙ ʻal-ʼadĕmáţi֔y ʻal-ké֥̇n qidȧ֖mĕţi̇y libĕrò֣ẖa ţȧrĕşǐ֑yşá̌h ki֣̇y yáda֗ʻĕţi̇y ki֤̇y ʼaţá̇h֙ ʼéֽl-ẖaṅ֣ẇn wĕraẖ֔ẇm ʼe֤rekĕ ʼapȧ֙yim֙ wĕrab-ẖe֔sed wĕniẖá֖m ʻal-háráʻáֽh׃"],[4,3,"וְעַתָּ֣ה יְהוָ֔ה קַח־נָ֥א אֶת־נַפְשִׁ֖י מִמֶּ֑נִּי כִּ֛י ט֥וֹב מוֹתִ֖י מֵחַיָּֽי׃ ס","wĕʻaţá֣̇h yĕhwá֔h qaẖ-ná֥ʼ ʼeţ-napĕşǐ֖y mimė֑ni̇y ki֛̇y t֥wòb mwòţi֖y méẖayáֽ̇y׃ s"],[4,4,"וַיֹּ֣אמֶר יְהוָ֔ה הַהֵיטֵ֖ב חָ֥רָה לָֽךְ׃","wayò֣̇ʼmer yĕhwá֔h hahéyté֖b ẖá֥ráh láֽkĕ׃"],[4,5,"וַיֵּצֵ֤א יוֹנָה֙ מִן־הָעִ֔יר וַיֵּ֖שֶׁב מִקֶּ֣דֶם לָעִ֑יר וַיַּעַשׂ֩ ל֨וֹ שָׁ֜ם סֻכָּ֗ה וַיֵּ֤שֶׁב תַּחְתֶּ֙יהָ֙ בַּצֵּ֔ל עַ֚ד אֲשֶׁ֣ר יִרְאֶ֔ה מַה־יִּהְיֶ֖ה בָּעִֽיר׃","wayé̇ẕé֤ʼ ywònáh֙ min-háʻi֔yr wayé֖̇şěb miqė֣dem láʻi֑yr wayȧʻaş̂֩ l֨wò şá̌֜m suká̇֗h wayé֤̇şěb ţȧẖĕţė֙yhá֙ bȧẕé̇֔l ʻa֚d ʼàşě֣r yirĕʼe֔h mah-yi̇hĕye֖h bá̇ʻiֽyr׃"],[4,6,"וַיְמַ֣ן יְהוָֽה־אֱ֠לֹהִים קִיקָי֞וֹן וַיַּ֣עַל ׀ מֵעַ֣ל לְיוֹנָ֗ה לִֽהְי֥וֹת צֵל֙ עַל־רֹאשׁ֔וֹ לְהַצִּ֥יל ל֖וֹ מֵרָֽעָת֑וֹ וַיִּשְׂמַ֥ח יוֹנָ֛ה עַל־הַקִּֽיקָי֖וֹן שִׂמְחָ֥ה גְדוֹלָֽה׃","wayĕma֣n yĕhwáֽh-ʼè֠lòhiym qiyqáy֞wòn wayȧ֣ʻal ׀ méʻa֣l lĕywòná֗h liֽhĕy֥wòţ ẕél֙ ʻal-ròʼş̌֔wò lĕhaẕi֥̇yl l֖wò méráֽʻáţ֑wò wayi̇şĕ̂ma֥ẖ ywòná֛h ʻal-haqֽ̇iyqáy֖wòn şîmĕẖá֥h gĕdwòláֽh׃"],[4,7,"וַיְמַ֤ן הָֽאֱלֹהִים֙ תּוֹלַ֔עַת בַּעֲל֥וֹת הַשַּׁ֖חַר לַֽמָּחֳרָ֑ת וַתַּ֥ךְ אֶת־הַקִּֽיקָי֖וֹן וַיִּיבָֽשׁ׃","wayĕma֤n háֽʼèlòhiym֙ ţ̇wòla֔ʻaţ bȧʻàl֥wòţ haşȧ֖̌ẖar laֽmá̇ẖorá֑ţ waţȧ֥kĕ ʼeţ-haqiֽ̇yqáy֖wòn wayi̇ybáֽş̌׃"],[4,8,"וַיְהִ֣י ׀ כִּזְרֹ֣חַ הַשֶּׁ֗מֶשׁ וַיְמַ֨ן אֱלֹהִ֜ים ר֤וּחַ קָדִים֙ חֲרִישִׁ֔ית וַתַּ֥ךְ הַשֶּׁ֛מֶשׁ עַל־רֹ֥אשׁ יוֹנָ֖ה וַיִּתְעַלָּ֑ף וַיִּשְׁאַ֤ל אֶת־נַפְשׁוֹ֙ לָמ֔וּת וַיֹּ֕אמֶר ט֥וֹב מוֹתִ֖י מֵחַיָּֽי׃","wayĕhi֣y ׀ ki̇zĕrò֣ẖa haşė̌֗meş̌ wayĕma֨n ʼèlòhi֜ym r֤ẇẖa qádiym֙ ẖàriyşǐ֔yţ waţȧ֥kĕ haşė֛̌meş̌ ʻal-rò֥ʼş̌ ywòná֖h wayi̇ţĕʻalá֑̇p wayi̇şĕ̌ʼa֤l ʼeţ-napĕş̌wò֙ lám֔ẇţ wayò̇֕ʼmer t֥wòb mwòţi֖y méẖayáֽ̇y׃"],[4,9,"וַיֹּ֤אמֶר אֱלֹהִים֙ אֶל־יוֹנָ֔ה הַהֵיטֵ֥ב חָרָֽה־לְךָ֖ עַל־הַקִּֽיקָי֑וֹן וַיֹּ֕אמֶר הֵיטֵ֥ב חָֽרָה־לִ֖י עַד־מָֽוֶת׃","wayò֤̇ʼmer ʼèlòhiym֙ ʼel-ywòná֔h hahéyté֥b ẖáráֽh-lĕká֖ ʻal-haqiֽ̇yqáy֑wòn wayò̇֕ʼmer héyté֥b ẖáֽráh-li֖y ʻad-máֽweţ׃"],[4,10,"וַיֹּ֣אמֶר יְהוָ֔ה אַתָּ֥ה חַ֙סְתָּ֙ עַל־הַקִּ֣יקָי֔וֹן אֲשֶׁ֛ר לֹא־עָמַ֥לְתָּ בּ֖וֹ וְלֹ֣א גִדַּלְתּ֑וֹ שֶׁבִּן־לַ֥יְלָה הָיָ֖ה וּבִן־לַ֥יְלָה אָבָֽד׃","wayò֣̇ʼmer yĕhwá֔h ʼaţá֥̇h ẖa֙sĕţá̇֙ ʻal-haqi֣̇yqáy֔wòn ʼàşě֛r lòʼ-ʻáma֥lĕţá̇ ḃ֖wò wĕlò֣ʼ gidȧlĕţ֑̇wò şěbi̇n-la֥yĕláh háyá֖h ẇbin-la֥yĕláh ʼábáֽd׃"],[4,11,"וַֽאֲנִי֙ לֹ֣א אָח֔וּס עַל־נִינְוֵ֖ה הָעִ֣יר הַגְּדוֹלָ֑ה אֲשֶׁ֣ר יֶשׁ־בָּ֡הּ הַרְבֵּה֩ מִֽשְׁתֵּים־עֶשְׂרֵ֨ה רִבּ֜וֹ אָדָ֗ם אֲשֶׁ֤ר לֹֽא־יָדַע֙ בֵּין־יְמִינ֣וֹ לִשְׂמֹאל֔וֹ וּבְהֵמָ֖ה רַבָּֽה׃","waֽʼàniy֙ lò֣ʼ ʼáẖ֔ẇs ʻal-niynĕwé֖h háʻi֣yr hagĕ̇dwòlá֑h ʼàşě֣r yeş̌-bá̇֡ḣ harĕbé̇h֩ miֽşĕ̌ţé̇ym-ʻeşĕ̂ré֨h riḃ֜wò ʼádá֗m ʼàşě֤r lòֽʼ-yádaʻ֙ bé̇yn-yĕmiyn֣wò lişĕ̂mòʼl֔wò ẇbĕhémá֖h rabáֽ̇h׃"]],"fra-giguet-lxx":[[1,1,"Et la parole du Seigneur vint à Jonas, fils d’Amathi, disant:","Et la parole du Seigneur vint à Jonas, fils d’Amathi, disant:"],[1,2,"Lève-toi, et pars pour Ninive, la grande ville, et proclame dans ses murs que le cri de sa méchanceté est monté jusqu’à moi.","Lève-toi, et pars pour Ninive, la grande ville, et proclame dans ses murs que le cri de sa méchanceté est monté jusqu’à moi."],[1,3,"Et Jonas se leva pour s’enfuir à Tharsis, loin de la face du Seigneur; et il descendit à Joppé; il y trouva une barque allant à Tharsis, et il paya son passage, et il s’embarqua pour naviguer avec les matelots, jusqu’à Tharsis, loin de la face du Seigneur.","Et Jonas se leva pour s’enfuir à Tharsis, loin de la face du Seigneur; et il descendit à Joppé; il y trouva une barque allant à Tharsis, et il paya son passage, et il s’embarqua pour naviguer avec les matelots, jusqu’à Tharsis, loin de la face du Seigneur."],[1,4,"Et le Seigneur excita un grand vent sur la mer, et les vagues s’élevèrent, et la barque fut en danger de se rompre.","Et le Seigneur excita un grand vent sur la mer, et les vagues s’élevèrent, et la barque fut en danger de se rompre."],[1,5,"Et les matelots eurent crainte, et ils crièrent chacun vers son dieu, et ils lancèrent à la mer le chargement de la barque, pour s’en alléger. Jonas descendit à fond de cale, et là il s’endormit, et il ronfla.","Et les matelots eurent crainte, et ils crièrent chacun vers son dieu, et ils lancèrent à la mer le chargement de la barque, pour s’en alléger. Jonas descendit à fond de cale, et là il s’endormit, et il ronfla."],[1,6,"Et le pilote l’alla trouver, et il lui dit: Pourquoi ronfles-tu? Lève-toi, et invoque ton Dieu, afin que Dieu nous sauve, et que nous ne mourions pas.","Et le pilote l’alla trouver, et il lui dit: Pourquoi ronfles-tu? Lève-toi, et invoque ton Dieu, afin que Dieu nous sauve, et que nous ne mourions pas."],[1,7,"Et chacun des matelots dit à son voisin: Allons, agitons les sorts, et sachons par qui ce malheur nous arrive. Et ils agitèrent des sorts, et le sort tomba sur Jonas.","Et chacun des matelots dit à son voisin: Allons, agitons les sorts, et sachons par qui ce malheur nous arrive. Et ils agitèrent des sorts, et le sort tomba sur Jonas."],[1,8,"Et ils lui dirent: Déclare-nous quel est ton métier; d’où viens-tu? de quelle contrée, de quel peuple es-tu?","Et ils lui dirent: Déclare-nous quel est ton métier; d’où viens-tu? de quelle contrée, de quel peuple es-tu?"],[1,9,"Et il leur dit: Je suis un serviteur du Seigneur; j’adore le Seigneur Dieu du ciel, qui a créé la mer et la terre.","Et il leur dit: Je suis un serviteur du Seigneur; j’adore le Seigneur Dieu du ciel, qui a créé la mer et la terre."],[1,10,"Et ces hommes eurent grande crainte, et ils lui dirent Pourquoi as-tu fait cela? Car ces hommes connurent qu’il fuyait loin de la face du Seigneur; car il le leur avait déclaré.","Et ces hommes eurent grande crainte, et ils lui dirent Pourquoi as-tu fait cela? Car ces hommes connurent qu’il fuyait loin de la face du Seigneur; car il le leur avait déclaré."],[1,11,"Et ils lui dirent: Que te ferons-nous, afin que pour nous la mer se calme? Car la mer allait, et soulevait encore plus de vagues.","Et ils lui dirent: Que te ferons-nous, afin que pour nous la mer se calme? Car la mer allait, et soulevait encore plus de vagues."],[1,12,"Et Jonas leur dit: Prenez-moi et jetez-moi à la mer, et la mer se calmera pour vous; car je sais que c’est à cause de moi qu’il y a contre vous ces grandes vagues.","Et Jonas leur dit: Prenez-moi et jetez-moi à la mer, et la mer se calmera pour vous; car je sais que c’est à cause de moi qu’il y a contre vous ces grandes vagues."],[1,13,"Et ces hommes s’efforcèrent de retourner à la côte; mais ils ne le purent, parce que la mer allait et soulevait contre eux toujours plus de vagues.","Et ces hommes s’efforcèrent de retourner à la côte; mais ils ne le purent, parce que la mer allait et soulevait contre eux toujours plus de vagues."],[1,14,"Et ils crièrent au Seigneur, et ils dirent: Non, Seigneur, que nous ne périssions pas pour la vie de cet homme; ne faites pas retomber sur nous un sang innocent; car, Seigneur, vous avez fait selon votre volonté.","Et ils crièrent au Seigneur, et ils dirent: Non, Seigneur, que nous ne périssions pas pour la vie de cet homme; ne faites pas retomber sur nous un sang innocent; car, Seigneur, vous avez fait selon votre volonté."],[1,15,"Et ils prirent Jonas, et ils le lancèrent à la mer; et la mer cessa de s’agiter.","Et ils prirent Jonas, et ils le lancèrent à la mer; et la mer cessa de s’agiter."],[1,16,"Et ces hommes eurent grande crainte du Seigneur; et ils offrirent au Seigneur un sacrifice, et ils lui firent des vœux.","Et ces hommes eurent grande crainte du Seigneur; et ils offrirent au Seigneur un sacrifice, et ils lui firent des vœux."],[2,1,"Et le Seigneur prescrivit à une grande baleine d’avaler Jonas, et Jonas fut dans le ventre de la baleine trois jours et trois nuits.","Et le Seigneur prescrivit à une grande baleine d’avaler Jonas, et Jonas fut dans le ventre de la baleine trois jours et trois nuits."],[2,2,"Et Jonas pria le Seigneur son Dieu, dans le ventre de la baleine.","Et Jonas pria le Seigneur son Dieu, dans le ventre de la baleine."],[2,3,"Et il dit: J’ai crié dans mà tribulation au Seigneur mon Dieu, et il m’a exaucé; mon cri est parti des entrailles de l’enfer, et vous avez écouté ma voix;","Et il dit: J’ai crié dans mà tribulation au Seigneur mon Dieu, et il m’a exaucé; mon cri est parti des entrailles de l’enfer, et vous avez écouté ma voix;"],[2,4,"Vous m’avez précipité au plus profond du cœur de la mer; et les fleuves m’ont enveloppé, et toutes vos grandes vagues, tous vos flots ont passé sur moi.","Vous m’avez précipité au plus profond du cœur de la mer; et les fleuves m’ont enveloppé, et toutes vos grandes vagues, tous vos flots ont passé sur moi."],[2,5,"Et j’ai dit: C’est moi qui me suis éloigné de vos yeux; me permettrez-vous de voir encore votre saint temple?","Et j’ai dit: C’est moi qui me suis éloigné de vos yeux; me permettrez-vous de voir encore votre saint temple?"],[2,6,"L’eau s’est répandue autour de moi, jusqu’à l’âme; l’abîme le plus profond m’a enclos, et ma tête a plongé","L’eau s’est répandue autour de moi, jusqu’à l’âme; l’abîme le plus profond m’a enclos, et ma tête a plongé"],[2,7,"Jusqu’aux racines des monts; je suis descendu sous la terre, dont les verrous sont des barrières éternelles. Seigneur mon Dieu, que la destruction de ma vie remonte à la surface des flots.","Jusqu’aux racines des monts; je suis descendu sous la terre, dont les verrous sont des barrières éternelles. Seigneur mon Dieu, que la destruction de ma vie remonte à la surface des flots."],[2,8,"En la défaillance de mon âme, je me suis souvenu de vous, Seigneur; que ma prière arrive à vous dans votre saint temple!","En la défaillance de mon âme, je me suis souvenu de vous, Seigneur; que ma prière arrive à vous dans votre saint temple!"],[2,9,"Ceux-là seuls qui s’attachent aux vanités et aux mensonges ont renoncé à votre miséricorde.","Ceux-là seuls qui s’attachent aux vanités et aux mensonges ont renoncé à votre miséricorde."],[2,10,"Pour moi, je vous offrirai dans mes chants un","Pour moi, je vous offrirai dans mes chants un"],[2,11,"Et le Seigneur donna ordre à la baleine, et elle rejeta Jonas sur la terre ferme.","Et le Seigneur donna ordre à la baleine, et elle rejeta Jonas sur la terre ferme."],[3,1,"Et la parole du Seigneur vint à Jonas pour la seconde fois, disant:","Et la parole du Seigneur vint à Jonas pour la seconde fois, disant:"],[3,2,"Lève-toi, et pars pour Ninive, la grande ville, et proclame dans ses murs la prédiction que je t’ai déjà prescrit de proclamer.","Lève-toi, et pars pour Ninive, la grande ville, et proclame dans ses murs la prédiction que je t’ai déjà prescrit de proclamer."],[3,3,"Et Jonas se leva; et il s’en alla à Ninive, comme lui avait dit le Seigneur. Or la ville de Ninive était grande de trois jours de marche.","Et Jonas se leva; et il s’en alla à Ninive, comme lui avait dit le Seigneur. Or la ville de Ninive était grande de trois jours de marche."],[3,4,"Et Jonas commença par entrer dans la ville et par faire environ un jour de marche, et il cria, et il dit: Encore trois jours, et Ninive sera détruite!","Et Jonas commença par entrer dans la ville et par faire environ un jour de marche, et il cria, et il dit: Encore trois jours, et Ninive sera détruite!"],[3,5,"Et les hommes de Ninive crurent en Dieu, et ils proclamèrent un jeûne, et ils se ceignirent de cilices, depuis le grand jusqu’au petit.","Et les hommes de Ninive crurent en Dieu, et ils proclamèrent un jeûne, et ils se ceignirent de cilices, depuis le grand jusqu’au petit."],[3,6,"Et la parole de Jonas arriva au roi de Ninive, et il se leva de son trône, et il ôta sa robe, et il se ceignit d’un cilice, et il s’assit sur la cendre.","Et la parole de Jonas arriva au roi de Ninive, et il se leva de son trône, et il ôta sa robe, et il se ceignit d’un cilice, et il s’assit sur la cendre."],[3,7,"Et il fut proclamé, et il fut dit en Ninive de la part du roi et de la part de ses grands, ce qui suit: Que ni hommes, ni bêtes, ni bœufs, ni brebis ne mangent, ne paissent, ne boivent même de l’eau.","Et il fut proclamé, et il fut dit en Ninive de la part du roi et de la part de ses grands, ce qui suit: Que ni hommes, ni bêtes, ni bœufs, ni brebis ne mangent, ne paissent, ne boivent même de l’eau."],[3,8,"Et les hommes et les bêtes furent couverts de cilices, et les hommes crièrent sans relâche au Seigneur. Et chacun revint de sa voie coupable et de l’iniquité de ses mains, disant:","Et les hommes et les bêtes furent couverts de cilices, et les hommes crièrent sans relâche au Seigneur. Et chacun revint de sa voie coupable et de l’iniquité de ses mains, disant:"],[3,9,"Qui sait si le Seigneur ne se repentira pas, et s’il ne calmera pas les transports de sa colère, pour que nous ne périssions point?","Qui sait si le Seigneur ne se repentira pas, et s’il ne calmera pas les transports de sa colère, pour que nous ne périssions point?"],[3,10,"Et Dieu vit leurs œuvres; il vit qu’ils revenaient de leurs voies coupables; et Dieu se repentit du mal qu’il avait voulu leur faire, et il ne le leur fit pas.","Et Dieu vit leurs œuvres; il vit qu’ils revenaient de leurs voies coupables; et Dieu se repentit du mal qu’il avait voulu leur faire, et il ne le leur fit pas."],[4,1,"Et Jonas fut affligé d’une grande tristesse, et il fut confondu,","Et Jonas fut affligé d’une grande tristesse, et il fut confondu,"],[4,2,"Et il pria le Seigneur, et il dit: Seigneur, n’est-ce pas là ce que je disais, quand j’étais encore en mon pays? Je m’étais hâté de fuir à Tharsis, parce que je vous sais plein de clémence et de compassion, patient et abondant en miséricorde, et que vous vous repentez du mal que vous vouliez faire aux hommes.","Et il pria le Seigneur, et il dit: Seigneur, n’est-ce pas là ce que je disais, quand j’étais encore en mon pays? Je m’étais hâté de fuir à Tharsis, parce que je vous sais plein de clémence et de compassion, patient et abondant en miséricorde, et que vous vous repentez du mal que vous vouliez faire aux hommes."],[4,3,"Maintenant donc, Seigneur mon maître, prenez-moi ma vie; car il vaut mieux pour moi mourir que vivre.","Maintenant donc, Seigneur mon maître, prenez-moi ma vie; car il vaut mieux pour moi mourir que vivre."],[4,4,"Et le Seigneur dit à Jonas: Pourquoi es-tu si vivement contristé?","Et le Seigneur dit à Jonas: Pourquoi es-tu si vivement contristé?"],[4,5,"Et Jonas sortit de Ninive, et il s’assit en face de la ville, et là il se fit une tente et il s’y établit, jusqu’à ce qu’il eut vu de loin ce qui arriverait à la ville.","Et Jonas sortit de Ninive, et il s’assit en face de la ville, et là il se fit une tente et il s’y établit, jusqu’à ce qu’il eut vu de loin ce qui arriverait à la ville."],[4,6,"Et le Seigneur Dieu donna ordre à une gourde, et sa tige et ses feuilles montèrent au-dessus de la tête de Jonas pour l’ombrager et le préserver de tout mal. Et Jonas eut une grande joie de cette gourde.","Et le Seigneur Dieu donna ordre à une gourde, et sa tige et ses feuilles montèrent au-dessus de la tête de Jonas pour l’ombrager et le préserver de tout mal. Et Jonas eut une grande joie de cette gourde."],[4,7,"Et Dieu donna ordre dès l’aurore à un ver qui rongea la gourde, et elle se dessécha.","Et Dieu donna ordre dès l’aurore à un ver qui rongea la gourde, et elle se dessécha."],[4,8,"Et il arriva, aux premiers rayons du soleil, que Dieu donna ordre à un vent chaud et ardent, et le soleil frappa sur la tête de Jonas, et celui-ci défaillit, et il désespéra de sa vie, et il dit: Mieux vaut pour moi mourir que vivre.","Et il arriva, aux premiers rayons du soleil, que Dieu donna ordre à un vent chaud et ardent, et le soleil frappa sur la tête de Jonas, et celui-ci défaillit, et il désespéra de sa vie, et il dit: Mieux vaut pour moi mourir que vivre."],[4,9,"Et le Seigneur dit à Jonas: Est-ce à cause de la gourde que tu es si fortement contristé? Et il répondit: Je suis triste jusqu’à la mort.","Et le Seigneur dit à Jonas: Est-ce à cause de la gourde que tu es si fortement contristé? Et il répondit: Je suis triste jusqu’à la mort."],[4,10,"Et le Seigneur dit: Tu as grande pitié pour une gourde qui ne t’avait donné aucune peine, que tu n’avais point cultivée, qui était venue en une nuit, et qui en une nuit a été détruite.","Et le Seigneur dit: Tu as grande pitié pour une gourde qui ne t’avait donné aucune peine, que tu n’avais point cultivée, qui était venue en une nuit, et qui en une nuit a été détruite."],[4,11,"Et moi, je n’épargnerai pas Ninive la grande ville, où demeurent plus de douze myriades d’hommes, qui ne savent pas distinguer leur main droite de leur main gauche; et des troupeaux si nombreux!","Et moi, je n’épargnerai pas Ninive la grande ville, où demeurent plus de douze myriades d’hommes, qui ne savent pas distinguer leur main droite de leur main gauche; et des troupeaux si nombreux!"]],"ell-vamvas1850":[[1,1,"Και έγεινε λόγος Κυρίου προς Ιωνάν τον υιόν του Αμαθί, λέγων,","Kai égeine lógos Kyríou pros Iōnán ton yión tou Amathí, légōn,"],[1,2,"Σηκώθητι, ύπαγε εις Νινευή, την πόλιν την μεγάλην, και κήρυξον κατ' αυτής· διότι η ασέβεια αυτών ανέβη ενώπιόν μου.","Sēkṓthēti, ýpage eis Nineuḗ, tēn pólin tēn megálēn, kai kḗryxon kat' autḗs: dióti ē asébeia autṓn anébē enṓpión mou."],[1,3,"Και εσηκώθη ο Ιωνάς διά να φύγη εις Θαρσείς από προσώπου Κυρίου και κατέβη εις Ιόππην· και εύρηκε πλοίον πορευόμενον εις Θαρσείς, και έδωκε τον ναύλον αυτού και επέβη εις αυτό, διά να υπάγη μετ' αυτών εις Θαρσείς από προσώπου Κυρίου.","Kai esēkṓthē o Iōnás diá na phýgē eis Tharseís apó prosṓpou Kyríou kai katébē eis Ióppēn: kai eúrēke ploíon poreuómenon eis Tharseís, kai édōke ton naúlon autoú kai epébē eis autó, diá na ypágē met' autṓn eis Tharseís apó prosṓpou Kyríou."],[1,4,"Αλλ' ο Κύριος εξήγειρεν άνεμον μέγαν επί την θάλασσαν, και έγεινε κλύδων μέγας εν τη θαλάσση και το πλοίον εκινδύνευε να συντριφθή.","All' o Kýrios exḗgeiren ánemon mégan epí tēn thálassan, kai égeine klýdōn mégas en tē thalássē kai to ploíon ekindýneue na syntriphthḗ."],[1,5,"Και εφοβήθησαν οι ναύται και ανεβόησαν έκαστος προς τον θεόν αυτού και έκαμον εκβολήν των εν τω πλοίω σκευών εις την θάλασσαν, διά να ελαφρωθή απ' αυτών· ο δε Ιωνάς κατέβη εις το κοίλωμα του πλοίου και επλαγίασε και εκοιμάτο βαθέως.","Kai ephobḗthēsan oi naútai kai anebóēsan ékastos pros ton theón autoú kai ékamon ekbolḗn tōn en tō ploíō skeuṓn eis tēn thálassan, diá na elaphrōthḗ ap' autṓn: o de Iōnás katébē eis to koílōma tou ploíou kai eplagíase kai ekoimáto bathéōs."],[1,6,"Και επλησίασε προς αυτόν ο πλοίαρχος και είπε προς αυτόν, Τι κοιμάσαι συ; σηκώθητι, επικαλού τον Θεόν σου, ίσως ο Θεός μας ενθυμηθή και δεν χαθώμεν.","Kai eplēsíase pros autón o ploíarchos kai eípe pros autón, Ti koimásai sy? sēkṓthēti, epikaloú ton Theón sou, ísōs o Theós mas enthymēthḗ kai den chathṓmen."],[1,7,"Και είπον έκαστος προς τον πλησίον αυτού, Έλθετε και ας ρίψωμεν κλήρους, διά να γνωρίσωμεν τίνος ένεκεν το κακόν τούτο είναι εφ' ημάς. Και έρριψαν κλήρους και έπεσεν ο κλήρος επί τον Ιωνάν.","Kai eípon ékastos pros ton plēsíon autoú, Élthete kai as rípsōmen klḗrous, diá na gnōrísōmen tínos éneken to kakón toúto eínai eph' ēmás. Kai érripsan klḗrous kai épesen o klḗros epí ton Iōnán."],[1,8,"Τότε είπον προς αυτόν, Ειπέ τώρα προς ημάς, τίνος ένεκεν το κακόν τούτο ήλθεν εφ' ημάς; Τι είναι το έργον σου; και πόθεν έρχεσαι; τις ο τόπος σου; και εκ τίνος λαού είσαι;","Tóte eípon pros autón, Eipé tṓra pros ēmás, tínos éneken to kakón toúto ḗlthen eph' ēmás? Ti eínai to érgon sou? kai póthen érchesai? tis o tópos sou? kai ek tínos laoú eísai?"],[1,9,"Ο δε είπε προς αυτούς, Εγώ είμαι Εβραίος· και σέβομαι Κύριον τον Θεόν του ουρανού, όστις εποίησε την θαλάσσαν και την ξηράν.","O de eípe pros autoús, Egṓ eímai Ebraíos: kai sébomai Kýrion ton Theón tou ouranoú, óstis epoíēse tēn thalássan kai tēn xērán."],[1,10,"Τότε εφοβήθησαν οι άνθρωποι φόβον μέγαν και είπον προς αυτόν, Τι είναι τούτο, το οποίον έκαμες; διότι εγνώρισαν οι άνθρωποι, ότι έφευγεν από προσώπου Κυρίου, επειδή είχεν αναγγείλει τούτο προς αυτούς.","Tóte ephobḗthēsan oi ánthrōpoi phóbon mégan kai eípon pros autón, Ti eínai toúto, to opoíon ékames? dióti egnṓrisan oi ánthrōpoi, óti épheugen apó prosṓpou Kyríou, epeidḗ eíchen anangeílei toúto pros autoús."],[1,11,"Και είπον προς αυτόν, Τι να σε κάμωμεν, διά να ησυχάση η θάλασσα αφ' ημών; διότι η θάλασσα εκλυδωνίζετο επί το μάλλον.","Kai eípon pros autón, Ti na se kámōmen, diá na ēsychásē ē thálassa aph' ēmṓn? dióti ē thálassa eklydōnízeto epí to mállon."],[1,12,"Και είπε προς αυτούς, Σηκώσατέ με και ρίψατέ με εις την θάλασσαν, και η θάλασσα θέλει ησυχάσει αφ' υμών· διότι εγώ γνωρίζω, ότι εξ αιτίας εμού έγεινεν ο μέγας ούτος κλύδων εφ' υμάς.","Kai eípe pros autoús, Sēkṓsaté me kai rípsaté me eis tēn thálassan, kai ē thálassa thélei ēsychásei aph' ymṓn: dióti egṓ gnōrízō, óti ex aitías emoú égeinen o mégas oútos klýdōn eph' ymás."],[1,13,"Οι άνθρωποι όμως εκωπηλάτουν δυνατά διά να επιστρέψωσι προς την ξηράν· αλλά δεν εδύναντο, διότι η θάλασσα εκλυδωνίζετο επί το μάλλον κατ' αυτών.","Oi ánthrōpoi ómōs ekōpēlátoun dynatá diá na epistrépsōsi pros tēn xērán: allá den edýnanto, dióti ē thálassa eklydōnízeto epí to mállon kat' autṓn."],[1,14,"Όθεν ανεβόησαν προς τον Κύριον και είπον, Δεόμεθα, Κύριε, δεόμεθα, ας μη χαθώμεν διά την ζωήν του ανθρώπου τούτου και μη επιβάλης εφ' ημάς αίμα αθώον· διότι συ, Κύριε, έκαμες ως ήθελες.","Óthen anebóēsan pros ton Kýrion kai eípon, Deómetha, Kýrie, deómetha, as mē chathṓmen diá tēn zōḗn tou anthrṓpou toútou kai mē epibálēs eph' ēmás aíma athṓon: dióti sy, Kýrie, ékames ōs ḗtheles."],[1,15,"Και εσήκωσαν τον Ιωνάν και έρριψαν αυτόν εις την θάλασσαν και η θάλασσα εστάθη από του θυμού αυτής.","Kai esḗkōsan ton Iōnán kai érripsan autón eis tēn thálassan kai ē thálassa estáthē apó tou thymoú autḗs."],[1,16,"Τότε οι άνθρωποι εφοβήθησαν τον Κύριον φόβον μέγαν και προσέφεραν θυσίαν εις τον Κύριον και έκαμον ευχάς.","Tóte oi ánthrōpoi ephobḗthēsan ton Kýrion phóbon mégan kai prosépheran thysían eis ton Kýrion kai ékamon euchás."],[1,17,"Και διέταξε Κύριος μέγα κήτος να καταπίη τον Ιωνάν. Και ήτο ο Ιωνάς εν τη κοιλία του κήτους τρεις ημέρας και τρεις νύκτας.","Kai diétaxe Kýrios méga kḗtos na katapíē ton Iōnán. Kai ḗto o Iōnás en tē koilía tou kḗtous treis ēméras kai treis nýktas."],[2,1,"Και προσηυχήθη Ιωνάς προς Κύριον τον Θεόν αυτού εκ της κοιλίας του κήτους,","Kai prosēychḗthē Iōnás pros Kýrion ton Theón autoú ek tēs koilías tou kḗtous,"],[2,2,"Και είπεν, Εβόησα εν τη θλίψει μου προς τον Κύριον, και εισήκουσέ μου· εκ κοιλίας άδου εβόησα, και ήκουσας της φωνής μου.","Kai eípen, Ebóēsa en tē thlípsei mou pros ton Kýrion, kai eisḗkousé mou: ek koilías ádou ebóēsa, kai ḗkousas tēs phōnḗs mou."],[2,3,"Διότι με έρριψας εις τα βάθη, εις την καρδίαν της θαλάσσης, και ρεύματα με περιεκύκλωσαν· πάσαι αι τρικυμίαι σου και τα κύματά σου διήλθον επάνωθέν μου.","Dióti me érripsas eis ta báthē, eis tēn kardían tēs thalássēs, kai reúmata me periekýklōsan: pásai ai trikymíai sou kai ta kýmatá sou diḗlthon epánōthén mou."],[2,4,"Και εγώ είπα, Απερρίφθην απ' έμπροσθεν των οφθαλμών σου· όμως θέλω επιβλέψει πάλιν εις τον ναόν τον άγιόν σου.","Kai egṓ eípa, Aperríphthēn ap' émprosthen tōn ophthalmṓn sou: ómōs thélō epiblépsei pálin eis ton naón ton ágión sou."],[2,5,"Τα ύδατα με περιεκύκλωσαν έως της ψυχής, η άβυσσος με περιέκλεισε, τα φύκια περιετυλίχθησαν περί την κεφαλήν μου.","Ta ýdata me periekýklōsan éōs tēs psychḗs, ē ábyssos me periékleise, ta phýkia perietylíchthēsan perí tēn kephalḗn mou."],[2,6,"Κατέβην εις τα έσχατα των ορέων· οι μοχλοί της γης είναι επάνωθέν μου διαπαντός· αλλ' ανέβη η ζωή μου από της φθοράς, Κύριε Θεέ μου·","Katébēn eis ta éschata tōn oréōn: oi mochloí tēs gēs eínai epánōthén mou diapantós: all' anébē ē zōḗ mou apó tēs phthorás, Kýrie Theé mou:"],[2,7,"Ενώ ήτο εκλείπουσα εν εμοί η ψυχή μου, ενεθυμήθην τον Κύριον· και η προσευχή μου εισήλθε προς σε, εις τον ναόν τον άγιόν σου.","Enṓ ḗto ekleípousa en emoí ē psychḗ mou, enethymḗthēn ton Kýrion: kai ē proseuchḗ mou eisḗlthe pros se, eis ton naón ton ágión sou."],[2,8,"Οι φυλάττοντες ματαιότητας ψεύδους εγκαταλείπουσι το έλεος αυτών.","Oi phyláttontes mataiótētas pseúdous enkataleípousi to éleos autṓn."],[2,9,"Αλλ' εγώ θέλω θυσιάσει προς σε μετά φωνής αινέσεως· θέλω αποδώσει όσα ηυχήθην· η σωτηρία είναι παρά του Κυρίου.","All' egṓ thélō thysiásei pros se metá phōnḗs ainéseōs: thélō apodṓsei ósa ēychḗthēn: ē sōtēría eínai pará tou Kyríou."],[2,10,"Και προσέταξεν ο Κύριος το κήτος και εξήμεσε τον Ιωνάν επί την ξηράν.","Kai prosétaxen o Kýrios to kḗtos kai exḗmese ton Iōnán epí tēn xērán."],[3,1,"Και έγεινε λόγος Κυρίου προς Ιωνάν εκ δευτέρου, λέγων,","Kai égeine lógos Kyríou pros Iōnán ek deutérou, légōn,"],[3,2,"Σηκώθητι, ύπαγε εις Νινευή, την πόλιν την μεγάλην, και κήρυξον προς αυτήν το κήρυγμα, το οποίον εγώ λαλώ προς σε.","Sēkṓthēti, ýpage eis Nineuḗ, tēn pólin tēn megálēn, kai kḗryxon pros autḗn to kḗrygma, to opoíon egṓ lalṓ pros se."],[3,3,"Και εσηκώθη ο Ιωνάς και υπήγεν εις Νινευή κατά τον λόγον του Κυρίου. Η δε Νινευνή ήτο πόλις μεγάλη σφόδρα, οδού τριών ημερών·","Kai esēkṓthē o Iōnás kai ypḗgen eis Nineuḗ katá ton lógon tou Kyríou. Ē de Nineunḗ ḗto pólis megálē sphódra, odoú triṓn ēmerṓn:"],[3,4,"Και ήρχισεν ο Ιωνάς να διέρχηται εις την πόλιν οδόν μιας ημέρας και εκήρυξε και είπεν, Έτι τεσσαράκοντα ημέραι και η Νινευή θέλει καταστραφή.","Kai ḗrchisen o Iōnás na diérchētai eis tēn pólin odón mias ēméras kai ekḗryxe kai eípen, Éti tessarákonta ēmérai kai ē Nineuḗ thélei katastraphḗ."],[3,5,"Και οι άνδρες της Νινευή επίστευσαν εις τον Θεόν και εκήρυξαν νηστείαν και ενεδύθησαν σάκκους από μεγάλου αυτών έως μικρού αυτών·","Kai oi ándres tēs Nineuḗ epísteusan eis ton Theón kai ekḗryxan nēsteían kai enedýthēsan sákkous apó megálou autṓn éōs mikroú autṓn:"],[3,6,"διότι ο λόγος είχε φθάσει προς τον βασιλέα της Νινευή και εσηκώθη από του θρόνου αυτού και αφήρεσε την στολήν αυτού επάνωθεν εαυτού και εσκεπάσθη με σάκκον και εκάθησεν επί σποδού.","dióti o lógos eíche phthásei pros ton basiléa tēs Nineuḗ kai esēkṓthē apó tou thrónou autoú kai aphḗrese tēn stolḗn autoú epánōthen eautoú kai eskepásthē me sákkon kai ekáthēsen epí spodoú."],[3,7,"Και διεκηρύχθη και εγνωστοποιήθη εν τη Νινευή διά ψηφίσματος του βασιλέως και των μεγιστάνων αυτού και ελαλήθη, οι άνθρωποι και τα κτήνη, οι βόες και τα πρόβατα, να μη γευθώσι μηδέν, μηδέ να βοσκήσωσι, μηδέ ύδωρ να πίωσιν·","Kai diekērýchthē kai egnōstopoiḗthē en tē Nineuḗ diá psēphísmatos tou basiléōs kai tōn megistánōn autoú kai elalḗthē, oi ánthrōpoi kai ta ktḗnē, oi bóes kai ta próbata, na mē geuthṓsi mēdén, mēdé na boskḗsōsi, mēdé ýdōr na píōsin:"],[3,8,"αλλ' άνθρωπος και κτήνος να σκεπασθώσι με σάκκους και να φωνάξωσιν ισχυρώς προς τον Θεόν· και ας επιστρέψωσιν έκαστος από της οδού αυτού της πονηράς και από της αδικίας, ήτις είναι εν ταις χερσίν αυτών.","all' ánthrōpos kai ktḗnos na skepasthṓsi me sákkous kai na phōnáxōsin ischyrṓs pros ton Theón: kai as epistrépsōsin ékastos apó tēs odoú autoú tēs ponērás kai apó tēs adikías, ḗtis eínai en tais chersín autṓn."],[3,9,"Τις εξεύρει αν επιστρέψη και μεταμεληθή ο Θεός και επιστρέψη από της οργής του θυμού αυτού και δεν απολεσθώμεν;","Tis exeúrei an epistrépsē kai metamelēthḗ o Theós kai epistrépsē apó tēs orgḗs tou thymoú autoú kai den apolesthṓmen?"],[3,10,"Και είδεν ο Θεός τα έργα αυτών, ότι επέστρεψαν από της οδού αυτών της πονηράς· και μετεμελήθη ο Θεός περί του κακού, το οποίον είπε να κάμη εις αυτούς· και δεν έκαμεν αυτό.","Kai eíden o Theós ta érga autṓn, óti epéstrepsan apó tēs odoú autṓn tēs ponērás: kai metemelḗthē o Theós perí tou kakoú, to opoíon eípe na kámē eis autoús: kai den ékamen autó."],[4,1,"Και ελυπήθη ο Ιωνάς λύπην μεγάλην και ηγανάκτησε.","Kai elypḗthē o Iōnás lýpēn megálēn kai ēganáktēse."],[4,2,"Και προσηυχήθη προς τον Κύριον και είπεν, Ω Κύριε, δεν ήτο ούτος ο λόγος μου, ενώ έτι ήμην εν τη πατρίδι μου; διά τούτο προέλαβον να φύγω εις Θαρσείς· διότι εγνώριζον ότι συ είσαι Θεός ελεήμων και οικτίρμων, μακρόθυμος και πολυέλεος και μετανοών διά το κακόν.","Kai prosēychḗthē pros ton Kýrion kai eípen, Ō Kýrie, den ḗto oútos o lógos mou, enṓ éti ḗmēn en tē patrídi mou? diá toúto proélabon na phýgō eis Tharseís: dióti egnṓrizon óti sy eísai Theós eleḗmōn kai oiktírmōn, makróthymos kai polyéleos kai metanoṓn diá to kakón."],[4,3,"Και τώρα, Κύριε, λάβε, δέομαί σου, την ψυχήν μου απ' εμού· διότι είναι κάλλιον εις εμέ να αποθάνω παρά να ζω.","Kai tṓra, Kýrie, lábe, déomaí sou, tēn psychḗn mou ap' emoú: dióti eínai kállion eis emé na apothánō pará na zō."],[4,4,"Και είπε Κύριος, Είναι καλόν να αγανακτής;","Kai eípe Kýrios, Eínai kalón na aganaktḗs?"],[4,5,"Και εξήλθεν Ιωνάς από της πόλεως και εκάθησε κατά το ανατολικόν μέρος της πόλεως, και εκεί έκαμεν εις εαυτόν καλύβην και εκάθητο υποκάτω αυτής εν τη σκιά, εωσού ίδη τι έμελλε να γείνη εις την πόλιν.","Kai exḗlthen Iōnás apó tēs póleōs kai ekáthēse katá to anatolikón méros tēs póleōs, kai ekeí ékamen eis eautón kalýbēn kai ekáthēto ypokátō autḗs en tē skiá, eōsoú ídē ti émelle na geínē eis tēn pólin."],[4,6,"Και διέταξε Κύριος ο Θεός κολοκύνθην και έκαμε να αναβή επάνωθεν του Ιωνά, διά να ήναι σκιά υπεράνω της κεφαλής αυτού, διά να ανακουφίση αυτόν από της θλίψεως αυτού. Και εχάρη ο Ιωνάς διά την κολοκύνθην χαράν μεγάλην.","Kai diétaxe Kýrios o Theós kolokýnthēn kai ékame na anabḗ epánōthen tou Iōná, diá na ḗnai skiá yperánō tēs kephalḗs autoú, diá na anakouphísē autón apó tēs thlípseōs autoú. Kai echárē o Iōnás diá tēn kolokýnthēn charán megálēn."],[4,7,"Και διέταξεν ο Θεός σκώληκα, ότε εχάραξεν η αυγή της επαύριον· και επάταξε την κολοκύνθην και εξηράνθη.","Kai diétaxen o Theós skṓlēka, óte echáraxen ē augḗ tēs epaúrion: kai epátaxe tēn kolokýnthēn kai exēránthē."],[4,8,"Και καθώς ανέτειλεν ο ήλιος, διέταξεν ο Θεός άνεμον ανατολικόν καυστικόν· και προσέβαλεν ο ήλιος επί την κεφαλήν του Ιωνά, ώστε ώλιγοψύχησε· και εζήτησεν εν τη ψυχή αυτού να αποθάνη, και είπεν, Είναι κάλλιον εις εμέ να αποθάνω παρά να ζω.","Kai kathṓs anéteilen o ḗlios, diétaxen o Theós ánemon anatolikón kaustikón: kai prosébalen o ḗlios epí tēn kephalḗn tou Iōná, ṓste ṓligopsýchēse: kai ezḗtēsen en tē psychḗ autoú na apothánē, kai eípen, Eínai kállion eis emé na apothánō pará na zō."],[4,9,"Και είπεν ο Θεός προς τον Ιωνάν, είναι καλόν να αγανακτής διά την κολοκύνθην; Και είπε, Καλόν είναι να αγανακτώ έως θανάτου.","Kai eípen o Theós pros ton Iōnán, eínai kalón na aganaktḗs diá tēn kolokýnthēn? Kai eípe, Kalón eínai na aganaktṓ éōs thanátou."],[4,10,"Και είπε Κύριος, Συ ελυπήθης υπέρ της κολοκύνθης, διά την οποίαν δεν εκοπίασας, αλλ' ουδέ έκαμες αυτήν να αυξήση, ήτις εγεννήθη εν μιά νυκτί και εν μιά νυκτί εχάθη.","Kai eípe Kýrios, Sy elypḗthēs ypér tēs kolokýnthēs, diá tēn opoían den ekopíasas, all' oudé ékames autḗn na auxḗsē, ḗtis egennḗthē en miá nyktí kai en miá nyktí echáthē."],[4,11,"Και εγώ δεν έπρεπε να λυπηθώ υπέρ της Νινευή, της πόλεως της μεγάλης, εν ή υπάρχουσι πλειότεροι των δώδεκα μυριάδων ανθρώπων, οίτινες δεν διακρίνουσι την δεξιάν αυτών από της αριστεράς αυτών, και κτήνη πολλά;","Kai egṓ den éprepe na lypēthṓ ypér tēs Nineuḗ, tēs póleōs tēs megálēs, en ḗ ypárchousi pleióteroi tōn dṓdeka myriádōn anthrṓpōn, oítines den diakrínousi tēn dexián autṓn apó tēs aristerás autṓn, kai ktḗnē pollá?"]],"grc-swete":[[1,1,"ΚΑΙ ἐγένετο λόγος Κυρίου πρὸς Ἰωνᾶν τὸν τοῦ Ἀμαθεὶ λέγων,","KAI egéneto lógos Kyríou pròs Iōnân tòn toû Amatheì légōn,"],[1,2,"ʼἈνάστηθι καὶ πορεύθητι εἰς Νινευὴ τὴν πόλιν τὴν μεγάλην καὶ κήρυξον ἐν αὐτῇ, ὅτι ἀνέβη ἡ κραυγὴ τῆς κακίας αὐτῆς πρὸς μέ.","ʼAnástēthi kaì poreúthēti eis Nineuḕ tḕn pólin tḕn megálēn kaì kḗryxon en autē̂i, hóti anébē hē kraugḕ tē̂s kakías autē̂s pròs mé."],[1,3,"καὶ ἀνέστη Ἰωνᾶς τοῦ φυγεῖν εἰς Θαρσεὶς ἐκ προσώπου Κυρίου, καὶ κατέβη εἰς Ἰόππην· καὶ εὗρεν πλοῖον βαδίζον εἰς Θαρσείς, καὶ ἔδωκεν τὸ ναῦλον αὐτοῦ καὶ ἐνέβη εἰς αὐτὸ τοῦ πλεῦσαι μετʼ αὐτῶν εἰς Θαρσεὶς ἐκ προσώπου Κυρίου.","kaì anéstē Iōnâs toû phygeîn eis Tharseìs ek prosṓpou Kyríou, kaì katébē eis Ióppēn: kaì heûren ploîon badízon eis Tharseís, kaì édōken tò naûlon autoû kaì enébē eis autò toû pleûsai metʼ autō̂n eis Tharseìs ek prosṓpou Kyríou."],[1,4,"Καὶ Κύριος ἐξήγειρεν πνεῦμα ἐπὶ τὴν θάλασσαν, καὶ ἐγένετο κλύδων μέγας ἐν τῇ θαλάσσῃ, καὶ τὸ πλοῖον ἐκινδύνευεν συντριβῆναι.","Kaì Kýrios exḗgeiren pneûma epì tḕn thálassan, kaì egéneto klýdōn mégas en tē̂i thalássēi, kaì tò ploîon ekindýneuen syntribē̂nai."],[1,5,"καὶ ἐφοβήθησαν οἱ ναυτικοὶ καὶ ἀνεβόησαν ἕκαστος πρὸς τὸν θεὸν αὐτοῦ, καὶ ἐκβολὴν ἐποιήσαντο τῶν σκευῶν τῶν ἐν τῷ πλοίῳ εἰς τὴν θάλασσαν, τοῦ κουφισθῆναι ἀπʼ αὐτῶν· Ἰωνᾶς δὲ κατέβη εἰς τὴν κοίλην τοῦ πλοίου, καὶ ἐκάθευδεν καὶ ἔρεγχεν.","kaì ephobḗthēsan hoi nautikoì kaì anebóēsan hékastos pròs tòn theòn autoû, kaì ekbolḕn epoiḗsanto tō̂n skeuō̂n tō̂n en tō̂i ploíōi eis tḕn thálassan, toû kouphisthē̂nai apʼ autō̂n: Iōnâs dè katébē eis tḕn koílēn toû ploíou, kaì ekátheuden kaì érenchen."],[1,6,"καὶ προσῆλθεν πρὸς αὐτὸν ὁ πρωρεὺς καὶ εἶπεν αὐτῷ Τί σὺ ῥέγχεις; ἀνάστα καὶ ἐπικαλοῦ τὸν θεόν σου, ὅπως διασώσῃ ὁ θεὸς ἡμᾶς καὶ μὴ ἀπολώμεθα.","kaì prosē̂lthen pròs autòn ho prōreùs kaì eîpen autō̂i Tí sỳ rhéncheis? anásta kaì epikaloû tòn theón sou, hópōs diasṓsēi ho theòs hēmâs kaì mḕ apolṓmetha."],[1,7,"καὶ εἶπευ ἕκαστος πρὸς τὸν πλησίον αὐτοῦ Δεῦτε βάλωμεν κλήρους καὶ ἐπιγνῶμεν τίνος ἕνεκεν ἡ κακία αὕτη ἐστὶν ἐν ἡμῖν. καὶ ἔβαλον κλήρους. καὶ ἔπεσεν ὁ κλῆρος ἐπὶ Ἰωνᾶν.","kaì eîpeu hékastos pròs tòn plēsíon autoû Deûte bálōmen klḗrous kaì epignō̂men tínos héneken hē kakía haútē estìn en hēmîn. kaì ébalon klḗrous. kaì épesen ho klē̂ros epì Iōnân."],[1,8,"καὶ εἶπον πρὸς αὐτόν Ἀπάγγειλον ἡμῖν τίς σου ἡ ἐργασία ἐστίν, καὶ πόθεν ἔρχῃ. καὶ ἐκ ποίας χώρας καὶ ἐκ ποίου λαοῦ εἶ σύ;","kaì eîpon pròs autón Apángeilon hēmîn tís sou hē ergasía estín, kaì póthen érchēi. kaì ek poías chṓras kaì ek poíou laoû eî sý?"],[1,9,"καὶ εἶπεν πρὸς αὐτούς Δοῦλος Κυρίου ἐγὼ εἰμι, καὶ τὸν κύριον θεὸν τοῦ οὐρανοῦ ἐγῶ σέβομαι, ὃς ἐποίησεν τὴν θάλασσαν καὶ τὴν ξηράν.","kaì eîpen pròs autoús Doûlos Kyríou egṑ eimi, kaì tòn kýrion theòn toû ouranoû egō̂ sébomai, hòs epoíēsen tḕn thálassan kaì tḕn xērán."],[1,10,"καὶ ἐφοβήθησαν οἱ ἄνδρες φόβον μέγαν καὶ εἶπαν πρὸς αὐτόν Τί τοῦτο ἐποίησας; διότι ἔγνωσαν οἱ ἄνδρες ὅτι ἐκ προσώπου Κυρίου ἦν φεύγων, ὅτι ἀπήγγειλεν αὐτοῖς.","kaì ephobḗthēsan hoi ándres phóbon mégan kaì eîpan pròs autón Tí toûto epoíēsas? dióti égnōsan hoi ándres hóti ek prosṓpou Kyríou ē̂n pheúgōn, hóti apḗngeilen autoîs."],[1,11,"καὶ εἶπαν πρὸς αὐτόν Τί σοι ποιήσομεν, καὶ κοπάσει ἡ θάλασσα ἀφʼ ἡμῶν; ὅτι ἡ θάλασσα ἐπορεύετο καὶ ἐξήγειρεν μᾶλλον κλύδωνα.","kaì eîpan pròs autón Tí soi poiḗsomen, kaì kopásei hē thálassa aphʼ hēmō̂n? hóti hē thálassa eporeúeto kaì exḗgeiren mâllon klýdōna."],[1,12,"καὶ εἶπεν Ἰωνᾶς πρὸς αὐτούς Ἄρατέ με καὶ ἐμβάλετέ με εἰς τὴν θάλασσαν, καὶ κοπάσει ἡ θάλασσα ἀφʼ ὑμῶν· διότι ἔγνωκα ἐγὼ ὅτι δι᾿ ἐμὲ ὁ κλύδων ὁ μέγας οὗτος ἐφʼ ὑμᾶς ἐστίν.","kaì eîpen Iōnâs pròs autoús Áraté me kaì embáleté me eis tḕn thálassan, kaì kopásei hē thálassa aphʼ hymō̂n: dióti égnōka egṑ hóti di᾿ emè ho klýdōn ho mégas hoûtos ephʼ hymâs estín."],[1,13,"καὶ παρεβιάζοντο οἱ ἄνδρες τοῦ ἐπιστρέψαι πρὸς τὴν γῆν, καὶ οὐκ ἡδύναντο, ὅτι ἡ θάλασσα ἐπορεύετο καὶ ἐξηγείρετο μᾶλλον ἐπʼ αὐτούς.","kaì parebiázonto hoi ándres toû epistrépsai pròs tḕn gē̂n, kaì ouk hēdýnanto, hóti hē thálassa eporeúeto kaì exēgeíreto mâllon epʼ autoús."],[1,14,"καὶ ἀνεβόησαν πρὸς Κύριον καὶ εἶπαν Μηδαμῶς, Κύριε· μὴ ἀπολώμεθα ἕνεκεν τῆς ψυχῆς τοῦ ἀνθρώπου τούτου, καὶ μὴ δῷς ἐφʼ ἡμᾶς αἷμα δίκαιον, διότι σύ, Κύριε, ὃν τρόπον ἐβούλου πεποίηκας.","kaì anebóēsan pròs Kýrion kaì eîpan Mēdamō̂s, Kýrie: mḕ apolṓmetha héneken tē̂s psychē̂s toû anthrṓpou toútou, kaì mḕ dō̂is ephʼ hēmâs haîma díkaion, dióti sý, Kýrie, hòn trópon eboúlou pepoíēkas."],[1,15,"καὶ ἔλαβον τὸν Ἰωνᾶν καὶ ἐξέβαλον αὐτὸν εἰς τὴν θάλασσαν, καὶ ἔστη ἡ θάλασσα ἐκ τοῦ σάλου αὐτῆς.","kaì élabon tòn Iōnân kaì exébalon autòn eis tḕn thálassan, kaì éstē hē thálassa ek toû sálou autē̂s."],[1,16,"καὶ ἐφοβήθησαν οἱ ἄνδρες φόβῳ μεγάλῳ τὸν κύριον, καὶ ἔθυσαν θυσίας τῷ κυρίῳ καὶ εὔξαντο εὐχάς.","kaì ephobḗthēsan hoi ándres phóbōi megálōi tòn kýrion, kaì éthysan thysías tō̂i kyríōi kaì eúxanto euchás."],[2,1,"Καὶ προσέταξεν Κύριος κήτει μεγάλῳ καταπιεῖν τὸν Ἰωνᾶν· καὶ ἦν Ἰωνᾶς ἐν τῇ κοιλίᾳ τοῦ κήτους τρεῖς ἡμέρας καὶ τρεῖς νύκτας.","Kaì prosétaxen Kýrios kḗtei megálōi katapieîn tòn Iōnân: kaì ē̂n Iōnâs en tē̂i koilíāi toû kḗtous treîs hēméras kaì treîs nýktas."],[2,2,"καὶ προσηύξατο Ἰωνᾶς πρὸς Κύριον τὸν θεὸν αὐτοῦ ἐκ τῆς κοιλίας τοῦ κήτους,","kaì prosēýxato Iōnâs pròs Kýrion tòn theòn autoû ek tē̂s koilías toû kḗtous,"],[2,3,"καὶ εἶπεν Ἐβόησα ἐν θλίψει μου πρὸς Κύριον τὸν θεόν μου, καὶ εἰσήκουσέν μου. ἐκ κοιλίας ᾅδου κραυγῆς μου ἤκουσας φωνῆς μου·","kaì eîpen Ebóēsa en thlípsei mou pròs Kýrion tòn theón mou, kaì eisḗkousén mou. ek koilías hā́idou kraugē̂s mou ḗkousas phōnē̂s mou:"],[2,4,"⁴ἀπέρριψάς με εἰς βάθη καρδίας θαλάσσης, καὶ ποταμοί με ἐκύκλωσαν, πάντες οἱ μετεωρισμοί σου καὶ τὰ κύματά σου ἐπʼ ἐμὲ διῆλθον.","⁴apérripsás me eis báthē kardías thalássēs, kaì potamoí me ekýklōsan, pántes hoi meteōrismoí sou kaì tà kýmatá sou epʼ emè diē̂lthon."],[2,5,"⁵καὶ ἐγώ εἶπα Ἀπῶσμαι ἐξ ὀφθαλμῶν σου· ἆρα προσθήσω τοῦ ἐπιβλέψαι πρὸς τὸν λαὸν τὸν ἅγιόν σου;","⁵kaì egṓ eîpa Apō̂smai ex ophthalmō̂n sou: âra prosthḗsō toû epiblépsai pròs tòn laòn tòn hágión sou?"],[2,6,"⁶περιεχύθη ὕδωρ μοι ἕως ψυχῆς. ἄβυσσος ἐκύκλωσέν με ἐσχάτη, ἔδυ ἡ κεφαλή μου εἰς σχισμὰς ὀρέων,","⁶periechýthē hýdōr moi héōs psychē̂s. ábyssos ekýklōsén me eschátē, édy hē kephalḗ mou eis schismàs oréōn,"],[2,7,"⁷κατέβην εἰς γῆν ἧς οἱ μοχλοὶ αὐτῆς κάτοχοι αἰώνιοι· καὶ ἀναβήτω φθορὰ ζωῆς μου, Κύριε ὁ θεός μου,","⁷katébēn eis gē̂n hē̂s hoi mochloì autē̂s kátochoi aiṓnioi: kaì anabḗtō phthorà zōē̂s mou, Kýrie ho theós mou,"],[2,8,"8ἐν τῷ ἐκλιπεῖν ἀπʼ ἐμοῦ τὴν ψυχήν μου τοῦ κυρίου ἐμνήσθην, καὶ ἔλθοι πρὸς σὲ ἡ εὐχή μου εἰς ναὸν ἅγιόν σου.","8en tō̂i eklipeîn apʼ emoû tḕn psychḗn mou toû kyríou emnḗsthēn, kaì élthoi pròs sè hē euchḗ mou eis naòn hágión sou."],[2,9,"⁹φυλασσόμενοι μάταια καὶ ψευδῆ ἔλεος αὐτῶν ἐγκατέλιπον.","⁹phylassómenoi mátaia kaì pseudē̂ éleos autō̂n enkatélipon."],[2,10,"¹⁰ἐγὼ δὲ μετὰ φωνῆς αἰνέσεως καὶ ἐξομολογήσεως θύσω σοι, ὅσα ηὐξάμην ἀποδώσω σοι σωτηρίου τῷ κυρίῳ.","¹⁰egṑ dè metà phōnē̂s ainéseōs kaì exomologḗseōs thýsō soi, hósa ēyxámēn apodṓsō soi sōtēríou tō̂i kyríōi."],[2,11,"¹¹Καὶ προσετάγη τῷ κήτει, καὶ ἐξέβαλεν τὸν Ἰωνᾶν ἐπὶ τὴν ξηράν.","¹¹Kaì prosetágē tō̂i kḗtei, kaì exébalen tòn Iōnân epì tḕn xērán."],[3,1,"Καὶ ἐγένετο λόγος Κυρίου πρὸς Ἰωνᾶν ἐκ δευτέρου λέγων","Kaì egéneto lógos Kyríou pròs Iōnân ek deutérou légōn"],[3,2,"Ἀνάστηθι πορεύθητι εἰς Νινευὴ τὴν πόλιν τὴν μεγάλην, καὶ κήρυξον ἐν αὐτῇ κατὰ τὸ κήρυγμα τὸ ἔμπροσθεν ὃ ἐγὼ ἐλάλησα πρὸς σέ.","Anástēthi poreúthēti eis Nineuḕ tḕn pólin tḕn megálēn, kaì kḗryxon en autē̂i katà tò kḗrygma tò émprosthen hò egṑ elálēsa pròs sé."],[3,3,"καὶ ἀνέστη Ἰωνᾶς καὶ ἐπορεύθη εἰς Νινευή, καθὰ ἐλάλησεν Κύριος· ἡ δὲ Νινευὴ ἦν πόλις μεγάλη τῷ θεῷ, ὡσεὶ πορείας ὁδοῦ ἡμερῶν τριῶν.","kaì anéstē Iōnâs kaì eporeúthē eis Nineuḗ, kathà elálēsen Kýrios: hē dè Nineuḕ ē̂n pólis megálē tō̂i theō̂i, hōseì poreías hodoû hēmerō̂n triō̂n."],[3,4,"καὶ ἤρξατο Ἰωνᾶς τοῦ εἰσελθεῖν εἰς τὴν πόλιν ὡσεὶ πορείαν ἡμέρας μιᾶς, καὶ ἐκήρυξεν καὶ εἶπεν Ἔτι τρεῖς ἡμέραι καὶ Νινευὴ καταστραφήσεται.","kaì ḗrxato Iōnâs toû eiseltheîn eis tḕn pólin hōseì poreían hēméras miâs, kaì ekḗryxen kaì eîpen Éti treîs hēmérai kaì Nineuḕ katastraphḗsetai."],[3,5,"καὶ ἐνεπίστευσαν οἱ ἄνδρες Νινευὴ τῷ θεῷ, καὶ ἐκήρυξαν νηστίαν, καὶ ἐνεδύσαντο σάκκους ἀπὸ μεγάλου αὐτῶν ἕως μικροῦ αὐτῶν.","kaì enepísteusan hoi ándres Nineuḕ tō̂i theō̂i, kaì ekḗryxan nēstían, kaì enedýsanto sákkous apò megálou autō̂n héōs mikroû autō̂n."],[3,6,"καὶ ἤγγισεν ὁ λόγος πρὸς τὸν βασιλέα τῆς Νινευή· καὶ ἐξανέστη ἀπὸ τοῦ θρόνου αὐτοῦ, καὶ περιείλατο τὴν στολὴν αὐτοῦ ἀφʼ ἑαυτοῦ καὶ περιεβάλετο σάκκον, καὶ ἐκάθισεν ἐπὶ σποδοῦ.","kaì ḗngisen ho lógos pròs tòn basiléa tē̂s Nineuḗ: kaì exanéstē apò toû thrónou autoû, kaì perieílato tḕn stolḕn autoû aphʼ heautoû kaì periebáleto sákkon, kaì ekáthisen epì spodoû."],[3,7,"καὶ ἐκηρύχθη καὶ ἐρρέθη ἐν τῇ Νινευὴ παρὰ τοῦ βασιλέως καὶ παρὰ τῶν μεγιστάνων αὐτοῦ λέγων Οἱ ἄνθρωποι καὶ τὰ κτήνη καὶ οἱ βόες καὶ τὰ πρόβατα μὴ γευσάσθωσαν μηδὲν μηδὲ νεμέσθωσαν μηδὲ ὕδωρ πιέτωσαν.","kaì ekērýchthē kaì erréthē en tē̂i Nineuḕ parà toû basiléōs kaì parà tō̂n megistánōn autoû légōn Hoi ánthrōpoi kaì tà ktḗnē kaì hoi bóes kaì tà próbata mḕ geusásthōsan mēdèn mēdè nemésthōsan mēdè hýdōr piétōsan."],[3,8,"καὶ περιεβάλοντο σάκκους οἱ ἄνθρωποι καὶ τὰ κτήνη, καὶ ἀνεβόησαν πρὸς τὸν θεὸν ἐκτενῶς· καὶ ἀπέστρεψαν ἕκαστος ἀπὸ τῆς ὁδοῦ αὐτοῦ τῆς πονηρᾶς καὶ ἀπὸ τῆς ἀδικίας τῆς ἐν χερσὶν αὐτῶν, λέγοντες","kaì periebálonto sákkous hoi ánthrōpoi kaì tà ktḗnē, kaì anebóēsan pròs tòn theòn ektenō̂s: kaì apéstrepsan hékastos apò tē̂s hodoû autoû tē̂s ponērâs kaì apò tē̂s adikías tē̂s en chersìn autō̂n, légontes"],[3,9,"Τίς οἶδεν εἰ μετανοήσει ὁ θεὸς καὶ ἀποστρέψει ἐξ ὀργῆς θυμοῦ αὐτοῦ, καὶ οὐ μὴ ἀπολώμεθα;","Tís oîden ei metanoḗsei ho theòs kaì apostrépsei ex orgē̂s thymoû autoû, kaì ou mḕ apolṓmetha?"],[3,10,"καὶ εἶδεν ὁ θεὸς τὰ ἔργα αὐτῶν, ὅτι ἀπέστρεψαν ἀπὸ τῶν ὁδῶν αὐτῶν τῶν πονηρῶν· καὶ μετενόησεν ὁ θεὸς ἐπὶ τῇ κακίᾳ ᾗ ἐλάλησεν τοῦ ποιῆσαι αὐτοῖς, καὶ οὐκ ἐποίησεν.","kaì eîden ho theòs tà érga autō̂n, hóti apéstrepsan apò tō̂n hodō̂n autō̂n tō̂n ponērō̂n: kaì metenóēsen ho theòs epì tē̂i kakíāi hē̂i elálēsen toû poiē̂sai autoîs, kaì ouk epoíēsen."],[4,1,"Καὶ ἐλυπήθη Ἰωνᾶς λύπην μεγάλην, καὶ συνεχύθη·","Kaì elypḗthē Iōnâs lýpēn megálēn, kaì synechýthē:"],[4,2,"καὶ προσεύξατο πρὸς Κύριον καὶ εἶπεν Ὦ Κύριε, οὐχ οὗτοι οἱ λόγοι μου, ἔτι ὄντος μου ἐν τῇ γῇ μου διὰ τοῦτο προέφθασα τοῦ φυγεῖν εἰς Θαρσείς, διότι ἔγνων ὅτι σὺ ἐλεήμων καὶ οἰκτίρμων, μακρόθυμος καὶ πολυέλεος καὶ μετανοῶν ἐπὶ ταῖς κακίαις.","kaì proseúxato pròs Kýrion kaì eîpen Ō̂ Kýrie, ouch hoûtoi hoi lógoi mou, éti óntos mou en tē̂i gē̂i mou dià toûto proéphthasa toû phygeîn eis Tharseís, dióti égnōn hóti sỳ eleḗmōn kaì oiktírmōn, makróthymos kaì polyéleos kaì metanoō̂n epì taîs kakíais."],[4,3,"καὶ νῦν, δέσποτα Κύριε, λάβε τὴν ψυχήν μου ἀπʼ ἐμοῦ, ὅτι καλὸν τὸ ἀποθανεῖν με ἢ ζῇν με.","kaì nŷn, déspota Kýrie, lábe tḕn psychḗn mou apʼ emoû, hóti kalòn tò apothaneîn me ḕ zē̂in me."],[4,4,"καὶ εἶπεν Κύριος πρὸς Ἰωνᾶν Εἰ σφόδρα λελύπησαι σύ;","kaì eîpen Kýrios pròs Iōnân Ei sphódra lelýpēsai sý?"],[4,5,"καὶ ἐξῆλθεν Ἰωνᾶς ἐκ τῆς πόλεως, καὶ ἐκάθισεν ἀπέναντι τῆς πόλεως· καὶ ἐποίησεν ἑαυτῷ ἐκεῖ σκηνὴν καὶ ἐκάθητο ὑποκάτω αὐτῆς ἐν σκιῷ, ἕως οὗ ἀπίδῃ τί ἔσται τῇ πόλει.","kaì exē̂lthen Iōnâs ek tē̂s póleōs, kaì ekáthisen apénanti tē̂s póleōs: kaì epoíēsen heautō̂i ekeî skēnḕn kaì ekáthēto hypokátō autē̂s en skiō̂i, héōs hoû apídēi tí éstai tē̂i pólei."],[4,6,"καὶ προσέταξεν Κύριος ὁ θεὸς κολοκύνθῃ, καὶ ἀνέβη ὑπὲρ κεφαλῆς τοῦ Ἰωνᾶ τοῦ εἶναι σκιὰν ὑπεράνω τῆς κεφαλῆς αὐτοῦ, τοῦ σκιάζειν αὐτῷ ἀπὸ τῶν κακῶν αὐτοῦ· καὶ ἐχάρη Ἰωνᾶς ἐπὶ τῇ κολοκύνθῃ χαρὰν μεγάλην.","kaì prosétaxen Kýrios ho theòs kolokýnthēi, kaì anébē hypèr kephalē̂s toû Iōnâ toû eînai skiàn hyperánō tē̂s kephalē̂s autoû, toû skiázein autō̂i apò tō̂n kakō̂n autoû: kaì echárē Iōnâs epì tē̂i kolokýnthēi charàn megálēn."],[4,7,"καὶ προσέταξεν ὁ θεὸς σκώληκι ἑωθινῇ τῇ ἐπαύριον, καὶ ἐπάταξεν τὴν κολοκύνθαν, καὶ ἀπεξηράνθη.","kaì prosétaxen ho theòs skṓlēki heōthinē̂i tē̂i epaúrion, kaì epátaxen tḕn kolokýnthan, kaì apexēránthē."],[4,8,"καὶ ἐγένετο ἅμα τῷ ἀνατεῖλαι τὸν ἥλιον καὶ προσέταξεν ὁ θεὸς πνεύματι καύσωνος συνκαίοντι, καὶ ἐπάταξεν ὁ ἥλιος ἐπὶ τὴν κεφαλὴν Ἰωνᾶ· καὶ ὠλιγοψύχησεν καὶ ἀπελέγετο τὴν ψυχὴν αὐτοῦ, καὶ εἶπεν Καλόν μοι ἀποθανεῖν με ἢ ζῇν.","kaì egéneto háma tō̂i anateîlai tòn hḗlion kaì prosétaxen ho theòs pneúmati kaúsōnos syn'kaíonti, kaì epátaxen ho hḗlios epì tḕn kephalḕn Iōnâ: kaì ōligopsýchēsen kaì apelégeto tḕn psychḕn autoû, kaì eîpen Kalón moi apothaneîn me ḕ zē̂in."],[4,9,"καὶ εἶπεν ὁ θεὸς πρὸς Ἰωνᾶν Εἰ σφόδρα λελύπησαι σὺ ἐπὶ τῇ κολοκύνθῃ; καὶ εἶπεν Σφόδρα λελύπημαι ἐγὼ ἕως θανάτου.","kaì eîpen ho theòs pròs Iōnân Ei sphódra lelýpēsai sỳ epì tē̂i kolokýnthēi? kaì eîpen Sphódra lelýpēmai egṑ héōs thanátou."],[4,10,"καὶ εἶπεν Κύριος Σὺ ἐφείσω ὑπὲρ τῆς κολοκύνθης, ὑπὲρ ἧς οὐκ ἐκακοπάθησας ἐπʼ αὐτήν, καὶ οὐκ ἐξέθρεψας αὐτήν, ἣ ἐγενήθη ὑπὸ νύκτα καὶ ὑπὸ νύκτα ἀπώλετο.","kaì eîpen Kýrios Sỳ epheísō hypèr tē̂s kolokýnthēs, hypèr hē̂s ouk ekakopáthēsas epʼ autḗn, kaì ouk exéthrepsas autḗn, hḕ egenḗthē hypò nýkta kaì hypò nýkta apṓleto."],[4,11,"ἐγὼ δὲ οὐ φείσομαι ὑπὲρ Νινευὴ τῆς πόλεως τῆς μεγάλης, ἐν ᾗ κατοικοῦσιν πλείους δώδεκα μυριάδες ἀνθρώπων, οἵτινες οὐκ ἔγνωσαν δεξιὰν αὐτῶν ἢ ἀριστερὰν αὐτῶν, καὶ κτήνη πολλά;","egṑ dè ou pheísomai hypèr Nineuḕ tē̂s póleōs tē̂s megálēs, en hē̂i katoikoûsin pleíous dṓdeka myriádes anthrṓpōn, hoítines ouk égnōsan dexiàn autō̂n ḕ aristeràn autō̂n, kaì ktḗnē pollá?"]],"chu-elizabeth":[[1,1,"И бысть слово Господне ко Ионе сыну Амафиину, глаголя:","I bystʹ slovo Gospodne ko Ione synu Amafiinu, glagolâ:"],[1,2,"востани и иди в Ниневию град великий и проповеждь в нем, яко взыде вопль злобы его ко Мне.","vostani i idi v Nineviû grad velikij i propoveždʹ v nem, âko vzyde voplʹ zloby ego ko Mne."],[1,3,"И воста Иона, еже бежати в Фарсис от лица Господня и сниде во Июппию и обрете корабль идущь в Фарсис, и даде наем свой и вниде в онь плыти с ними в Фарсис от лица Господня.","I vosta Iona, eže bežati v Farsis ot lica Gospodnâ i snide vo Iûppiû i obrete korablʹ iduŝʹ v Farsis, i dade naem svoj i vnide v onʹ plyti s nimi v Farsis ot lica Gospodnâ."],[1,4,"И Господь воздвиже ветр велий на мори, и бысть буря великая в мори, и корабль бедствоваше еже сокрушитися.","I Gospodʹ vozdviže vetr velij na mori, i bystʹ burâ velikaâ v mori, i korablʹ bedstvovaše eže sokrušitisâ."],[1,5,"И убояшася корабельницы, и возопиша кийждо к богу своему, и изметание сотвориша сосудов иже в корабли в море, еже облегчитися от них: Иона же сниде во дно корабля и спаше ту и храпляше.","I uboâšasâ korabelʹnicy, i vozopiša kijždo k bogu svoemu, i izmetanie sotvoriša sosudov iže v korabli v more, eže oblegčitisâ ot nih: Iona že snide vo dno korablâ i spaše tu i hraplâše."],[1,6,"И прииде к нему кормчий и рече ему что ты храплеши? Востани и моли Бога твоего, яко да спасет ны Бог, да не погибнем.","I priide k nemu kormčij i reče emu čto ty hrapleši? Vostani i moli Boga tvoego, âko da spaset ny Bog, da ne pogibnem."],[1,7,"И рече кийждо ко искреннему своему приидите, вержим жребия и уразумеем, кого ради есть зло сие на нас? И метнуша жребия, и паде жребий на Иону.","I reče kijždo ko iskrennemu svoemu priidite, veržim žrebiâ i urazumeem, kogo radi estʹ zlo sie na nas? I metnuša žrebiâ, i pade žrebij na Ionu."],[1,8,"И реша к нему возвести нам, кого ради сие зло на нас, что твое делание есть, и откуду грядеши и камо идеши, и от коея страны и от киих людий еси ты?","I reša k nemu vozvesti nam, kogo radi sie zlo na nas, čto tvoe delanie estʹ, i otkudu grâdeši i kamo ideši, i ot koeâ strany i ot kiih lûdij esi ty?"],[1,9,"И рече к ним раб Господень есмь аз и Господа Бога небеснаго аз чту, иже сотвори море и сушу.","I reče k nim rab Gospodenʹ esmʹ az i Gospoda Boga nebesnago az čtu, iže sotvori more i sušu."],[1,10,"И убояшася мужие страхом великим и реша к нему что сие сотворил еси? Зане разумеша мужие, яко от лица Господня бежаше, яко возвести им.","I uboâšasâ mužie strahom velikim i reša k nemu čto sie sotvoril esi? Zane razumeša mužie, âko ot lica Gospodnâ bežaše, âko vozvesti im."],[1,11,"И реша к нему: что тебе сотворим, и утолится море от нас? Зане море восхождаше и воздвизаше паче волнение.","I reša k nemu: čto tebe sotvorim, i utolitsâ more ot nas? Zane more voshoždaše i vozdvizaše pače volnenie."],[1,12,"И рече к ним Иона: возмите мя и вверзите в море, и утолится море от вас понеже познах аз, яко мене ради волнение сие великое на вы есть.","I reče k nim Iona: vozmite mâ i vverzite v more, i utolitsâ more ot vas poneže poznah az, âko mene radi volnenie sie velikoe na vy estʹ."],[1,13,"И нуждахуся мужие, возвратитися к земли, и не можаху, яко море восхождаше и воздвизашеся паче на них.","I nuždahusâ mužie, vozvratitisâ k zemli, i ne možahu, âko more voshoždaše i vozdvizašesâ pače na nih."],[1,14,"И возопиша ко Господеви и реша: никакоже, Господи, да не погибнем души ради человека сего, и не даждь на нас крове праведныя: зане Ты, Господи, якоже восхотел, сотворил еси.","I vozopiša ko Gospodevi i reša: nikakože, Gospodi, da ne pogibnem duši radi čeloveka sego, i ne daždʹ na nas krove pravednyâ: zane Ty, Gospodi, âkože voshotel, sotvoril esi."],[1,15,"И взяша Иону и ввергоша его в море, и преста море от волнения своего.","I vzâša Ionu i vvergoša ego v more, i presta more ot volneniâ svoego."],[1,16,"И убояшася мужие страхом великим Господа и пожроша жертву Господеви и помолишася молитвами.","I uboâšasâ mužie strahom velikim Gospoda i požroša žertvu Gospodevi i pomolišasâ molitvami."],[2,1,"И повеле Господь киту великому пожрети Иону. И бе Иона во чреве китове три дни и три нощи.","I povele Gospodʹ kitu velikomu požreti Ionu. I be Iona vo čreve kitove tri dni i tri noŝi."],[2,2,"И помолися Иона ко Господу Богу своему от чрева китова","I pomolisâ Iona ko Gospodu Bogu svoemu ot čreva kitova"],[2,3,"и рече: возопих в скорби моей ко Господу Богу моему, и услыша мя из чрева адова вопль мой, услышал еси глас мой:","i reče: vozopih v skorbi moej ko Gospodu Bogu moemu, i uslyša mâ iz čreva adova voplʹ moj, uslyšal esi glas moj:"],[2,4,"отвергл мя еси во глубины сердца морскаго, и реки обыдоша мя вся высоты Твоя и волны Твоя мне преидоша.","otvergl mâ esi vo glubiny serdca morskago, i reki obydoša mâ vsâ vysoty Tvoâ i volny Tvoâ mne preidoša."],[2,5,"И аз рех: отринуся от очию Твоею: еда приложу призрети ми ко храму святому Твоему?","I az reh: otrinusâ ot očiû Tvoeû: eda priložu prizreti mi ko hramu svâtomu Tvoemu?"],[2,6,"Возлияся на мя вода до души моея, бездна обыде мя последняя, понре глава моя в разселины гор,","Vozliâsâ na mâ voda do duši moeâ, bezdna obyde mâ poslednââ, ponre glava moâ v razseliny gor,"],[2,7,"снидох в землю, еяже вереи ея заклепи вечнии: и да взыдет из истления живот мой к Тебе, Господи Боже мой.","snidoh v zemlû, eâže verei eâ zaklepi večnii: i da vzydet iz istleniâ život moj k Tebe, Gospodi Bože moj."],[2,8,"Внегда скончаватися от мене души моей, Господа помянух, и да приидет к Тебе молитва моя ко храму святому Твоему.","Vnegda skončavatisâ ot mene duši moej, Gospoda pomânuh, i da priidet k Tebe molitva moâ ko hramu svâtomu Tvoemu."],[2,9,"Хранящии суетная и ложная милость свою оставиша:","Hranâŝii suetnaâ i ložnaâ milostʹ svoû ostaviša:"],[2,10,"аз же со гласом хваления и исповедания пожру Тебе, елика обещах, воздам Тебе во спасение мое Господеви.","az že so glasom hvaleniâ i ispovedaniâ požru Tebe, elika obeŝah, vozdam Tebe vo spasenie moe Gospodevi."],[2,11,"И повеле Господь китови, и изверже Иону на сушу.","I povele Gospodʹ kitovi, i izverže Ionu na sušu."],[3,1,"И бысть слово Господне ко Ионе вторицею глаголя:","I bystʹ slovo Gospodne ko Ione vtoriceû glagolâ:"],[3,2,"востани и иди в Ниневию град великий, и проповеждь в нем по проповеди преждней, юже Аз глаголах тебе.","vostani i idi v Nineviû grad velikij, i propoveždʹ v nem po propovedi preždnej, ûže Az glagolah tebe."],[3,3,"И воста Иона и иде в Ниневию, якоже глагола Господь. Ниневиа же бяше град велик Богу, яко шествия пути триех дний.","I vosta Iona i ide v Nineviû, âkože glagola Gospodʹ. Ninevia že bâše grad velik Bogu, âko šestviâ puti trieh dnij."],[3,4,"И начат Иона входити во град, яко шествие пути дне единаго, и проповеда и рече: еще три дни, и Ниневиа превратится.","I načat Iona vhoditi vo grad, âko šestvie puti dne edinago, i propoveda i reče: eŝe tri dni, i Ninevia prevratitsâ."],[3,5,"И вероваша мужие Ниневийстии Богови, и заповедаша пост, и облекошася во вретища от велика их даже до мала их.","I verovaša mužie Ninevijstii Bogovi, i zapovedaša post, i oblekošasâ vo vretiŝa ot velika ih daže do mala ih."],[3,6,"И дойде слово ко царю Ниневийскому, и воста с престола своего и сверже ризы своя с себе, и облечеся во вретище и седе на пепеле.","I dojde slovo ko carû Ninevijskomu, i vosta s prestola svoego i sverže rizy svoâ s sebe, i oblečesâ vo vretiŝe i sede na pepele."],[3,7,"И проповедася и речено бысть в Ниневию от царя и вельмож его глаголющих: человецы и скоти, и волове и овцы да не вкусят ничесоже, ни да пасутся, ниже воды да пиют.","I propovedasâ i rečeno bystʹ v Nineviû ot carâ i velʹmož ego glagolûŝih: čelovecy i skoti, i volove i ovcy da ne vkusât ničesože, ni da pasutsâ, niže vody da piût."],[3,8,"И облекошася во вретища человецы и скоти и возопиша прилежно к Богу, и возвратися кийждо от пути своего лукаваго и от неправды сущия в руках их, глаголюще:","I oblekošasâ vo vretiŝa čelovecy i skoti i vozopiša priležno k Bogu, i vozvratisâ kijždo ot puti svoego lukavago i ot nepravdy suŝiâ v rukah ih, glagolûŝe:"],[3,9,"кто весть, аще раскается и умолен будет Бог, и обратится от гнева ярости Своея, и не погибнем?","kto vestʹ, aŝe raskaetsâ i umolen budet Bog, i obratitsâ ot gneva ârosti Svoeâ, i ne pogibnem?"],[3,10,"И виде Бог дела их, яко обратишася от путий своих лукавых, и раскаяся Бог о зле, еже глаголаше сотворити им, и не сотвори.","I vide Bog dela ih, âko obratišasâ ot putij svoih lukavyh, i raskaâsâ Bog o zle, eže glagolaše sotvoriti im, i ne sotvori."],[4,1,"И опечалися Иона печалию великою и смутися,","I opečalisâ Iona pečaliû velikoû i smutisâ,"],[4,2,"и помолися ко Господу и рече: о Господи, не сия ли убо словеса моя, яже глаголах, еще сущу ми на земли моей? Сего ради предварих бежати в Фарсис, зане разумех, яко милостив Ты еси и щедр, долготерпелив и многомилостив, и каяйся о злобах (человеческих):","i pomolisâ ko Gospodu i reče: o Gospodi, ne siâ li ubo slovesa moâ, âže glagolah, eŝe suŝu mi na zemli moej? Sego radi predvarih bežati v Farsis, zane razumeh, âko milostiv Ty esi i ŝedr, dolgoterpeliv i mnogomilostiv, i kaâjsâ o zlobah (čelovečeskih):"],[4,3,"и ныне, Владыко Господи, приими душу мою от мене, яко уне ми умрети, нежели жити.","i nyne, Vladyko Gospodi, priimi dušu moû ot mene, âko une mi umreti, neželi žiti."],[4,4,"И рече Господь ко Ионе: аще зело опечалился еси ты?","I reče Gospodʹ ko Ione: aŝe zelo opečalilsâ esi ty?"],[4,5,"И изыде Иона из града и седе прямо града, и сотвори себе кущу и седяще под нею в сени, дондеже увидит, что будет граду.","I izyde Iona iz grada i sede prâmo grada, i sotvori sebe kuŝu i sedâŝe pod neû v seni, dondeže uvidit, čto budet gradu."],[4,6,"И повеле Господь Бог тыкве, и возрасте над главою его, еже осенити его от злых его. И возрадовася Иона о тыкве радостию великою.","I povele Gospodʹ Bog tykve, i vozraste nad glavoû ego, eže oseniti ego ot zlyh ego. I vozradovasâ Iona o tykve radostiû velikoû."],[4,7,"И повеле Господь Бог червию раннему во утрие, и подяде тыкву, и изсше.","I povele Gospodʹ Bog červiû rannemu vo utrie, i podâde tykvu, i izsše."],[4,8,"И бысть вкупе внегда возсияти солнцу, и повеле Бог ветру знойну жегущу, и порази солнце на главу Ионину, и малодушствоваше и отрицашеся души своея и рече:","I bystʹ vkupe vnegda vozsiâti solncu, i povele Bog vetru znojnu žeguŝu, i porazi solnce na glavu Ioninu, i malodušstvovaše i otricašesâ duši svoeâ i reče:"],[4,9,"уне ми умрети, нежели жити. И рече Господь Бог ко Ионе: зело ли опечалился еси ты о тыкве? И рече (Иона): зело опечалихся аз даже до смерти.","une mi umreti, neželi žiti. I reče Gospodʹ Bog ko Ione: zelo li opečalilsâ esi ty o tykve? I reče (Iona): zelo opečalihsâ az daže do smerti."],[4,10,"И рече Господь: ты оскорбился еси о тыкве, о нейже не трудился еси, ни воскормил еси ея, яже родися об нощь и об нощь погибе:","I reče Gospodʹ: ty oskorbilsâ esi o tykve, o nejže ne trudilsâ esi, ni voskormil esi eâ, âže rodisâ ob noŝʹ i ob noŝʹ pogibe:"],[4,11,"Аз же не пощажду ли Ниневии града великаго, в немже живут множайшии неже дванадесять тем человек, иже не познаша десницы своея, ниже шуйцы своея, и скоти их мнози?","Az že ne poŝaždu li Ninevii grada velikago, v nemže živut množajšii neže dvanadesâtʹ tem čelovek, iže ne poznaša desnicy svoeâ, niže šujcy svoeâ, i skoti ih mnozi?"]]}};